create function beta_private.immutable() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'Append-only evidence: insert a linked correction'; end $$;
do $$ declare t text; begin foreach t in array array['tip_publications','settlement_events','correction_events','tip_status_events','audit_events','consent_events','article_revisions','launch_record','validation_runs'] loop execute format('create trigger immutable before update or delete on beta_private.%I for each row execute function beta_private.immutable()',t); end loop; end $$;
create function beta_private.publication_guard() returns trigger language plpgsql set search_path='' as $$
declare e beta_private.events; s beta_private.strategy_versions; r beta_private.region_policies; actor_role text; q jsonb;
begin
 select * into e from beta_private.events where id=new.event_id for share;
 select * into s from beta_private.strategy_versions where id=new.strategy_id for share;
 select * into r from beta_private.region_policies where id=new.region_policy_id for share;
 select role into actor_role from beta_private.roles where user_id=new.approved_by;
 if actor_role is null or actor_role not in ('owner','admin','analyst') then raise exception 'Approval role required'; end if;
 if new.evidence in ('demo','retrospective_backtest') then raise exception 'Demo/backtest cannot enter publication ledger'; end if;
 if e.status<>'scheduled' or e.start_at<=clock_timestamp()+interval '10 minutes' then raise exception 'Event not safely pre-start'; end if;
 if not s.active or s.frozen_at is null or s.research_approved_at is null or new.config_hash<>s.config_hash then raise exception 'Strategy not approved'; end if;
 if new.evidence='live_published' and (s.paper_approved_at is null or s.owner_approved_at is null) then raise exception 'Paper/release approval missing'; end if;
 if not coalesce((select enabled from beta_private.feature_flags where key='publication'),false) then raise exception 'Publication paused'; end if;
 if not r.approved or r.effective_from>now() or r.effective_to<=now() or r.review_at<=now() or not ('tips'=any(r.features)) then raise exception 'Region restricted'; end if;
 if jsonb_array_length(new.sources)<3 then raise exception 'Offer plus two references required'; end if;
 for q in select * from jsonb_array_elements(new.sources) loop
  if (q->>'sourceAt')::timestamptz>clock_timestamp() or (q->>'sourceAt')::timestamptz<clock_timestamp()-interval '3 minutes' then raise exception 'Stale/future evidence'; end if;
 end loop;
 if new.odds<new.minimum_odds or new.estimated_ev<0.03 or new.estimated_ev>0.20 then raise exception 'Price does not qualify'; end if;
 new.published_at=clock_timestamp(); return new;
end $$;
create trigger publication_guard before insert on beta_private.tip_publications for each row execute function beta_private.publication_guard();
create function beta_private.publish_outbox() returns trigger language plpgsql set search_path='' as $$ begin
 insert into beta_private.outbox(dedupe_key,kind,payload,expires_at) values ('publication:'||new.id,'publication',jsonb_build_object('tipId',new.id),new.published_at+interval '3 minutes');
 insert into beta_private.audit_events(actor,action,subject) values (new.approved_by::text,'publish',new.id::text); return new; end $$;
create trigger publication_outbox after insert on beta_private.tip_publications for each row execute function beta_private.publish_outbox();
create function beta_private.no_strategy_rewrite() returns trigger language plpgsql set search_path='' as $$ begin if old.frozen_at is not null and (new.config<>old.config or new.config_hash<>old.config_hash or new.frozen_at is distinct from old.frozen_at) then raise exception 'Frozen configuration is immutable';end if;return new;end $$;
create trigger frozen_strategy before update on beta_private.strategy_versions for each row execute function beta_private.no_strategy_rewrite();

