 started_at timestamptz not null default now(), completed_at timestamptz
);
create index on beta_private.provider_poll_runs(provider,started_at desc);
create function beta_private.candidate_evidence_guard() returns trigger language plpgsql set search_path='' as $$ begin
 if tg_op='DELETE' then raise exception 'Candidate decisions are immutable evidence'; end if;
 if new.event_id<>old.event_id or new.strategy_id<>old.strategy_id or new.decision_at<>old.decision_at or new.window_seconds<>old.window_seconds
 or new.payload<>old.payload or new.rejection_reasons<>old.rejection_reasons
 or (new.status<>old.status and not(old.status='review' and new.status='published')) then raise exception 'Candidate decisions are immutable evidence'; end if;
 return new;
end $$;
create trigger candidate_evidence_guard before update or delete on beta_private.candidate_decisions for each row execute function beta_private.candidate_evidence_guard();
create trigger immutable before update or delete on beta_private.closing_snapshots for each row execute function beta_private.immutable();
create trigger immutable before update or delete on beta_private.availability_observations for each row execute function beta_private.immutable();
