-- All Data API reads require a currently active verified session as well as ownership.
-- This narrow private function exposes a boolean for the caller's own verified JWT only.
create function beta_private.active_member_session() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id
 where s.user_id=(select auth.uid()) and s.id::text=(select auth.jwt()->>'session_id')
 and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false)
 and (s.not_after is null or s.not_after>now()))
$$;
grant usage on schema beta_private to authenticated;
grant execute on function beta_private.active_member_session() to authenticated;
drop policy own_profile on beta_public.profiles;
create policy own_profile on beta_public.profiles for select to authenticated using(
 (select auth.uid())=id and disabled_at is null and (select beta_private.active_member_session()));
drop policy own_preferences on beta_public.notification_preferences;
create policy own_preferences on beta_public.notification_preferences for select to authenticated using(
 (select auth.uid())=user_id and exists(select 1 from beta_public.profiles p where p.id=user_id));
drop policy own_saved on beta_public.saved_tips;
create policy own_saved on beta_public.saved_tips for select to authenticated using(
 (select auth.uid())=user_id and exists(select 1 from beta_public.profiles p where p.id=user_id));
drop policy own_personal on beta_public.personal_entries;
create policy own_personal on beta_public.personal_entries for select to authenticated using(
 (select auth.uid())=user_id and exists(select 1 from beta_public.profiles p where p.id=user_id));

alter table beta_private.strategy_versions add column lifecycle text not null default 'DRAFT' check(lifecycle in
 ('DRAFT','RESEARCH','VALIDATED','FROZEN_FOR_FORWARD_PAPER','FORWARD_PAPER','APPROVED_FOR_LIVE','RETIRED'));
alter table beta_private.strategy_versions add column code_commit text;
alter table beta_private.strategy_versions add column state_changed_at timestamptz not null default now();
-- Existing timestamp approvals are not silently treated as reviewed Phase 2 lifecycle evidence.
update beta_private.strategy_versions set active=false,lifecycle=case when frozen_at is not null then 'RETIRED' else 'DRAFT' end;
insert into beta_private.audit_events(actor,action,subject,details)
 select 'phase2-schema-migration','legacy_strategy_retired',id,jsonb_build_object('reason','Legacy frozen evidence preserved; explicit lifecycle requires a new reviewed version') from beta_private.strategy_versions where frozen_at is not null;
create table beta_private.strategy_transitions (
 id uuid primary key default gen_random_uuid(), strategy_id text not null references beta_private.strategy_versions(id),
 from_state text not null, to_state text not null, actor uuid not null, created_at timestamptz not null default clock_timestamp(),
 strategy_hash text not null, code_commit text not null, reason text not null check(length(reason)>=12),
 validation_run_id uuid references beta_private.validation_runs(id), configuration jsonb not null
);
create trigger immutable before update or delete on beta_private.strategy_transitions for each row execute function beta_private.immutable();
create or replace function beta_private.no_strategy_rewrite() returns trigger language plpgsql set search_path='' as $$
begin
 if old.frozen_at is not null and (new.config<>old.config or new.config_hash<>old.config_hash or new.frozen_at is distinct from old.frozen_at or new.code_commit is distinct from old.code_commit)
 then raise exception 'Frozen configuration is immutable; create a new strategy version'; end if;
 if (new.lifecycle<>old.lifecycle or new.active<>old.active or new.research_approved_at is distinct from old.research_approved_at or new.paper_approved_at is distinct from old.paper_approved_at or new.owner_approved_at is distinct from old.owner_approved_at or new.frozen_at is distinct from old.frozen_at)
 and coalesce(current_setting('docked.strategy_transition',true),'')<>old.id
 then raise exception 'Use the audited strategy transition operation'; end if;
 return new;
end $$;
create function beta_private.transition_strategy(p_id text,p_to text,p_actor uuid,p_reason text,p_commit text,p_run uuid default null)
returns text language plpgsql set search_path='' as $$
declare s beta_private.strategy_versions; v beta_private.validation_runs; valid boolean;
begin
 if not exists(select 1 from beta_private.roles where user_id=p_actor and role in ('owner','admin')) then raise exception 'Administrator role required'; end if;
 if length(p_reason)<12 or p_commit!~'^[0-9a-f]{40}$' then raise exception 'Reason and exact code commit required'; end if;
 select * into s from beta_private.strategy_versions where id=p_id for update;
 if not found then raise exception 'Strategy missing'; end if;
 valid=(s.lifecycle='DRAFT' and p_to='RESEARCH') or (s.lifecycle='RESEARCH' and p_to='VALIDATED')
 or (s.lifecycle='VALIDATED' and p_to='FROZEN_FOR_FORWARD_PAPER') or (s.lifecycle='FROZEN_FOR_FORWARD_PAPER' and p_to='FORWARD_PAPER')
 or (s.lifecycle='FORWARD_PAPER' and p_to='APPROVED_FOR_LIVE') or (s.lifecycle<>'RETIRED' and p_to='RETIRED');
 if not valid then raise exception 'Invalid strategy lifecycle transition'; end if;
 if s.frozen_at is not null and s.code_commit is distinct from p_commit then raise exception 'Frozen code commit mismatch'; end if;
 if p_to='FROZEN_FOR_FORWARD_PAPER' and not coalesce(
  (s.config->>'minEV')::numeric>=0.03 and (s.config->>'minEV')::numeric<=0.20
  and (s.config->>'minOdds')::numeric>=1.5 and (s.config->>'maxOdds')::numeric<=5
  and (s.config->>'minOdds')::numeric<=(s.config->>'maxOdds')::numeric,false)
 then raise exception 'Forward paper requires the 3%% EV release floor and odds within 1.5 to 5; research sensitivity settings cannot be frozen for release'; end if;
 if p_to in ('VALIDATED','APPROVED_FOR_LIVE') then
  select * into v from beta_private.validation_runs where id=p_run and strategy_id=p_id;
  if not found or v.contaminated or v.report='{}'::jsonb or v.code_commit<>p_commit
   or v.manifest->>'configHash' is distinct from s.config_hash or coalesce((v.manifest->>'fixture')::boolean,true)
   or not coalesce((v.report->'validation'->>'valid')::boolean,false)
   or (p_to='VALIDATED' and (v.manifest->'datasetHashes'->>'canonical') is null)
   or (p_to='APPROVED_FOR_LIVE' and not exists(select 1 from beta_private.tip_publications where strategy_id=p_id and evidence='forward_paper'))
   or (p_to='VALIDATED' and v.evidence<>'retrospective_backtest') or (p_to='APPROVED_FOR_LIVE' and v.evidence<>'forward_paper')
  then raise exception 'Matching uncontaminated genuine validation report required'; end if;
 end if;
 perform set_config('docked.strategy_transition',p_id,true);
 update beta_private.strategy_versions set lifecycle=p_to,state_changed_at=clock_timestamp(),code_commit=p_commit,
 frozen_at=case when p_to='FROZEN_FOR_FORWARD_PAPER' then coalesce(frozen_at,clock_timestamp()) else frozen_at end,
 active=p_to in ('FORWARD_PAPER','APPROVED_FOR_LIVE'),
 research_approved_at=case when p_to='VALIDATED' then clock_timestamp() else research_approved_at end,
 paper_approved_at=case when p_to='APPROVED_FOR_LIVE' then clock_timestamp() else paper_approved_at end,
 owner_approved_at=case when p_to='APPROVED_FOR_LIVE' then clock_timestamp() else owner_approved_at end,
 approval_evidence=p_reason where id=p_id;
 insert into beta_private.strategy_transitions(strategy_id,from_state,to_state,actor,strategy_hash,code_commit,reason,validation_run_id,configuration)
 values(p_id,s.lifecycle,p_to,p_actor,s.config_hash,p_commit,p_reason,p_run,s.config);
 perform set_config('docked.strategy_transition','',true);
 return p_to;
end $$;
insert into beta_private.feature_flags(key,reason) values('forward_paper','Private forward paper awaits approved frozen strategy');

-- Renewing a policy must not erase historical losses from that jurisdiction's record.
-- Current recommendations are separately revalidated against current operator/price controls.
create function beta_private.publication_region_matches(published_policy uuid,current_policy uuid) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from beta_private.region_policies old_policy join beta_private.region_policies current_policy_row
 on old_policy.country=current_policy_row.country and old_policy.state=current_policy_row.state
 where old_policy.id=published_policy and current_policy_row.id=current_policy and current_policy_row.approved
 and current_policy_row.effective_from<=now() and current_policy_row.effective_to>now() and current_policy_row.review_at>now()
 and 'tips'=any(current_policy_row.features))
$$;

create or replace function beta_private.publication_guard() returns trigger language plpgsql set search_path='' as $$
declare e beta_private.events; s beta_private.strategy_versions; r beta_private.region_policies; c beta_private.candidate_decisions; actor_role text; q jsonb;
begin
 select * into e from beta_private.events where id=new.event_id for share;
 select * into s from beta_private.strategy_versions where id=new.strategy_id for share;
 select * into r from beta_private.region_policies where id=new.region_policy_id for share;
 select * into c from beta_private.candidate_decisions where id=new.candidate_id for share;
 select role into actor_role from beta_private.roles where user_id=new.approved_by;
 if actor_role is null or actor_role not in ('owner','admin','analyst') then raise exception 'Approval role required'; end if;
 if new.evidence not in ('forward_paper','live_published') then raise exception 'Demo/backtest cannot enter publication ledger'; end if;
 if c.event_id is distinct from new.event_id or c.strategy_id is distinct from new.strategy_id or c.status<>'review'
 or c.decision_at>clock_timestamp() or c.decision_at>=e.start_at then raise exception 'Candidate linkage invalid'; end if;
 if e.status<>'scheduled' or e.start_at<=clock_timestamp()+interval '10 minutes' then raise exception 'Event not safely pre-start'; end if;
 if not s.active or s.frozen_at is null or s.research_approved_at is null or new.config_hash<>s.config_hash then raise exception 'Strategy not approved'; end if;
 if new.evidence='live_published' and (s.lifecycle<>'APPROVED_FOR_LIVE' or s.paper_approved_at is null or s.owner_approved_at is null) then raise exception 'Paper/release approval missing'; end if;
 if new.evidence='forward_paper' and s.lifecycle<>'FORWARD_PAPER' then raise exception 'Strategy not in forward paper'; end if;
 if not coalesce((select enabled from beta_private.feature_flags where key=case when new.evidence='forward_paper' then 'forward_paper' else 'publication' end),false) then raise exception 'Publication paused'; end if;
 if not r.approved or r.effective_from>now() or r.effective_to<=now() or r.review_at<=now() or not ('tips'=any(r.features)) then raise exception 'Region restricted'; end if;
 if jsonb_array_length(new.sources)<3 then raise exception 'Offer plus two references required'; end if;
 if (select count(distinct value->>'operator') from jsonb_array_elements(new.sources))<3 then raise exception 'Independent offer and references required'; end if;
 for q in select * from jsonb_array_elements(new.sources) loop
  if q->'rules' is distinct from new.market_rules then raise exception 'Source market mismatch'; end if;
  if q->>'sourceAt' is null or q->>'snapshotAt' is null or q->>'receivedAt' is null
   or (q->>'sourceAt')::timestamptz>(q->>'snapshotAt')::timestamptz or (q->>'snapshotAt')::timestamptz>(q->>'receivedAt')::timestamptz
   or (q->>'receivedAt')::timestamptz>clock_timestamp() or (q->>'sourceAt')::timestamptz<clock_timestamp()-interval '3 minutes' then raise exception 'Stale/future evidence'; end if;
 end loop;
 if new.odds<new.minimum_odds or new.odds<1.5 or new.odds>5 or new.estimated_ev<greatest((s.config->>'minEV')::numeric,0.03) or new.estimated_ev>0.20
 or new.minimum_odds<ceil((1+greatest((s.config->>'minEV')::numeric,0.03))/new.probability*100)/100 then raise exception 'Price does not qualify'; end if;
 if abs(new.probability*new.odds-1-new.estimated_ev)>0.00000001 then raise exception 'EV/probability mismatch'; end if;
 new.published_at=clock_timestamp(); return new;
end $$;
create or replace function beta_private.publish_outbox() returns trigger language plpgsql set search_path='' as $$ begin
 if new.evidence='live_published' then
  insert into beta_private.outbox(dedupe_key,kind,payload,expires_at) values('publication:'||new.id,'publication',jsonb_build_object('tipId',new.id),new.published_at+interval '3 minutes');
 end if;
 insert into beta_private.audit_events(actor,action,subject,details) values(new.approved_by::text,'publish',new.id::text,jsonb_build_object('evidence',new.evidence));
 return new;
end $$;

-- A correction must point to settlements of the same immutable publication.
create function beta_private.correction_guard() returns trigger language plpgsql set search_path='' as $$ begin
 if new.settlement_id is null or new.replacement_settlement_id is null or new.settlement_id=new.replacement_settlement_id
 or not exists(select 1 from beta_private.settlement_events where id=new.settlement_id and tip_id=new.tip_id)
 or not exists(select 1 from beta_private.settlement_events where id=new.replacement_settlement_id and tip_id=new.tip_id)
 then raise exception 'Correction settlement linkage invalid'; end if;
 return new;
end $$;
create trigger correction_guard before insert on beta_private.correction_events for each row execute function beta_private.correction_guard();

-- Account closure revokes immediately; remote Auth erasure is retried by the durable worker.
-- Pseudonymous consent/publication/audit evidence stays append-only pending legal retention review.
create function beta_private.disable_account(p_user uuid) returns void language plpgsql set search_path='' as $$
begin
 update beta_public.profiles set disabled_at=coalesce(disabled_at,clock_timestamp()) where id=p_user;
 if not found then return; end if;
 update beta_public.notification_preferences set paused=true,digest='off',edge_alerts=false,education=false,updated_at=now() where user_id=p_user;
 update beta_private.outbox set state='suppressed',user_id=null,payload='{}',dedupe_key='erased:'||id::text,last_error='Account erased',lease_token=null,lease_until=null where user_id=p_user;
 update beta_private.delivery_attempts set user_id=null,provider_id=null where user_id=p_user;
 delete from beta_private.analytics_events where user_id=p_user;
 delete from beta_private.unsubscribe_tokens where user_id=p_user;
 delete from beta_public.saved_tips where user_id=p_user;
 delete from beta_public.personal_entries where user_id=p_user;
 delete from auth.sessions where user_id=p_user;
 insert into beta_private.job_runs(dedupe_key,kind,payload) values('account-deletion:'||p_user::text,'account_deletion',jsonb_build_object('userId',p_user)) on conflict do nothing;
 insert into beta_private.audit_events(actor,action,subject) values('account-service','account_access_revoked',p_user::text);
end $$;

alter table beta_private.provider_poll_runs enable row level security;
alter table beta_private.strategy_transitions enable row level security;
revoke all on beta_private.provider_poll_runs,beta_private.strategy_transitions from public,anon,authenticated;
revoke all on function beta_private.transition_strategy(text,text,uuid,text,text,uuid),beta_private.correction_guard() from public,anon,authenticated;
revoke all on function beta_private.disable_account(uuid) from public,anon,authenticated;
revoke all on function beta_private.candidate_evidence_guard() from public,anon,authenticated;
revoke all on function beta_private.publication_region_matches(uuid,uuid) from public,anon,authenticated;


-- SOURCE 20261003002609_phase3_membership_and_rewards.sql sha256=8b2a175a39ec5a7f0c3f96a470c662e042e4459cd6d8f8722d6ad2ac7ac3d505
-- Phase 3 preparation only. No billing, competition, prize or deal activation.
create table beta_private.membership_plans (
 id text primary key check(id in ('FREE','PRO')), name text not null,
 enabled boolean not null default false, provider text,
 check(id='FREE' or not enabled), check(provider is null)
);
insert into beta_private.membership_plans(id,name,enabled) values('FREE','Docked Free',true),('PRO','Docked Pro',false);
create table beta_private.plan_prices (
 id uuid primary key default gen_random_uuid(), plan_id text not null references beta_private.membership_plans(id),
 currency text check(currency ~ '^[A-Z]{3}$'), amount_minor bigint check(amount_minor>=0),
 cadence text check(cadence in ('month','year')), provider_price_reference text,
 enabled boolean not null default false check(not enabled), created_at timestamptz not null default clock_timestamp()
);
create table beta_private.plan_entitlements (
 plan_id text not null references beta_private.membership_plans(id), feature text not null,
 enabled boolean not null default false, primary key(plan_id,feature),
 check(feature not in ('leaderboard_advantage','verification_override','hide_losses','delayed_safety')),
 check(plan_id='FREE' or not enabled)
);
insert into beta_private.plan_entitlements(plan_id,feature,enabled)
 select 'FREE',feature,true from unnest(array['community','follows','social_posts','community_edges','public_profile','top_docked','core_official_edges','standard_alerts','public_results','methodology','education','basic_tracking','safety_and_corrections']) feature;
create table beta_private.member_subscriptions (
 id uuid primary key default gen_random_uuid(), user_id uuid unique references beta_public.profiles(id) on delete cascade,
 plan_id text not null references beta_private.membership_plans(id) default 'FREE',
 provider text, customer_reference text, subscription_reference text unique,
 state text not null default 'FREE' check(state in ('FREE','INCOMPLETE','TRIAL','ACTIVE','PAST_DUE','GRACE','CANCEL_AT_PERIOD_END','CANCELED','EXPIRED')),
 current_period_end timestamptz, cancel_at_period_end boolean not null default false,
 auto_convert boolean not null default false check(not auto_convert),
 created_at timestamptz not null default clock_timestamp(),
 check(plan_id='FREE' and state in ('FREE','INCOMPLETE','CANCELED','EXPIRED')),
 check(provider is null and customer_reference is null and subscription_reference is null)
);
create table beta_private.subscription_events (
 id uuid primary key default gen_random_uuid(), subscription_id uuid, actor uuid not null,
 event text not null, provider_event_id text unique, reason text not null check(length(reason)>=12),
 created_at timestamptz not null default clock_timestamp()
);
create table beta_private.commercial_approvals (
 id uuid primary key default gen_random_uuid(), feature text not null check(feature in ('paid_analysis','competitions','prizes','deals','sponsorship','marketing','affiliates')),
 country text not null check(country ~ '^[A-Z]{2}$'), state text not null,
 topic text not null check(topic in ('jurisdiction','rules','prize_tax_permit','privacy','marketing','sponsor','responsible_design')),
 approved boolean not null default false, evidence text not null check(length(evidence)>=12),
 valid_from timestamptz not null, valid_to timestamptz not null, review_at timestamptz not null,
 actor uuid not null, created_at timestamptz not null default clock_timestamp(),
 check(valid_to>valid_from and review_at>valid_from)
);
create table beta_private.community_competitions (
 id uuid primary key default gen_random_uuid(), title text not null, description text not null,
 country text not null, state text not null, starts_at timestamptz not null, ends_at timestamptz not null,
 entry_cutoff timestamptz not null, minimum_age integer not null check(minimum_age>=18),
 membership text not null check(membership in ('FREE','FREE_AND_PRO','FUTURE_PRO')),
 mechanics text not null check(mechanics in ('STANDARD_VERIFIED_PERFORMANCE','NON_WAGER_PREDICTION')),
 state_code text not null default 'DRAFT_DISABLED' check(state_code='DRAFT_DISABLED'),
 actor uuid not null, draft_hash text not null check(draft_hash ~ '^[0-9a-f]{64}$'), reason text not null check(length(reason)>=12), created_at timestamptz not null default clock_timestamp(),
 unique(actor,draft_hash),
 check(entry_cutoff<=starts_at and ends_at>starts_at)
);
create table beta_private.competition_rules (
 id uuid primary key default gen_random_uuid(), competition_id uuid not null unique references beta_private.community_competitions(id),
 version text not null, ranking_rule_version text not null, config jsonb not null,
 config_hash text not null check(config_hash ~ '^[0-9a-f]{64}$'),
 minimum_settled integer not null check(minimum_settled>=20), minimum_active_days integer not null check(minimum_active_days>=7),
 entry_limit integer not null check(entry_limit=1), tie_breaker text not null check(tie_breaker='NET_UNITS_ROI_SETTLED_EARLIEST'),
 frozen_at timestamptz not null default clock_timestamp(), actor uuid not null,
 unique(competition_id,version)
);
create table beta_private.competition_prizes (
 id uuid primary key default gen_random_uuid(), competition_id uuid not null references beta_private.community_competitions(id),
 description text not null, value numeric check(value>=0), currency text, sponsor text not null,
 check((value is null)=(currency is null)), check(currency is null or currency ~ '^[A-Z]{3}$')
);
create table beta_private.competition_qualifications (
 id uuid primary key default gen_random_uuid(), competition_id uuid not null references beta_private.community_competitions(id),
 member_id uuid not null, rule_id uuid not null references beta_private.competition_rules(id),
 eligible boolean not null, reason text not null, qualifying_edge_ids uuid[] not null,
 calculated_at timestamptz not null default clock_timestamp(), unique(competition_id,member_id,calculated_at)
);
create table beta_private.competition_rankings (
 id uuid primary key default gen_random_uuid(), competition_id uuid not null references beta_private.community_competitions(id),
 rule_id uuid not null references beta_private.competition_rules(id), leaderboard_snapshot_id uuid,
 rankings jsonb not null, export_hash text not null, calculated_at timestamptz not null default clock_timestamp()
);
create table beta_private.prize_award_events (
 id uuid primary key default gen_random_uuid(), competition_id uuid not null references beta_private.community_competitions(id),
 prize_id uuid not null references beta_private.competition_prizes(id), candidate_member_id uuid not null,
 ranking_id uuid not null references beta_private.competition_rankings(id), previous_id uuid unique references beta_private.prize_award_events(id),
 state text not null check(state in ('CALCULATED','INTEGRITY_REVIEW','ELIGIBILITY_REVIEW','APPROVED','AWARDED','DISQUALIFIED')),
 actor uuid not null, reason text not null check(length(reason)>=12), evidence text not null,
 created_at timestamptz not null default clock_timestamp()
);
create table beta_private.community_deals (
 id uuid primary key default gen_random_uuid(), title text not null, description text not null, sponsor text not null,
 category text not null check(category in ('MERCHANDISE','MEDIA','TICKETS','DOCKED_BENEFIT','NON_GAMBLING','BETTING_REVIEW_REQUIRED')),
 country text not null, state text not null, membership text not null check(membership in ('FREE','FREE_AND_PRO','FUTURE_PRO')),
 starts_at timestamptz not null, ends_at timestamptz not null, terms text not null, disclosure text not null,
 tracking_class text not null check(tracking_class in ('NONE','CONSENTED_AGGREGATE')),
 state_code text not null default 'DRAFT_DISABLED' check(state_code='DRAFT_DISABLED'),
 actor uuid not null, draft_hash text not null check(draft_hash ~ '^[0-9a-f]{64}$'), reason text not null check(length(reason)>=12), created_at timestamptz not null default clock_timestamp(),
 unique(actor,draft_hash),
 check(ends_at>starts_at)
);
create index community_competitions_created on beta_private.community_competitions(created_at desc,id);
create index community_deals_created on beta_private.community_deals(created_at desc,id);
create index commercial_approvals_region on beta_private.commercial_approvals(feature,country,state,valid_from desc);

create function beta_private.commercial_draft_audit() returns trigger language plpgsql set search_path=beta_private,pg_temp as $$
begin
 if not exists(select 1 from beta_private.roles where user_id=new.actor and role in ('owner','admin')) then raise exception 'Administrator required'; end if;
 insert into beta_private.audit_events(actor,action,subject,details) values(new.actor,'commercial_draft.'||tg_table_name,new.id::text,jsonb_build_object('state','DISABLED'));
 return new;
end $$;
create function beta_private.commercial_activation_disabled() returns trigger language plpgsql set search_path=beta_private,pg_temp as $$
begin raise exception 'Competition, prize and deal activation requires a separately reviewed release; disabled in Phase 3'; end $$;

create trigger commercial_draft_audit after insert on beta_private.community_competitions for each row execute function beta_private.commercial_draft_audit();
create trigger commercial_draft_audit after insert on beta_private.community_deals for each row execute function beta_private.commercial_draft_audit();
create trigger commercial_draft_audit after insert on beta_private.commercial_approvals for each row execute function beta_private.commercial_draft_audit();

do $$ declare t text; begin
 foreach t in array array['membership_plans','plan_prices','plan_entitlements','member_subscriptions','subscription_events','commercial_approvals','community_competitions','competition_rules','competition_prizes','competition_qualifications','competition_rankings','prize_award_events','community_deals'] loop
 execute format('alter table beta_private.%I enable row level security',t);
 execute format('revoke all on beta_private.%I from public,anon,authenticated',t);
 end loop;
 foreach t in array array['subscription_events','commercial_approvals','community_competitions','competition_rules','competition_prizes','competition_qualifications','competition_rankings','prize_award_events','community_deals'] loop
 execute format('create trigger immutable before update or delete on beta_private.%I for each row execute function beta_private.immutable()',t);
 end loop;
 foreach t in array array['competition_qualifications','competition_rankings','prize_award_events'] loop
 execute format('create trigger activation_disabled before insert on beta_private.%I for each row execute function beta_private.commercial_activation_disabled()',t);
 end loop;
end $$;
revoke all on function beta_private.commercial_draft_audit() from public,anon,authenticated;
revoke all on function beta_private.commercial_activation_disabled() from public,anon,authenticated;

alter table beta_private.analytics_events drop constraint analytics_events_event_check;
alter table beta_private.analytics_events add constraint analytics_events_event_check check(event in (
 'landing_view','signup_started','signup_completed','email_verified','onboarding_completed','sport_selected','bookmaker_selected',
 'edge_viewed','tip_saved','methodology_viewed','results_viewed','alert_enabled','alert_disabled','digest_enabled','digest_disabled','article_viewed','share_clicked',
 'feed_viewed','post_started','post_created','community_edge_started','community_edge_submitted','community_edge_rejected','community_price_moved','community_promo_excluded',
 'member_followed','member_unfollowed','reaction_added','comment_created','profile_viewed','leaderboard_viewed','member_discovery_viewed',
 'notifications_viewed','notification_opened','pro_viewed','competition_viewed','deal_viewed'
));


-- SOURCE 20261003002709_phase3_social_core.sql sha256=eb879ec56e6780bcb140f230a42783fde0f858348c635a68ded15270b414e3e6
-- Phase 3 social features. Local/isolated preview only; no hosted activation.
create table beta_private.social_profiles (
 id uuid primary key default gen_random_uuid(), user_id uuid unique references beta_public.profiles(id) on delete set null,
 handle text not null unique check(handle ~ '^[a-z][a-z0-9_]{2,39}$'), display_name text not null check(length(display_name) between 1 and 60),
 bio text not null default '' check(length(bio)<=280), avatar_media_id uuid,
 is_official boolean not null default false, visibility text not null default 'members' check(visibility in ('members','private')),
 status text not null default 'active' check(status in ('active','restricted','suspended','deleted')),
 joined_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
 check(is_official=(id='00000000-0000-4000-8000-000000000001'::uuid)),
 check((is_official and handle='docked' and display_name='Docked' and user_id is null and status='active') or (not is_official and handle<>'docked')),
 check(user_id is not null or is_official or status='deleted')
);
insert into beta_private.social_profiles(id,handle,display_name,bio,is_official) values
 ('00000000-0000-4000-8000-000000000001','docked','Docked','Official Docked research, education and canonical Edge records.',true);
create table beta_private.social_handle_history(handle text primary key,profile_id uuid not null references beta_private.social_profiles(id),created_at timestamptz not null default clock_timestamp());
create table beta_private.social_follows(actor_id uuid not null references beta_private.social_profiles(id),target_id uuid not null references beta_private.social_profiles(id),notifications boolean not null default false,created_at timestamptz not null default clock_timestamp(),primary key(actor_id,target_id),check(actor_id<>target_id));
create index on beta_private.social_follows(target_id,created_at desc);
create table beta_private.social_blocks(actor_id uuid not null references beta_private.social_profiles(id),target_id uuid not null references beta_private.social_profiles(id),created_at timestamptz not null default clock_timestamp(),primary key(actor_id,target_id),check(actor_id<>target_id));
create index on beta_private.social_blocks(target_id,actor_id);
create table beta_private.social_mutes(actor_id uuid not null references beta_private.social_profiles(id),target_id uuid not null references beta_private.social_profiles(id),created_at timestamptz not null default clock_timestamp(),primary key(actor_id,target_id),check(actor_id<>target_id));
create table beta_private.social_posts (
 id uuid primary key default gen_random_uuid(),author_id uuid not null references beta_private.social_profiles(id),
 kind text not null check(kind in ('discussion','analysis','question','celebration','edge','official')),body text not null check(length(body)<=4000),sport text,
 official_tip_id uuid unique references beta_private.tip_publications(id),community_edge_id uuid unique,
 claim_label text not null default 'social_only' check(claim_label in ('social_only','promotional_price')),
 moderation_status text not null default 'visible' check(moderation_status in ('visible','removed','review')),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),deleted_at timestamptz,
 idempotency_key uuid,unique(author_id,idempotency_key),
 check(not(official_tip_id is not null and community_edge_id is not null)),
 check((kind='edge' and (official_tip_id is not null or community_edge_id is not null)) or (kind<>'edge' and official_tip_id is null and community_edge_id is null)),
 check((kind<>'official' and official_tip_id is null) or author_id='00000000-0000-4000-8000-000000000001')
);
create index on beta_private.social_posts(created_at desc,id desc);
create index on beta_private.social_posts(author_id,created_at desc,id desc);
create index on beta_private.social_posts(sport,created_at desc);
create table beta_private.social_media (
 id uuid primary key default gen_random_uuid(),owner_id uuid not null references beta_private.social_profiles(id),
 content bytea,sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),mime text not null check(mime='image/webp'),
 width integer not null check(width between 1 and 4096),height integer not null check(height between 1 and 4096),
 alt text not null check(length(alt) between 1 and 240),status text not null default 'quarantine' check(status in ('quarantine','approved','rejected')),
 created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default (clock_timestamp()+interval '7 days'),
 reviewed_by uuid,reviewed_at timestamptz,check(octet_length(content)<=5242880),unique(owner_id,sha256)
);
alter table beta_private.social_profiles add foreign key(avatar_media_id) references beta_private.social_media(id);
create table beta_private.social_post_media(post_id uuid not null references beta_private.social_posts(id),media_id uuid not null references beta_private.social_media(id),position smallint not null check(position between 0 and 3),primary key(post_id,media_id),unique(post_id,position));
create table beta_private.social_comments (
 id uuid primary key default gen_random_uuid(),post_id uuid not null references beta_private.social_posts(id),author_id uuid not null references beta_private.social_profiles(id),
 parent_id uuid references beta_private.social_comments(id),depth smallint not null default 0 check(depth between 0 and 2),body text not null check(length(body)<=1000),
 moderation_status text not null default 'visible' check(moderation_status in ('visible','removed','review')),
 created_at timestamptz not null default clock_timestamp(),deleted_at timestamptz,idempotency_key uuid not null,unique(author_id,idempotency_key)
);
create index on beta_private.social_comments(post_id,created_at,id);
create table beta_private.social_reactions(profile_id uuid not null references beta_private.social_profiles(id),post_id uuid not null references beta_private.social_posts(id),created_at timestamptz not null default clock_timestamp(),primary key(profile_id,post_id));
create table beta_private.social_saved(profile_id uuid not null references beta_private.social_profiles(id),post_id uuid not null references beta_private.social_posts(id),created_at timestamptz not null default clock_timestamp(),primary key(profile_id,post_id));
create table beta_private.social_reports (
 id uuid primary key default gen_random_uuid(),reporter_id uuid references beta_private.social_profiles(id),target_type text not null check(target_type in ('post','comment','profile','media')),target_id uuid not null,
 reason text not null check(reason in ('spam','harassment','impersonation','privacy','scam','affiliate_spam','misleading_odds','other')),details text not null default '' check(length(details)<=1000),
 status text not null default 'open' check(status in ('open','dismissed','actioned','escalated')),created_at timestamptz not null default clock_timestamp(),closed_at timestamptz,
 unique(reporter_id,target_type,target_id)
);
create index on beta_private.social_reports(status,created_at);
create table beta_private.social_moderation_events(id uuid primary key default gen_random_uuid(),actor uuid not null,report_id uuid references beta_private.social_reports(id),target_type text not null,target_id uuid not null,decision text not null,reason text not null check(length(reason)>=12),created_at timestamptz not null default clock_timestamp());
create trigger immutable before update or delete on beta_private.social_moderation_events for each row execute function beta_private.immutable();
create table beta_private.social_notification_preferences (
 profile_id uuid primary key references beta_private.social_profiles(id),official_edges boolean not null default false,followed_members boolean not null default false,social boolean not null default true,
 leaderboard boolean not null default false,competitions boolean not null default false,deals_marketing boolean not null default false,
 in_app boolean not null default true,email boolean not null default false check(not email),push boolean not null default false check(not push),updated_at timestamptz not null default clock_timestamp()
);
create table beta_private.social_notifications (
 id uuid primary key default gen_random_uuid(),recipient_id uuid not null references beta_private.social_profiles(id),actor_id uuid references beta_private.social_profiles(id),
 type text not null check(type in ('official_edge','edge_status','followed_post','followed_edge','comment','reply','reaction','follower','leaderboard','competition','prize','deal','account','system')),
 post_id uuid references beta_private.social_posts(id),title text not null check(length(title)<=180),href text not null check(href ~ '^/(home|community|profile|notifications|edges|top-docked|membership|competitions|deals)(/|\?|$)'),
 group_key text not null,dedupe_key text not null unique,created_at timestamptz not null default clock_timestamp(),read_at timestamptz,
 expires_at timestamptz not null default (clock_timestamp()+interval '90 days')
);
create index on beta_private.social_notifications(recipient_id,created_at desc,id desc);
create table beta_private.social_notification_jobs (
 id uuid primary key default gen_random_uuid(),dedupe_key text not null unique,
 post_id uuid not null references beta_private.social_posts(id),kind text not null default 'publication' check(kind in ('publication','status')),cursor_profile_id uuid,
 created_at timestamptz not null default clock_timestamp(),completed_at timestamptz
);
create index on beta_private.social_notification_jobs(created_at) where completed_at is null;
create function beta_private.social_queue_notification() returns trigger language plpgsql set search_path='' as $$
begin
 insert into beta_private.social_notification_jobs(post_id,dedupe_key) values(new.id,'post:'||new.id) on conflict do nothing;
 return new;
end $$;
create trigger social_queue_notification after insert on beta_private.social_posts for each row execute function beta_private.social_queue_notification();
create function beta_private.social_queue_official_status() returns trigger language plpgsql set search_path='' as $$
begin
 insert into beta_private.social_notification_jobs(post_id,kind,dedupe_key)
 select id,'status',tg_table_name||':'||new.id from beta_private.social_posts where official_tip_id=new.tip_id
 on conflict do nothing;
 return new;
end $$;
create trigger social_queue_status after insert on beta_private.tip_status_events for each row execute function beta_private.social_queue_official_status();
create trigger social_queue_settlement after insert on beta_private.settlement_events for each row execute function beta_private.social_queue_official_status();

create function beta_private.community_assert_access(p_actor uuid,p_feature text) returns void language plpgsql set search_path='' as $$
declare member beta_public.profiles; policy beta_private.region_policies;
begin
 if p_actor is distinct from auth.uid() or not beta_private.active_member_session() then raise exception 'Active authenticated session required'; end if;
 select * into member from beta_public.profiles where id=p_actor for share;
 if not found or member.disabled_at is not null or not member.age_attested or member.accepted_version='' then raise exception 'Account ineligible'; end if;
 select * into policy from beta_private.region_policies where country=member.country and state=member.state and effective_from<=clock_timestamp() and effective_to>clock_timestamp() order by effective_from desc,id desc limit 1 for share;
 if not found or not policy.approved or policy.minimum_age>18 or policy.review_at<=clock_timestamp() or length(trim(policy.evidence))=0 or not(p_feature=any(policy.features)) then raise exception 'Community feature restricted'; end if;
end $$;
create function beta_private.community_actor(p_actor uuid,p_feature text,p_require_posting boolean default true) returns uuid language plpgsql set search_path='' as $$
declare profile beta_private.social_profiles;
begin
 perform beta_private.community_assert_access(p_actor,p_feature);
 select * into profile from beta_private.social_profiles where user_id=p_actor for update;
 if not found then raise exception 'Create a social profile first'; end if;
 if profile.status in ('suspended','deleted') or (p_require_posting and profile.status<>'active') then raise exception 'Social account restricted'; end if;
 return profile.id;
end $$;
create function beta_private.social_profile_visible(p_viewer uuid,p_target uuid,p_include_deleted boolean default false) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from beta_private.social_profiles target where target.id=p_target
 and (target.is_official or target.id=p_viewer or (target.visibility='members' and (target.status in ('active','restricted') or p_include_deleted)))
 and not exists(select 1 from beta_private.social_blocks b where (b.actor_id=p_viewer and b.target_id=p_target) or (b.actor_id=p_target and b.target_id=p_viewer)))
$$;
create function beta_private.community_feature_allowed(p_actor uuid,p_feature text) returns boolean language sql stable set search_path='' as $$
 select coalesce((select policy.approved and policy.minimum_age=18 and policy.review_at>now() and length(trim(policy.evidence))>0 and p_feature=any(policy.features)
 from beta_public.profiles member join lateral (select * from beta_private.region_policies r where r.country=member.country and r.state=member.state and r.effective_from<=now() and r.effective_to>now() order by r.effective_from desc,r.id desc limit 1) policy on true
 where member.id=p_actor and member.disabled_at is null and member.age_attested and member.accepted_version<>''),false)
$$;
create function beta_private.community_post_allowed(p_actor uuid,p_post uuid) returns boolean language sql stable set search_path='' as $$
 select beta_private.community_feature_allowed(p_actor,'community_social') and exists(select 1 from beta_private.social_posts p where p.id=p_post
 and (p.community_edge_id is null or beta_private.community_feature_allowed(p_actor,'community_edges'))
 and (p.official_tip_id is null or (beta_private.community_feature_allowed(p_actor,'tips') and exists(
 select 1 from beta_private.tip_publications tip join beta_public.profiles member on member.id=p_actor
 join lateral (select * from beta_private.region_policies rp where rp.country=member.country and rp.state=member.state and rp.effective_from<=now() and rp.effective_to>now() order by rp.effective_from desc,rp.id desc limit 1) policy on true
 where tip.id=p.official_tip_id and tip.evidence='live_published' and tip.published_at<=now() and beta_private.publication_region_matches(tip.region_policy_id,policy.id)))))
$$;
create function beta_private.social_post_visible(p_viewer uuid,p_post uuid) returns boolean language sql stable set search_path='' as $$
 select beta_private.community_post_allowed(auth.uid(),p_post) and exists(select 1 from beta_private.social_posts p where p.id=p_post and beta_private.social_profile_visible(p_viewer,p.author_id,false) and (p.moderation_status='visible' or p.kind='edge') and (p.deleted_at is null or p.kind='edge'))
$$;
create function beta_private.social_official_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Durable social identity cannot be deleted'; end if;
 if old.is_official and new is distinct from old then raise exception 'Official Docked identity is immutable'; end if;
 if new.id<>old.id or new.is_official<>old.is_official or (new.user_id is distinct from old.user_id and not(new.user_id is null and new.status='deleted')) then raise exception 'Social identity ownership is immutable'; end if;
 return new;
end $$;
create trigger social_official_guard before update or delete on beta_private.social_profiles for each row execute function beta_private.social_official_guard();
create function beta_private.social_identity_guard() returns trigger language plpgsql set search_path='' as $$
declare normalized text; historical uuid;
begin
 if new.is_official then return new; end if;
 normalized=regexp_replace(translate(lower(normalize(new.handle||' '||new.display_name,NFKD)),'013457оОοΟсСеЕ','oieastooooccee'),'[^a-z]','','g');
 if normalized like '%docked%' or normalized ~ '(official|administrator|moderator|support|admin)' or new.display_name ~ '[✓✔☑✅]'
 or (new.display_name ~ '[a-zA-Z]' and new.display_name ~ '[а-яА-Яα-ωΑ-Ω]') then raise exception 'Protected identity'; end if;
 if tg_op='INSERT' or new.handle is distinct from old.handle then
  select profile_id into historical from beta_private.social_handle_history where handle=new.handle;
  if historical is not null and historical<>new.id then raise exception 'Handle is reserved'; end if;
  insert into beta_private.social_handle_history(handle,profile_id) values(new.handle,new.id) on conflict do nothing;
  if tg_op='UPDATE' then insert into beta_private.audit_events(actor,action,subject,details) values(coalesce(new.user_id::text,'account-service'),'social_handle_changed',new.id::text,jsonb_build_object('changed',true)); end if;
 end if;
 return new;
end $$;
-- AFTER ensures the FK to a newly inserted durable profile exists.
create trigger social_identity_guard after insert or update on beta_private.social_profiles for each row execute function beta_private.social_identity_guard();
create function beta_private.social_post_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Use social tombstone; underlying Edge survives'; end if;
 if new.id<>old.id or new.author_id<>old.author_id or new.kind<>old.kind or new.created_at<>old.created_at
 or new.official_tip_id is distinct from old.official_tip_id or new.community_edge_id is distinct from old.community_edge_id or new.idempotency_key is distinct from old.idempotency_key
 then raise exception 'Social identity and ledger linkage immutable'; end if;
 return new;
end $$;
create trigger social_post_guard before update or delete on beta_private.social_posts for each row execute function beta_private.social_post_guard();
create function beta_private.social_comment_guard() returns trigger language plpgsql set search_path='' as $$
declare parent beta_private.social_comments;
begin
 if new.parent_id is not null then
  select * into parent from beta_private.social_comments where id=new.parent_id;
  if not found or parent.post_id<>new.post_id or parent.depth>=2 then raise exception 'Invalid reply parent or maximum depth'; end if;
  new.depth=parent.depth+1;
 else new.depth=0; end if;
 return new;
end $$;
create trigger social_comment_guard before insert on beta_private.social_comments for each row execute function beta_private.social_comment_guard();
create function beta_private.social_media_link_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from beta_private.social_media m join beta_private.social_posts p on p.author_id=m.owner_id where p.id=new.post_id and m.id=new.media_id and m.status='approved' and m.content is not null) then raise exception 'Only owned approved media can be attached'; end if;
 return new;
end $$;
create trigger social_media_link_guard before insert or update on beta_private.social_post_media for each row execute function beta_private.social_media_link_guard();
create function beta_private.social_official_edge_projection() returns trigger language plpgsql set search_path='' as $$
begin
 if new.evidence='live_published' then
  insert into beta_private.social_posts(author_id,kind,body,sport,official_tip_id,created_at)
  select '00000000-0000-4000-8000-000000000001','edge','',c.sport_id,new.id,new.published_at from beta_private.events e join beta_private.competitions c on c.id=e.competition_id where e.id=new.event_id
  on conflict(official_tip_id) do nothing;
 end if;
 return new;
end $$;
create trigger social_official_edge_projection after insert on beta_private.tip_publications for each row execute function beta_private.social_official_edge_projection();
-- Only existing canonical live publications are projected; no synthetic tips or results.
insert into beta_private.social_posts(author_id,kind,body,sport,official_tip_id,created_at)
 select '00000000-0000-4000-8000-000000000001','edge','',c.sport_id,t.id,t.published_at from beta_private.tip_publications t join beta_private.events e on e.id=t.event_id join beta_private.competitions c on c.id=e.competition_id where t.evidence='live_published' on conflict(official_tip_id) do nothing;
create function beta_private.social_account_erasure() returns trigger language plpgsql set search_path='' as $$
declare v_profile uuid;
begin
 if tg_op='UPDATE' and (new.disabled_at is null or old.disabled_at is not null) then return new; end if;
 select id into v_profile from beta_private.social_profiles where user_id=old.id;
 if v_profile is not null then
  update beta_private.social_posts set body='',moderation_status='removed',deleted_at=coalesce(deleted_at,clock_timestamp()),updated_at=clock_timestamp() where author_id=v_profile;
  update beta_private.social_comments set body='',moderation_status='removed',deleted_at=coalesce(deleted_at,clock_timestamp()) where author_id=v_profile;
  delete from beta_private.social_post_media where media_id in(select id from beta_private.social_media where owner_id=v_profile);
  update beta_private.social_media set content=null,alt='Removed',status='rejected' where owner_id=v_profile;
  delete from beta_private.social_reactions where social_reactions.profile_id=v_profile;
  delete from beta_private.social_saved where social_saved.profile_id=v_profile;
  delete from beta_private.social_follows where actor_id=v_profile or target_id=v_profile;
  delete from beta_private.social_blocks where actor_id=v_profile or target_id=v_profile;
  delete from beta_private.social_mutes where actor_id=v_profile or target_id=v_profile;
  delete from beta_private.social_notifications where recipient_id=v_profile or actor_id=v_profile;
  delete from beta_private.social_notification_preferences where social_notification_preferences.profile_id=v_profile;
  update beta_private.social_reports set reporter_id=null,details='' where reporter_id=v_profile;
  delete from beta_private.social_handle_history where social_handle_history.profile_id=v_profile;
  update beta_private.social_profiles set user_id=null,handle='deleted_'||replace(id::text,'-',''),display_name='Deleted member',bio='',avatar_media_id=null,status='deleted',visibility='members',updated_at=clock_timestamp() where id=v_profile;
 end if;
 if tg_op='DELETE' then return old; end if; return new;
end $$;
create trigger social_account_erasure before delete or update of disabled_at on beta_public.profiles for each row execute function beta_private.social_account_erasure();

do $$ declare t text; begin foreach t in array array['social_profiles','social_handle_history','social_follows','social_blocks','social_mutes','social_posts','social_media','social_post_media','social_comments','social_reactions','social_saved','social_reports','social_moderation_events','social_notification_preferences','social_notifications','social_notification_jobs'] loop
 execute format('alter table beta_private.%I enable row level security',t);
 execute format('revoke all on beta_private.%I from public,anon,authenticated',t);
end loop; end $$;
revoke all on function beta_private.community_assert_access(uuid,text),beta_private.community_actor(uuid,text,boolean),beta_private.social_profile_visible(uuid,uuid,boolean),beta_private.social_post_visible(uuid,uuid),beta_private.social_official_guard(),beta_private.social_identity_guard(),beta_private.social_post_guard(),beta_private.social_comment_guard(),beta_private.social_media_link_guard(),beta_private.social_account_erasure() from public,anon,authenticated;
revoke all on function beta_private.community_feature_allowed(uuid,text),beta_private.social_official_edge_projection() from public,anon,authenticated;
revoke all on function beta_private.community_post_allowed(uuid,uuid),beta_private.social_queue_notification(),beta_private.social_queue_official_status() from public,anon,authenticated;


-- SOURCE 20261003002935_phase3_community_edge_ledger.sql sha256=2285eaa18c23ae5d50dc988ef4c144ab17cb0317b6f51a182647627b58f4fc48
-- Community opinions have their own canonical ledger. Official publications are untouched.
create table beta_private.community_verification_rules (
  version text primary key, cutoff_seconds integer not null check(cutoff_seconds>=600),
  max_age_seconds integer not null check(max_age_seconds between 1 and 180),
  standard_units numeric not null check(standard_units=1), created_at timestamptz not null default clock_timestamp()
);
insert into beta_private.community_verification_rules values('community-standard-v1',600,180,1,clock_timestamp());
insert into beta_private.feature_flags(key,enabled,reason) values('community_edges',false,'Requires licensed standard-price metadata and community jurisdiction approval') on conflict do nothing;

create table beta_private.community_quote_evidence (
  id uuid primary key default gen_random_uuid(), snapshot_id text not null unique references beta_private.odds_snapshots(id),
  provider_event_id text not null, observed_start_at timestamptz not null,
  classification text not null check(classification in ('STANDARD_VERIFIED','PROMOTIONAL_EXCLUDED','UNVERIFIED','STALE','MARKET_MISMATCH','UNSUPPORTED','POST_CUTOFF','UNKNOWN_REVIEW')),
  classification_version text not null, classification_evidence text not null,
  rights_reference text not null, metadata jsonb not null, created_at timestamptz not null default clock_timestamp()
);
create function beta_private.community_quote_evidence_guard() returns trigger language plpgsql set search_path='' as $$
declare q beta_private.odds_snapshots; e beta_private.events; m beta_private.markets; h beta_private.source_health; meta jsonb;
begin
  select * into q from beta_private.odds_snapshots where id=new.snapshot_id for share;
  select * into m from beta_private.markets where id=q.market_id for share;
  select * into e from beta_private.events where id=m.event_id for share;
  select * into h from beta_private.source_health where provider=q.provider for share;
  meta:=q.payload->'communityMetadata';
  if q.id is null or q.evidence not in ('forward_paper','live_published') or q.provenance is distinct from h.rights_reference
    or h.rights_reference is null or not coalesce((h.capabilities->>'display')::boolean,false)
    or not coalesce((h.capabilities->>'retention')::boolean,false) or not coalesce((h.capabilities->>'community_standard_prices')::boolean,false)
    or meta is null or meta->>'sourceKind' is distinct from 'current_provider' or meta->>'receivedByDocked' is distinct from 'true'
    or meta->>'providerEventId' is distinct from e.source_mappings->>q.provider
    or meta->>'priceClass' is null or jsonb_typeof(meta->'promotionFlags') is distinct from 'array'
    or length(coalesce(meta->>'classificationEvidence',''))<5 or length(coalesce(meta->>'classificationVersion',''))<3
    then raise exception 'Trusted licensed standard-price metadata unavailable: UNKNOWN_REVIEW'; end if;
  new.provider_event_id:=meta->>'providerEventId';
  new.observed_start_at:=(meta->>'observedStartAt')::timestamptz;
  if new.observed_start_at is distinct from e.start_at then raise exception 'Observed event start mismatch'; end if;
  new.classification:=case when jsonb_array_length(meta->'promotionFlags')>0 then 'PROMOTIONAL_EXCLUDED' else meta->>'priceClass' end;
  new.classification_version:=meta->>'classificationVersion'; new.classification_evidence:=meta->>'classificationEvidence';
  new.metadata:=meta; new.rights_reference:=h.rights_reference; new.created_at:=clock_timestamp(); return new;
end $$;
create trigger community_quote_evidence_guard before insert on beta_private.community_quote_evidence for each row execute function beta_private.community_quote_evidence_guard();

create table beta_private.community_edges (
  id uuid primary key default gen_random_uuid(), profile_id uuid not null references beta_private.social_profiles(id),
  event_id text not null references beta_private.events(id), market_id text not null references beta_private.markets(id),
  snapshot_id text not null references beta_private.odds_snapshots(id), quote_evidence_id uuid not null references beta_private.community_quote_evidence(id),
  provider text not null, provider_event_id text not null, bookmaker text not null, selection text not null,
  market_rules jsonb not null, sport text not null, competition text not null,
  odds numeric not null check(odds>1 and odds<=1000), standard_units numeric not null default 1 check(standard_units=1),
  classification text not null default 'STANDARD_VERIFIED' check(classification='STANDARD_VERIFIED'),
  verification_rule text not null references beta_private.community_verification_rules(version),
  start_at timestamptz not null, source_at timestamptz not null, snapshot_at timestamptz not null, received_at timestamptz not null,
  submitted_at timestamptz not null default clock_timestamp(), region_policy_id uuid not null references beta_private.region_policies(id),
  confirmed_permanent boolean not null check(confirmed_permanent), review_hash text not null check(length(review_hash)=64),
  idempotency_key uuid not null, request_hash text not null check(length(request_hash)=64),
  unique(profile_id,idempotency_key), unique(profile_id,event_id)
);
create index on beta_private.community_edges(submitted_at desc,id desc);
create index on beta_private.community_edges(profile_id,submitted_at desc);
create index on beta_private.community_edges(sport,submitted_at desc);
alter table beta_private.social_posts add constraint social_posts_community_edge_fk foreign key(community_edge_id) references beta_private.community_edges(id);
create function beta_private.community_submission_retry(p_profile uuid,p_key uuid,p_hash text) returns uuid language plpgsql set search_path='' as $$
declare profile beta_private.social_profiles; existing beta_private.community_edges;
begin
  select * into profile from beta_private.social_profiles where id=p_profile for update;
  if profile.user_id is null or beta_private.community_actor(profile.user_id,'community_edges',true) is distinct from p_profile then raise exception 'Community author mismatch'; end if;
  select * into existing from beta_private.community_edges where profile_id=p_profile and idempotency_key=p_key;
  if existing.id is not null and existing.request_hash is distinct from p_hash then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
  return existing.id;
end $$;

create function beta_private.community_edge_guard() returns trigger language plpgsql set search_path='' as $$
declare q beta_private.odds_snapshots; v beta_private.community_quote_evidence; e beta_private.events; m beta_private.markets; h beta_private.source_health;
  p beta_private.social_profiles; r beta_private.region_policies; rule beta_private.community_verification_rules; checked_at timestamptz; latest text; author uuid;
begin
  checked_at:=clock_timestamp();
  if not coalesce((select enabled from beta_private.feature_flags where key='community_edges'),false) then raise exception 'Community Edge publication paused'; end if;
  select * into p from beta_private.social_profiles where id=new.profile_id for update;
  if p.id is null or p.is_official or p.user_id is null then raise exception 'Community member required'; end if;
  author:=beta_private.community_actor(p.user_id,'community_edges',true);
  if author is distinct from p.id then raise exception 'Community author mismatch'; end if;
  select * into rule from beta_private.community_verification_rules where version=new.verification_rule for share;
  if rule.version is distinct from 'community-standard-v1' then raise exception 'Unsupported verification rule'; end if;
  select * into e from beta_private.events where id=new.event_id for share;
  select * into m from beta_private.markets where id=new.market_id for update;
  -- Every trusted ingestion and confirmation for this market shares the market row lock.
  select * into q from beta_private.odds_snapshots where id=new.snapshot_id for share;
  select * into v from beta_private.community_quote_evidence where id=new.quote_evidence_id for share;
  select * into h from beta_private.source_health where provider=q.provider for share;
  select * into r from beta_private.region_policies where id=new.region_policy_id for share;
  perform 1 from beta_private.bookmaker_eligibility b where b.bookmaker=q.bookmaker and b.region_policy_id=r.id for share;
  perform 1 from beta_private.feature_flags where key='community_edges' for share;
  -- A contended transaction may have crossed the cutoff while waiting for any lock.
  checked_at:=clock_timestamp();
  if not coalesce((select enabled from beta_private.feature_flags where key='community_edges'),false) then raise exception 'Community Edge publication paused'; end if;
  select id into latest from beta_private.odds_snapshots where market_id=m.id and bookmaker=q.bookmaker and provider=q.provider
    and evidence in ('forward_paper','live_published') order by source_at desc,received_at desc,id desc limit 1;
  if q.id is null or q.id is distinct from latest or v.snapshot_id is distinct from q.id or q.market_id is distinct from m.id
    or m.event_id is distinct from e.id or q.evidence not in ('forward_paper','live_published')
    or v.classification<>'STANDARD_VERIFIED' or jsonb_array_length(v.metadata->'promotionFlags')<>0
    or v.observed_start_at is distinct from e.start_at or v.provider_event_id is distinct from e.source_mappings->>q.provider
    or q.payload->'rules' is distinct from m.rules or q.payload->>'id' is distinct from q.id
    or q.payload->>'bookmaker' is distinct from q.bookmaker or coalesce((q.payload->>'suspended')::boolean,true)
    then raise exception 'Current provider market evidence mismatch or non-standard price'; end if;
  if not coalesce(h.healthy,false) or h.last_success is null or h.last_success>checked_at or h.last_success<checked_at-interval '3 minutes'
    or h.rights_reference is distinct from v.rights_reference or h.rights_reference is distinct from q.provenance
    or not coalesce((h.capabilities->>'community_standard_prices')::boolean,false)
    or not coalesce((h.capabilities->>'display')::boolean,false) or not coalesce((h.capabilities->>'retention')::boolean,false)
    then raise exception 'Licensed provider health unavailable'; end if;
  if r.id is null or not r.approved or r.effective_from>checked_at or r.effective_to<=checked_at or r.review_at<=checked_at
    or r.id is distinct from (select rp.id from beta_private.region_policies rp join beta_public.profiles a on a.country=rp.country and a.state=rp.state where a.id=p.user_id and rp.effective_from<=checked_at and rp.effective_to>checked_at order by rp.effective_from desc,rp.id desc limit 1)
    or r.minimum_age>18 or not ('community_edges'=any(r.features)) or not(q.bookmaker=any(r.operators))
    or not exists(select 1 from beta_public.profiles a where a.id=p.user_id and a.country=r.country and a.state=r.state and a.age_attested and a.disabled_at is null)
    then raise exception 'Community jurisdiction denied'; end if;
  perform 1 from beta_private.bookmaker_eligibility b where b.bookmaker=q.bookmaker and b.region_policy_id=r.id and b.approved and b.effective_from<=checked_at and b.effective_to>checked_at for share;
  if not found then raise exception 'Bookmaker approval unavailable'; end if;
  if e.status<>'scheduled' or e.start_at<=checked_at+rule.cutoff_seconds*interval '1 second' then raise exception 'EDGE SUBMISSIONS CLOSED'; end if;
  if q.source_at>q.snapshot_at or q.snapshot_at>q.received_at or q.received_at>checked_at
    or q.source_at<checked_at-rule.max_age_seconds*interval '1 second' or q.received_at<checked_at-rule.max_age_seconds*interval '1 second'
    or (q.payload->>'sourceAt')::timestamptz is distinct from q.source_at or (q.payload->>'snapshotAt')::timestamptz is distinct from q.snapshot_at
    or (q.payload->>'receivedAt')::timestamptz is distinct from q.received_at then raise exception 'STALE quote or timestamp mismatch'; end if;
  if m.rules->>'period'<>'full_game' or m.rules->'line' is distinct from 'null'::jsonb or not (m.rules->'outcomes' ? new.selection)
    or (m.rules->>'eventId') is distinct from e.id or (m.rules->>'competition') is distinct from e.competition_id
    or m.rules->'participants' is distinct from e.participants
    or not exists(select 1 from beta_private.competitions where id=e.competition_id and sport_id=case when e.competition_id='basketball_nba' then 'basketball' else 'football' end)
    or jsonb_array_length(m.rules->'participants')<>2 or m.rules->'participants'->>0=m.rules->'participants'->>1
    or (select jsonb_agg(o order by o) from jsonb_array_elements_text(m.rules->'outcomes') o)
      is distinct from (select jsonb_agg(o order by o) from jsonb_array_elements_text(m.rules->'participants' || case when m.rules->>'market'='football_1x2' then '["Draw"]'::jsonb else '[]'::jsonb end) o)
    or not ((e.competition_id in ('soccer_epl','soccer_spain_la_liga') and m.rules->>'market'='football_1x2' and m.rules->>'settlement'='regulation_90_plus_stoppage' and m.rules->>'overtime'='false' and m.rules->>'draw'='true')
      or (e.competition_id='basketball_nba' and m.rules->>'market'='nba_moneyline' and m.rules->>'settlement'='full_game_including_overtime' and m.rules->>'overtime'='true' and m.rules->>'draw'='false'))
    then raise exception 'Unsupported or mismatched community settlement rules'; end if;
  if (select count(*) from jsonb_object_keys(q.payload->'prices'))<>jsonb_array_length(m.rules->'outcomes')
    or exists(select 1 from jsonb_array_elements_text(m.rules->'outcomes') o where not(q.payload->'prices' ? o) or (q.payload->'prices'->>o)::numeric<=1 or (q.payload->'prices'->>o)::numeric>1000)
    or new.odds is distinct from (q.payload->'prices'->>new.selection)::numeric then raise exception 'Verified provider price required'; end if;
  new.provider:=q.provider; new.provider_event_id:=v.provider_event_id; new.bookmaker:=q.bookmaker;
  new.market_rules:=m.rules; new.competition:=e.competition_id;
  select sport_id into new.sport from beta_private.competitions where id=e.competition_id;
  new.start_at:=e.start_at; new.source_at:=q.source_at; new.snapshot_at:=q.snapshot_at; new.received_at:=q.received_at;
  new.submitted_at:=checked_at; new.standard_units:=1; new.classification:='STANDARD_VERIFIED'; return new;
end $$;
create trigger community_edge_guard before insert on beta_private.community_edges for each row execute function beta_private.community_edge_guard();

-- Row lock serializes new quote ingestion with the final confirmation transaction.
create function beta_private.community_snapshot_lock() returns trigger language plpgsql set search_path='' as $$
begin perform 1 from beta_private.markets where id=new.market_id for update; return new; end $$;
create trigger community_snapshot_lock before insert on beta_private.odds_snapshots for each row execute function beta_private.community_snapshot_lock();

create table beta_private.community_edge_status (
  id uuid primary key default gen_random_uuid(), edge_id uuid not null references beta_private.community_edges(id),
  status text not null check(status in ('PENDING','INTEGRITY_REVIEW','INTEGRITY_CLEARED','MANUAL_REVIEW')),
  actor text not null, reason text not null check(length(reason)>=10), created_at timestamptz not null default clock_timestamp()
);
create index on beta_private.community_edge_status(edge_id,created_at desc,id desc);
create function beta_private.community_status_guard() returns trigger language plpgsql set search_path='' as $$
declare author uuid;
begin
  select p.user_id into author from beta_private.community_edges e join beta_private.social_profiles p on p.id=e.profile_id where e.id=new.edge_id for update of e;
  if new.status='PENDING' then
    if new.actor is distinct from author::text or auth.uid() is distinct from author or not beta_private.active_member_session()
      or exists(select 1 from beta_private.community_edge_status where edge_id=new.edge_id) then raise exception 'Initial pending status only'; end if;
  elsif new.actor is distinct from auth.uid()::text or auth.jwt()->>'aal' is distinct from 'aal2' or not beta_private.active_member_session()
    or not exists(select 1 from beta_private.roles where user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Administrator integrity review required'; end if;
  new.created_at:=clock_timestamp();
  insert into beta_private.audit_events(actor,action,subject,details) values(new.actor,'community_integrity_status',new.edge_id::text,jsonb_build_object('status',new.status,'reason',new.reason));
  return new;
end $$;
create trigger community_status_guard before insert on beta_private.community_edge_status for each row execute function beta_private.community_status_guard();
create table beta_private.community_result_sources (
  id uuid primary key default gen_random_uuid(), provider text not null, rights_reference text not null, approved boolean not null default false,
  reviewed_by uuid not null, review_at timestamptz not null, reason text not null check(length(reason)>=10), created_at timestamptz not null default clock_timestamp()
);
create index on beta_private.community_result_sources(provider,created_at desc,id desc);
create function beta_private.community_result_source_guard() returns trigger language plpgsql set search_path='' as $$
begin
  if new.reviewed_by is distinct from auth.uid() or auth.jwt()->>'aal' is distinct from 'aal2' or not beta_private.active_member_session()
    or not exists(select 1 from beta_private.roles where user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Administrator provider-rights review required'; end if;
  perform pg_advisory_xact_lock(hashtext('community-results:'||new.provider));
  new.created_at:=clock_timestamp();
  insert into beta_private.audit_events(actor,action,subject,details) values(new.reviewed_by::text,'community_results_rights',new.provider,jsonb_build_object('approved',new.approved,'reason',new.reason,'approvalId',new.id));
  return new;
end $$;
create trigger community_result_source_guard before insert on beta_private.community_result_sources for each row execute function beta_private.community_result_source_guard();
create table beta_private.community_settlements (
  id uuid primary key default gen_random_uuid(), edge_id uuid not null references beta_private.community_edges(id),
  result text not null check(result in ('WON','LOST','VOID','DISPUTED','MANUAL_REVIEW')),
  provider text not null, source_approval_id uuid not null references beta_private.community_result_sources(id), provider_event_id text not null, revision text not null,
  observed_at timestamptz not null, evidence jsonb not null, actor text not null,
  previous_id uuid unique references beta_private.community_settlements(id), correction_reason text,
  created_at timestamptz not null default clock_timestamp(), unique(edge_id,provider,provider_event_id,revision),
  check(previous_id is null or length(correction_reason)>=10)
);
create index on beta_private.community_settlements(edge_id,created_at desc,id desc);
create table beta_private.community_corrections (
  id uuid primary key default gen_random_uuid(), edge_id uuid not null references beta_private.community_edges(id),
  old_settlement_id uuid not null references beta_private.community_settlements(id), new_settlement_id uuid not null unique references beta_private.community_settlements(id),
  correction_type text not null default 'RESULT_CORRECTION', reason text not null, actor text not null,
  old_result text not null, new_result text not null, evidence_reference text not null, created_at timestamptz not null default clock_timestamp()
);
create function beta_private.community_settlement_guard() returns trigger language plpgsql set search_path='' as $$
declare edge beta_private.community_edges; previous beta_private.community_settlements; source beta_private.community_result_sources; outcome text; a text; b text; sa numeric; sb numeric;
begin
  select * into edge from beta_private.community_edges where id=new.edge_id for update;
  perform pg_advisory_xact_lock(hashtext('community-results:'||new.provider));
  select * into source from beta_private.community_result_sources where provider=new.provider order by created_at desc,id desc limit 1 for share;
  select * into previous from beta_private.community_settlements where edge_id=edge.id order by created_at desc,id desc limit 1;
  if edge.id is null or edge.start_at>clock_timestamp() or new.observed_at>clock_timestamp() or new.observed_at<edge.start_at
    or source.id is null or not source.approved or source.review_at<=clock_timestamp() or length(source.rights_reference)<=5
    or new.evidence->>'authorised' is distinct from 'true' or new.evidence->>'source' is distinct from new.provider
    or new.evidence->>'sourceEventId' is distinct from new.provider_event_id or new.evidence->>'revision' is distinct from new.revision
    or new.provider_event_id is distinct from (select source_mappings->>new.provider from beta_private.events where id=edge.event_id)
    or new.evidence->>'eventId' is distinct from edge.event_id or new.evidence->'rules' is distinct from edge.market_rules
    or (new.evidence->>'observedAt')::timestamptz is distinct from new.observed_at then raise exception 'Authorised matching result evidence required'; end if;
  if new.evidence->>'status'='final' then
    a:=edge.market_rules->'participants'->>0; b:=edge.market_rules->'participants'->>1;
    if (select count(*) from jsonb_object_keys(new.evidence->'scores'))<>2 or not(new.evidence->'scores' ? a and new.evidence->'scores' ? b) then raise exception 'Complete final scores required'; end if;
    sa:=(new.evidence->'scores'->>a)::numeric; sb:=(new.evidence->'scores'->>b)::numeric;
    if sa::text in ('NaN','Infinity','-Infinity') or sb::text in ('NaN','Infinity','-Infinity') or sa<0 or sb<0 or sa<>trunc(sa) or sb<>trunc(sb) then raise exception 'Invalid scores'; end if;
    if sa=sb and edge.market_rules->>'market'<>'football_1x2' then outcome:='DISPUTED';
    elsif edge.selection=(case when sa=sb then 'Draw' when sa>sb then a else b end) then outcome:='WON'; else outcome:='LOST'; end if;
  elsif new.evidence->>'status'='void' and length(coalesce(new.evidence->>'reason',''))>0 and length(coalesce(new.evidence->>'settlementBasis',''))>0 then outcome:='VOID';
  elsif new.evidence->>'status'='manual_review' then outcome:='MANUAL_REVIEW';
  elsif new.evidence->>'status'='disputed' then outcome:='DISPUTED'; else raise exception 'Unresolved outcome remains pending'; end if;
  if new.result is distinct from outcome then raise exception 'User or caller cannot choose settlement result'; end if;
  if previous.id is not null then
    if new.previous_id is distinct from previous.id or new.evidence->>'supersedesRevision' is distinct from previous.revision
      or length(coalesce(new.correction_reason,''))<10 or new.actor is distinct from auth.uid()::text
      or auth.jwt()->>'aal' is distinct from 'aal2' or not beta_private.active_member_session()
      or not exists(select 1 from beta_private.roles where user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Audited administrator correction required'; end if;
  elsif new.previous_id is not null then raise exception 'Invalid first settlement chain'; end if;
  new.source_approval_id:=source.id; new.created_at:=clock_timestamp(); return new;
end $$;
create trigger community_settlement_guard before insert on beta_private.community_settlements for each row execute function beta_private.community_settlement_guard();
create function beta_private.community_settlement_correction() returns trigger language plpgsql set search_path='' as $$
begin
  if new.previous_id is not null then
    insert into beta_private.community_corrections(edge_id,old_settlement_id,new_settlement_id,reason,actor,old_result,new_result,evidence_reference)
      select new.edge_id,new.previous_id,new.id,new.correction_reason,new.actor,result,new.result,new.provider||':'||new.provider_event_id||':'||new.revision from beta_private.community_settlements where id=new.previous_id;
  end if;
  insert into beta_private.audit_events(actor,action,subject,details) values(new.actor,'community_settlement',new.edge_id::text,jsonb_build_object('settlementId',new.id,'previousId',new.previous_id));
  insert into beta_private.social_notification_jobs(dedupe_key,post_id,kind)
    select 'community-settlement:'||new.id::text,id,'status' from beta_private.social_posts where community_edge_id=new.edge_id on conflict(dedupe_key) do nothing;
  return new;
end $$;
create trigger community_settlement_correction after insert on beta_private.community_settlements for each row execute function beta_private.community_settlement_correction();

create table beta_private.leaderboard_rule_versions (
  id text primary key, configuration jsonb not null, created_at timestamptz not null default clock_timestamp()
);
insert into beta_private.leaderboard_rule_versions values('top-docked-net-units-v1','{"minimumSettled":20,"minimumActiveDays":7,"primary":"net_standardised_units","tieBreakers":["maximum_drawdown_ascending","profile_id_ascending"],"periodBasis":"submitted_at_utc","roiDenominator":"settled_non_void_standard_units"}',clock_timestamp());
create table beta_private.leaderboard_snapshots (
  id uuid primary key default gen_random_uuid(), rule_version text not null references beta_private.leaderboard_rule_versions(id),
  period text not null check(period in ('week','month','7d','30d','90d','ytd','all')), sport text,
  as_of timestamptz not null, source_hash text not null check(length(source_hash)=64),
  snapshot_hash text not null check(length(snapshot_hash)=64), payload jsonb not null,
  previous_id uuid references beta_private.leaderboard_snapshots(id), actor uuid not null, reason text not null check(length(reason)>=10),
  created_at timestamptz not null default clock_timestamp()
);
create index on beta_private.leaderboard_snapshots(rule_version,period,sport,created_at desc);
create function beta_private.community_snapshot_guard() returns trigger language plpgsql set search_path='' as $$
begin
  if new.actor is distinct from auth.uid() or auth.jwt()->>'aal' is distinct from 'aal2' or not beta_private.active_member_session()
    or not exists(select 1 from beta_private.roles where user_id=new.actor and role in ('owner','admin'))
    or new.as_of>clock_timestamp() or new.rule_version<>'top-docked-net-units-v1' then raise exception 'Privileged reproducible snapshot required'; end if;
  new.created_at:=clock_timestamp(); return new;
end $$;
create trigger community_snapshot_guard before insert on beta_private.leaderboard_snapshots for each row execute function beta_private.community_snapshot_guard();
-- One durable job per captured snapshot, never an unbounded recipient loop in the admin request.
create table beta_private.leaderboard_notification_jobs (
  snapshot_id uuid primary key references beta_private.leaderboard_snapshots(id),
  cursor_profile_id uuid, created_at timestamptz not null default clock_timestamp(), completed_at timestamptz
);
create index on beta_private.leaderboard_notification_jobs(created_at) where completed_at is null;
alter table beta_private.leaderboard_notification_jobs enable row level security;
create function beta_private.leaderboard_notification_job() returns trigger language plpgsql set search_path='' as $$
declare previous beta_private.leaderboard_snapshots;
begin
  select * into previous from beta_private.leaderboard_snapshots where id=new.previous_id;
  if previous.id is not null and previous.as_of<new.as_of and previous.rule_version=new.rule_version
    and previous.period=new.period and previous.sport is not distinct from new.sport
    and previous.payload->'from' is not distinct from new.payload->'from' then
    insert into beta_private.leaderboard_notification_jobs(snapshot_id) values(new.id) on conflict do nothing;
  end if;
  return new;
end $$;
create trigger leaderboard_notification_job after insert on beta_private.leaderboard_snapshots for each row execute function beta_private.leaderboard_notification_job();

do $$ declare t text; begin foreach t in array array['community_verification_rules','community_quote_evidence','community_edges','community_edge_status','community_result_sources','community_settlements','community_corrections','leaderboard_rule_versions','leaderboard_snapshots'] loop
  execute format('alter table beta_private.%I enable row level security',t);
  execute format('create trigger immutable before update or delete on beta_private.%I for each row execute function beta_private.immutable()',t);
end loop; end $$;
revoke all on all tables in schema beta_private from public,anon,authenticated;
revoke all on function beta_private.community_quote_evidence_guard(),beta_private.community_submission_retry(uuid,uuid,text),beta_private.community_edge_guard(),beta_private.community_snapshot_lock(),beta_private.community_status_guard(),beta_private.community_result_source_guard(),beta_private.community_settlement_guard(),beta_private.community_settlement_correction(),beta_private.community_snapshot_guard(),beta_private.leaderboard_notification_job() from public,anon,authenticated;


-- SOURCE 20261003021118_session_helper_execute_hardening.sql sha256=4d06c780ea480f8e880e143112e535d039dfaf2427b07347b26f7335abfd6453
-- PostgreSQL's built-in global PUBLIC EXECUTE default is not removed by a
-- schema-scoped ALTER DEFAULT PRIVILEGES REVOKE. Explicitly narrow this one
-- intentionally callable SECURITY DEFINER helper to authenticated members.
-- Anonymous callers also lack private schema USAGE; retain both boundaries.
revoke all on function beta_private.active_member_session() from public, anon;
grant execute on function beta_private.active_member_session() to authenticated;


-- SOURCE 20261003030722_phase4_market_reference.sql sha256=6d8b2fe64cfb8f6811e8ad9585c35e24a02452bce722b1141ffca0997738e3a5
-- Additive benchmark model. Historical bookmaker publications are not relabelled.
create table beta_private.market_references (
 id uuid primary key default gen_random_uuid(),market_id text not null references beta_private.markets(id),selection text not null,
 methodology_version text not null,config_hash text not null check(length(config_hash)=64),configuration jsonb not null,
 reference jsonb not null,snapshot_ids text[] not null,decimal_price numeric not null check(decimal_price>1),observed_at timestamptz not null,
 region_policy_id uuid not null references beta_private.region_policies(id),created_at timestamptz not null default clock_timestamp()
);
alter table beta_private.market_references enable row level security;
create trigger immutable before update or delete on beta_private.market_references for each row execute function beta_private.immutable();
create function beta_private.reference_canonical_json(value jsonb) returns text language sql immutable set search_path='' as $$
 select case jsonb_typeof(value)
 when 'object' then '{'||coalesce((select string_agg(to_jsonb(key)::text||':'||beta_private.reference_canonical_json(v),',' order by key collate "C") from jsonb_each(value)e(key,v)),'')||'}'
 when 'array' then '['||coalesce((select string_agg(beta_private.reference_canonical_json(v),',' order by n) from jsonb_array_elements(value) with ordinality e(v,n)),'')||']'
 else value::text end
$$;
create table beta_private.market_reference_methodologies(version text primary key,config_hash text not null,configuration jsonb not null,created_at timestamptz not null default clock_timestamp());
alter table beta_private.market_reference_methodologies enable row level security;
create trigger immutable before update or delete on beta_private.market_reference_methodologies for each row execute function beta_private.immutable();
revoke all on beta_private.market_reference_methodologies from public,anon,authenticated;
revoke all on function beta_private.reference_canonical_json(jsonb) from public,anon,authenticated;
create function beta_private.reference_cohort_sources(p_market text,p_config jsonb,p_policy uuid,p_at timestamptz,p_cohort text)
returns table(id text,bookmaker text,operator text,price numeric,source_at timestamptz,prices jsonb) language sql stable set search_path='' as $$
 with latest as(select distinct on(q.bookmaker) q.* from beta_private.odds_snapshots q where q.market_id=p_market and q.evidence in ('forward_paper','live_published') order by q.bookmaker,q.source_at desc,q.received_at desc,q.id desc),
 valid as(select q.id,q.bookmaker,q.payload->>'operator' operator,q.source_at,q.payload->'prices' prices from latest q
 join beta_private.markets m on m.id=q.market_id join beta_private.events e on e.id=m.event_id
 join beta_private.community_quote_evidence v on v.snapshot_id=q.id join beta_private.source_health h on h.provider=q.provider
 where p_config->p_cohort ? q.bookmaker and length(btrim(q.provider))>0 and length(btrim(q.payload->>'operator'))>0 and length(btrim(h.rights_reference))>0 and length(btrim(v.classification_version))>0 and length(btrim(v.classification_evidence))>0 and v.classification='STANDARD_VERIFIED' and v.metadata->>'sourceType'='bookmaker' and v.metadata->'promotionFlags'='[]'
 and q.payload->'rules'=m.rules and q.payload->>'suspended'='false' and v.observed_start_at=e.start_at and v.provider_event_id=e.source_mappings->>q.provider
 and h.healthy and h.last_success between p_at-interval '3 minutes' and p_at and h.rights_reference=q.provenance and h.rights_reference=v.rights_reference
 and h.capabilities->>'display'='true' and h.capabilities->>'retention'='true' and h.capabilities->>'community_standard_prices'='true'
 and q.source_at<=q.snapshot_at and q.snapshot_at<=q.received_at and q.received_at<=p_at and q.source_at>=p_at-(p_config->>'maxAgeSeconds')::int*interval '1 second'
 and (select count(*) from jsonb_object_keys(q.payload->'prices'))=jsonb_array_length(m.rules->'outcomes')
 and not exists(select 1 from jsonb_array_elements_text(m.rules->'outcomes') o where not(q.payload->'prices' ? o) or (q.payload->'prices'->>o)::numeric<=1 or (q.payload->'prices'->>o)::numeric>1000)
 and (select sum(1/value::numeric) from jsonb_each_text(q.payload->'prices')) between 0.95 and 1.25
 and exists(select 1 from beta_private.bookmaker_eligibility b join beta_private.region_policies r on r.id=b.region_policy_id where b.bookmaker=q.bookmaker and b.operator_group=q.payload->>'operator' and length(btrim(b.rights_reference))>0 and b.approved and b.effective_from<=p_at and b.effective_to>p_at and r.approved and r.effective_from<=p_at and r.effective_to>p_at and r.review_at>p_at and q.bookmaker=any(r.operators) and (p_cohort='pricingBookmakers' or r.id=p_policy))
 and not exists(select 1 from beta_private.bookmaker_eligibility b join beta_private.region_policies r on r.id=b.region_policy_id where b.bookmaker=q.bookmaker and b.operator_group<>q.payload->>'operator' and b.approved and b.effective_from<=p_at and b.effective_to>p_at and r.approved and r.effective_from<=p_at and r.effective_to>p_at and r.review_at>p_at)
 and (p_cohort='pricingBookmakers' or not exists(select 1 from latest pq where p_config->'pricingBookmakers' ? pq.bookmaker and pq.payload->>'operator'=q.payload->>'operator')))
 select distinct on(v.operator collate "C") v.id,v.bookmaker,v.operator,null::numeric,v.source_at,v.prices from valid v order by v.operator collate "C",v.bookmaker collate "C"
$$;
create function beta_private.reference_expected_availability(p_market text,p_config jsonb,p_policy uuid,p_at timestamptz,p_selection text)
returns text[] language sql stable set search_path='' as $$
 with cohort as(select c.*,(c.prices->>p_selection)::numeric selection_price from beta_private.reference_cohort_sources(p_market,p_config,p_policy,p_at,'availabilityBookmakers') c),
 centre as(select selection_price price from cohort order by selection_price offset greatest(0,((select count(*) from cohort)-1)/2) limit 1)
 select coalesce(array_agg(c.id order by c.bookmaker collate "C"),'{}') from cohort c cross join centre m where abs(c.selection_price/m.price-1)<=(p_config->>'maxAvailabilityDeviation')::numeric
$$;
create function beta_private.market_reference_guard() returns trigger language plpgsql set search_path='' as $$
declare m beta_private.markets; e beta_private.events; q beta_private.odds_snapshots; v beta_private.community_quote_evidence; h beta_private.source_health; r beta_private.region_policies;
 selected_probability numeric; implied_total numeric; probability_sum numeric:=0;
 expected text[]; outcome text; canonical_sources jsonb; expected_hash text;
 sid text; availability text[]; pricing text[]; operators text[]:='{}'; pricing_operators text[]:='{}'; prices numeric[]:='{}'; price numeric; raw_price numeric; checked timestamptz;
begin
 perform pg_advisory_xact_lock(hashtext('reference-methodology:'||new.methodology_version));
 select * into m from beta_private.markets where id=new.market_id for update;
 select * into e from beta_private.events where id=m.event_id for share;
 select * into r from beta_private.region_policies where id=new.region_policy_id for share;
 -- Lock the complete current market/cohort inputs before taking the freshness clock.
 perform 1 from beta_private.odds_snapshots where market_id=m.id for share;
 perform 1 from beta_private.community_quote_evidence where snapshot_id in(select id from beta_private.odds_snapshots where market_id=m.id) for share;
 perform 1 from beta_private.source_health where provider in(select provider from beta_private.odds_snapshots where market_id=m.id) for share;
 perform 1 from beta_private.bookmaker_eligibility where new.configuration->'pricingBookmakers' ? bookmaker or new.configuration->'availabilityBookmakers' ? bookmaker for share;
 perform 1 from beta_private.region_policies for share;
 checked:=clock_timestamp();
 if new.methodology_version !~ '^market-reference-v[0-9]+\.[0-9]+\.[0-9]+(-[a-z0-9-]+)?$' then raise exception 'Versioned methodology required'; end if;
 expected_hash:=encode(sha256(convert_to(beta_private.reference_canonical_json(new.configuration),'UTF8')),'hex');
 if expected_hash is distinct from new.config_hash or new.reference->>'rulesHash' is distinct from encode(sha256(convert_to(beta_private.reference_canonical_json(m.rules),'UTF8')),'hex') then raise exception 'Canonical reference/configuration hash mismatch'; end if;
 if new.configuration->>'validationStatus' is distinct from 'UNVALIDATED' or new.configuration->>'availabilityMethod' is distinct from 'independent-lower-median'
 or new.configuration->>'pricingMethod' is distinct from 'proportional-equal-independent-disjoint' or new.configuration->>'allowReactivation' is distinct from 'false'
 or new.configuration->>'exchangeSupport' is distinct from 'false' or new.configuration->>'tick' is distinct from '0.01'
 or new.configuration->>'version' is distinct from new.methodology_version or new.reference->>'methodologyVersion' is distinct from new.methodology_version
 or new.reference->>'configHash' is distinct from new.config_hash or new.reference->>'evidenceMode' is distinct from 'current'
 or new.reference->>'selection' is distinct from new.selection or (new.reference->>'decimalPrice')::numeric is distinct from new.decimal_price
 or (new.reference->>'observedAt')::timestamptz is distinct from new.observed_at
 or not(m.rules->'outcomes' ? new.selection) then raise exception 'Reference methodology mismatch'; end if;
 if not coalesce((new.configuration->>'maxAgeSeconds')::int between 1 and 180 and (new.configuration->>'maxSkewSeconds')::int between 0 and 90 and (new.configuration->>'maxAvailabilitySpread')::numeric between 0 and 0.10 and (new.configuration->>'maxProbabilityDisagreement')::numeric between 0 and 0.08 and (new.configuration->>'minPricingSources')::int>=2 and (new.configuration->>'minAvailabilitySources')::int>=2,false) then raise exception 'Bounded reference controls required'; end if;
 if not coalesce((new.configuration->>'maxAvailabilityDeviation')::numeric between 0 and 0.20 and (new.configuration->>'cutoffSeconds')::int>=600 and (new.configuration->>'minPricingSources')::int<=20 and (new.configuration->>'minAvailabilitySources')::int<=20,false) then raise exception 'Bounded reference configuration required'; end if;
 if jsonb_typeof(new.configuration->'pricingBookmakers') is distinct from 'array' or jsonb_typeof(new.configuration->'availabilityBookmakers') is distinct from 'array'
 or exists(select 1 from jsonb_array_elements((new.configuration->'pricingBookmakers')||(new.configuration->'availabilityBookmakers')) elem(value) where jsonb_typeof(elem.value)<>'string' or elem.value='""'::jsonb)
 or (select count(distinct elem.value) from jsonb_array_elements((new.configuration->'pricingBookmakers')||(new.configuration->'availabilityBookmakers')) elem(value))<>jsonb_array_length(new.configuration->'pricingBookmakers')+jsonb_array_length(new.configuration->'availabilityBookmakers') then raise exception 'Unique named source cohorts required'; end if;
 if exists(select 1 from jsonb_array_elements_text(new.configuration->'pricingBookmakers') b where new.configuration->'availabilityBookmakers' ? b) then raise exception 'Disjoint named source cohorts required'; end if;
 if e.status<>'scheduled' or e.start_at<=checked+greatest(600,(new.configuration->>'cutoffSeconds')::int)*interval '1 second'
 or new.observed_at>checked or new.observed_at<checked-interval '3 minutes' then raise exception 'Current pre-event reference required'; end if;
 if r.id is null or not r.approved or r.effective_from>checked or r.effective_to<=checked or r.review_at<=checked then raise exception 'Reference region unavailable'; end if;
 select array_agg(value) into availability from jsonb_array_elements_text(new.reference->'availability'->'sourceIds');
 select array_agg(value) into pricing from jsonb_array_elements_text(new.reference->'pricing'->'sourceIds');
 pricing:=coalesce(pricing,'{}');
 if cardinality(pricing)=0 and new.reference->'pricing' is distinct from 'null'::jsonb then raise exception 'Probability requires independent pricing source evidence'; end if;
 if cardinality(pricing)>0 and cardinality(pricing)<greatest(2,(new.configuration->>'minPricingSources')::int) then raise exception 'Independent pricing evidence required'; end if;
 if coalesce(cardinality(availability),0)<greatest(2,(new.configuration->>'minAvailabilitySources')::int)
 or cardinality(new.snapshot_ids)<>cardinality(availability)+cardinality(pricing)
 or not(new.snapshot_ids @> (availability||pricing)) or cardinality(new.snapshot_ids)<>(select count(distinct x) from unnest(new.snapshot_ids)x)
 then raise exception 'Independent source evidence required'; end if;
 foreach sid in array new.snapshot_ids loop
  select * into q from beta_private.odds_snapshots where id=sid for share;
  select * into v from beta_private.community_quote_evidence where snapshot_id=sid for share;
  select * into h from beta_private.source_health where provider=q.provider for share;
  if q.id is null or q.market_id is distinct from m.id or q.evidence not in ('forward_paper','live_published') or q.payload->'rules' is distinct from m.rules
  or q.payload->>'id' is distinct from q.id or q.payload->>'bookmaker' is distinct from q.bookmaker or coalesce((q.payload->>'suspended')::boolean,true)
  or v.id is null or v.metadata->>'sourceType' is distinct from 'bookmaker' or v.classification<>'STANDARD_VERIFIED' or jsonb_array_length(v.metadata->'promotionFlags')<>0
  or v.provider_event_id is distinct from e.source_mappings->>q.provider or v.observed_start_at is distinct from e.start_at
  or not coalesce(h.healthy,false) or h.last_success is null or h.last_success<checked-interval '3 minutes' or h.last_success>checked
  or h.rights_reference is distinct from q.provenance or h.rights_reference is distinct from v.rights_reference
  or not coalesce((h.capabilities->>'display')::boolean,false) or not coalesce((h.capabilities->>'retention')::boolean,false)
  or not coalesce((h.capabilities->>'community_standard_prices')::boolean,false)
  or (q.payload->>'sourceAt')::timestamptz is distinct from q.source_at or (q.payload->>'snapshotAt')::timestamptz is distinct from q.snapshot_at or (q.payload->>'receivedAt')::timestamptz is distinct from q.received_at
  or q.source_at>q.snapshot_at or q.snapshot_at>q.received_at or q.received_at>checked or q.received_at>new.observed_at
  or q.source_at<checked-least(180,(new.configuration->>'maxAgeSeconds')::int)*interval '1 second'
  or q.id is distinct from (select id from beta_private.odds_snapshots where market_id=m.id and bookmaker=q.bookmaker and evidence in ('forward_paper','live_published') order by source_at desc,received_at desc,id desc limit 1)
  then raise exception 'Reference source unavailable or stale'; end if;
  if not exists(select 1 from beta_private.bookmaker_eligibility b join beta_private.region_policies p on p.id=b.region_policy_id where b.bookmaker=q.bookmaker and b.operator_group=q.payload->>'operator' and length(btrim(b.rights_reference))>0 and b.approved and b.effective_from<=checked and b.effective_to>checked and p.approved and p.effective_from<=checked and p.effective_to>checked and p.review_at>checked and q.bookmaker=any(p.operators) and (not(sid=any(availability)) or p.id=r.id)) then raise exception 'Current ownership approval required'; end if;
  if (select count(*) from jsonb_object_keys(q.payload->'prices'))<>jsonb_array_length(m.rules->'outcomes')
  or exists(select 1 from jsonb_array_elements_text(m.rules->'outcomes') o where not(q.payload->'prices' ? o) or (q.payload->'prices'->>o)::numeric<=1 or (q.payload->'prices'->>o)::numeric>1000) then raise exception 'Complete standard market required'; end if;
  select sum(1/value::numeric) into implied_total from jsonb_each_text(q.payload->'prices');
  if implied_total not between 0.95 and 1.25 then raise exception 'Implausible source market'; end if;
  if sid=any(availability) then
   if not(new.configuration->'availabilityBookmakers' ? q.bookmaker) or q.payload->>'operator'=any(operators) then raise exception 'Availability cohort conflict'; end if;
   if exists(select 1 from beta_private.bookmaker_eligibility b where new.configuration->'pricingBookmakers' ? b.bookmaker and b.operator_group=q.payload->>'operator' and b.approved and b.effective_from<=checked and b.effective_to>checked) then raise exception 'Pricing ownership excluded from availability'; end if;
   operators:=array_append(operators,q.payload->>'operator');prices:=array_append(prices,(q.payload->'prices'->>new.selection)::numeric);
  else
   if not(new.configuration->'pricingBookmakers' ? q.bookmaker) or q.payload->>'operator'=any(pricing_operators) then raise exception 'Pricing cohort conflict'; end if;
   probability_sum:=probability_sum+(1/(q.payload->'prices'->>new.selection)::numeric)/implied_total;
   pricing_operators:=array_append(pricing_operators,q.payload->>'operator');
  end if;
 end loop;
  if m.rules->>'period' is distinct from 'full_game' or m.rules->'line' is distinct from 'null'::jsonb or not (m.rules->'outcomes' ? new.selection)
    or (m.rules->>'eventId') is distinct from e.id or (m.rules->>'competition') is distinct from e.competition_id
    or m.rules->'participants' is distinct from e.participants
    or not exists(select 1 from beta_private.competitions where id=e.competition_id and sport_id=case when e.competition_id='basketball_nba' then 'basketball' else 'football' end)
    or jsonb_array_length(m.rules->'participants')<>2 or m.rules->'participants'->>0=m.rules->'participants'->>1
    or (select jsonb_agg(o order by o) from jsonb_array_elements_text(m.rules->'outcomes') o)
      is distinct from (select jsonb_agg(o order by o) from jsonb_array_elements_text(m.rules->'participants' || case when m.rules->>'market'='football_1x2' then '["Draw"]'::jsonb else '[]'::jsonb end) o)
    or not coalesce(((e.competition_id in ('soccer_epl','soccer_spain_la_liga') and m.rules->>'market'='football_1x2' and m.rules->>'settlement'='regulation_90_plus_stoppage' and m.rules->>'overtime'='false' and m.rules->>'draw'='true')
      or (e.competition_id='basketball_nba' and m.rules->>'market'='nba_moneyline' and m.rules->>'settlement'='full_game_including_overtime' and m.rules->>'overtime'='true' and m.rules->>'draw'='false')),false)
    then raise exception 'Unsupported or mismatched community settlement rules'; end if;
 expected:=beta_private.reference_expected_availability(m.id,new.configuration,r.id,checked,new.selection);
 if availability is distinct from expected then raise exception 'Complete availability cohort required'; end if;
 if cardinality(pricing)>0 then
  select array_agg(c.id order by c.bookmaker collate "C") into expected from beta_private.reference_cohort_sources(m.id,new.configuration,r.id,checked,'pricingBookmakers') c;
  if pricing is distinct from expected then raise exception 'Complete pricing cohort required'; end if;
  for outcome in select jsonb_array_elements_text(m.rules->'outcomes') loop
   if (select max(p)-min(p) from (select (1/(c.prices->>outcome)::numeric)/(select sum(1/value::numeric) from jsonb_each_text(c.prices)) p from beta_private.reference_cohort_sources(m.id,new.configuration,r.id,checked,'pricingBookmakers') c) v)>(new.configuration->>'maxProbabilityDisagreement')::numeric then raise exception 'Pricing source disagreement'; end if;
  end loop;
  if new.reference->'pricing'->>'probability' is null or new.reference->'pricing'->>'fairPrice' is null or (new.reference->'pricing'->>'probability')::numeric not between 0.000000000001 and 0.999999999999 then raise exception 'Finite pricing probability required'; end if;
  selected_probability:=probability_sum/cardinality(pricing);
  if abs(selected_probability-(new.reference->'pricing'->>'probability')::numeric)>0.000000000001 or abs(1/selected_probability-(new.reference->'pricing'->>'fairPrice')::numeric)>0.000000000001 then raise exception 'Pricing probability mismatch'; end if;
 end if;
 if (select extract(epoch from(max(source_at)-min(source_at))) from beta_private.odds_snapshots where id=any(new.snapshot_ids))>(new.configuration->>'maxSkewSeconds')::int then raise exception 'Reference source skew'; end if;
 if (new.reference->>'sourceAt')::timestamptz is distinct from (select min(source_at) from beta_private.odds_snapshots where id=any(new.snapshot_ids)) then raise exception 'Reference source timestamp mismatch'; end if;
 if (new.reference->>'snapshotAt')::timestamptz is distinct from (select min(snapshot_at) from beta_private.odds_snapshots where id=any(new.snapshot_ids)) or (new.reference->>'receivedAt')::timestamptz is distinct from (select min(received_at) from beta_private.odds_snapshots where id=any(new.snapshot_ids)) or (new.reference->'availability'->>'sourceCount')::int is distinct from cardinality(availability) then raise exception 'Reference timestamp/count mismatch'; end if;
 if new.reference->'availability'->'operators' is distinct from (select jsonb_agg(qs.payload->>'operator' order by ids.n) from unnest(availability) with ordinality ids(id,n) join beta_private.odds_snapshots qs on qs.id=ids.id) or (cardinality(pricing)>0 and new.reference->'pricing'->'operators' is distinct from (select jsonb_agg(qs.payload->>'operator' order by ids.n) from unnest(pricing) with ordinality ids(id,n) join beta_private.odds_snapshots qs on qs.id=ids.id)) then raise exception 'Canonical ownership projection required'; end if;
 if operators && pricing_operators then raise exception 'Pricing and availability ownership overlap'; end if;
 select p into raw_price from unnest(prices) p order by p offset (cardinality(prices)-1)/2 limit 1;price:=floor(raw_price*100)/100;
 if new.decimal_price is distinct from price then raise exception 'Server lower median reference required'; end if;
 if (select (max(p)-min(p))/raw_price from unnest(prices)p)>(new.configuration->>'maxAvailabilitySpread')::numeric then raise exception 'Availability disagreement'; end if;
 select jsonb_agg(sq.payload||jsonb_build_object('approved',true,'provider',sq.provider,'sourceKind','bookmaker','licensed',true,'rightsReference',sh.rights_reference,'ownershipEvidence',b.rights_reference,'mappingVerified',true,'feedHealthy',true,'priceClass',cv.classification,'classificationVersion',cv.classification_version,'classificationEvidence',cv.classification_evidence,'promotionFlags',cv.metadata->'promotionFlags','provenance','current_provider') order by sq.id collate "C") into canonical_sources
 from beta_private.odds_snapshots sq join beta_private.community_quote_evidence cv on cv.snapshot_id=sq.id join beta_private.source_health sh on sh.provider=sq.provider
 join lateral(select be.rights_reference from beta_private.bookmaker_eligibility be join beta_private.region_policies rp on rp.id=be.region_policy_id where be.bookmaker=sq.bookmaker and be.approved and be.effective_from<=checked and be.effective_to>checked and rp.approved and rp.effective_from<=checked and rp.effective_to>checked and rp.review_at>checked and be.bookmaker=any(rp.operators) order by be.id limit 1)b on true where sq.id=any(new.snapshot_ids);
 expected_hash:=encode(sha256(convert_to(beta_private.reference_canonical_json(jsonb_build_object('config',new.configuration,'input',jsonb_build_object('rules',m.rules,'startAt',to_char(e.start_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'observedAt',new.reference->>'observedAt','selection',new.selection,'evidenceMode','current'),'sources',canonical_sources)),'UTF8')),'hex');
 if new.reference->>'evidenceHash' is distinct from expected_hash then raise exception 'Canonical source evidence hash mismatch'; end if;
 if exists(select 1 from beta_private.market_reference_methodologies where version=new.methodology_version and (configuration is distinct from new.configuration or config_hash is distinct from new.config_hash)) then raise exception 'Material reference changes require a new methodology version'; end if;
 insert into beta_private.market_reference_methodologies(version,config_hash,configuration) values(new.methodology_version,new.config_hash,new.configuration) on conflict do nothing;
 if e.start_at<=clock_timestamp()+greatest(600,(new.configuration->>'cutoffSeconds')::int)*interval '1 second' or (select min(source_at) from beta_private.odds_snapshots where id=any(new.snapshot_ids))<clock_timestamp()-(new.configuration->>'maxAgeSeconds')::int*interval '1 second' then raise exception 'Reference expired during finalization'; end if;
 new.created_at:=clock_timestamp();return new;
end $$;
create trigger market_reference_guard before insert on beta_private.market_references for each row execute function beta_private.market_reference_guard();

create function beta_private.assert_current_market_reference(p_id uuid) returns void language plpgsql set search_path='' as $$
declare r beta_private.market_references;e beta_private.events;p beta_private.region_policies;checked timestamptz;expected text[];
begin
 select * into r from beta_private.market_references where id=p_id for share;
 perform 1 from beta_private.markets where id=r.market_id for update;
 select e1.* into e from beta_private.events e1 join beta_private.markets m on m.event_id=e1.id where m.id=r.market_id for share of e1;
 select * into p from beta_private.region_policies where id=r.region_policy_id for share;
 perform 1 from beta_private.source_health where provider in(select provider from beta_private.odds_snapshots where market_id=r.market_id) for share;
 perform 1 from beta_private.bookmaker_eligibility where r.configuration->'pricingBookmakers' ? bookmaker or r.configuration->'availabilityBookmakers' ? bookmaker for share;
 checked:=clock_timestamp();
 if r.id is null or e.status<>'scheduled' or e.start_at<=checked+greatest(600,(r.configuration->>'cutoffSeconds')::int)*interval '1 second'
 or r.observed_at>checked or r.observed_at<checked-least(180,(r.configuration->>'maxAgeSeconds')::int)*interval '1 second'
 or not p.approved or p.effective_from>checked or p.effective_to<=checked or p.review_at<=checked then raise exception 'Reference no longer current'; end if;
 expected:=beta_private.reference_expected_availability(r.market_id,r.configuration,p.id,checked,r.selection);
 if to_jsonb(expected) is distinct from r.reference->'availability'->'sourceIds' then raise exception 'Reference availability changed'; end if;
 if r.reference->'pricing' is distinct from 'null'::jsonb then
  select array_agg(c.id order by c.bookmaker collate "C") into expected from beta_private.reference_cohort_sources(r.market_id,r.configuration,p.id,checked,'pricingBookmakers') c;
  if to_jsonb(expected) is distinct from r.reference->'pricing'->'sourceIds' then raise exception 'Reference pricing changed'; end if;
 end if;
end $$;
revoke all on function beta_private.assert_current_market_reference(uuid) from public,anon,authenticated;
alter table beta_private.community_edges add column pricing_model text not null default 'legacy_bookmaker_v1' check(pricing_model in ('legacy_bookmaker_v1','market_reference_v1'));
alter table beta_private.community_edges add column market_reference_id uuid references beta_private.market_references(id);
alter table beta_private.community_edges add column reference_payload jsonb;
alter table beta_private.community_edges alter column snapshot_id drop not null,alter column quote_evidence_id drop not null;
alter table beta_private.community_edges add constraint community_benchmark_version check((pricing_model='legacy_bookmaker_v1' and market_reference_id is null and snapshot_id is not null and quote_evidence_id is not null) or (pricing_model='market_reference_v1' and market_reference_id is not null and snapshot_id is null and quote_evidence_id is null and verification_rule='community-market-reference-v2'));
insert into beta_private.community_verification_rules(version,cutoff_seconds,max_age_seconds,standard_units) values('community-market-reference-v2',600,180,1);
drop trigger community_edge_guard on beta_private.community_edges;
create trigger community_edge_guard before insert on beta_private.community_edges for each row when(new.pricing_model='legacy_bookmaker_v1') execute function beta_private.community_edge_guard();
create function beta_private.community_reference_guard() returns trigger language plpgsql set search_path='' as $$
declare p beta_private.social_profiles; ref beta_private.market_references; m beta_private.markets; e beta_private.events; r beta_private.region_policies; checked timestamptz;
begin
 select * into p from beta_private.social_profiles where id=new.profile_id for update;
 if p.user_id is null or p.is_official or beta_private.community_actor(p.user_id,'community_edges',true) is distinct from p.id then raise exception 'Community member required'; end if;
 select * into ref from beta_private.market_references where id=new.market_reference_id for share;
 perform beta_private.assert_current_market_reference(new.market_reference_id);
 select * into m from beta_private.markets where id=ref.market_id for update;
 select * into e from beta_private.events where id=m.event_id for share;
 select * into r from beta_private.region_policies where id=new.region_policy_id for share;
 perform 1 from beta_private.feature_flags where key='community_edges' for share;checked:=clock_timestamp();
 if not coalesce((select enabled from beta_private.feature_flags where key='community_edges'),false) then raise exception 'Community Edge publication paused'; end if;
 if ref.id is null or ref.market_id is distinct from new.market_id or ref.selection is distinct from new.selection or m.event_id is distinct from new.event_id or ref.region_policy_id is distinct from r.id
 or new.odds is distinct from ref.decimal_price or new.verification_rule<>'community-market-reference-v2' then raise exception 'Immutable submission reference required'; end if;
 if e.status<>'scheduled' or e.start_at<=checked+interval '10 minutes' or ref.created_at<checked-interval '3 minutes' then raise exception 'EDGE SUBMISSIONS CLOSED or STALE reference'; end if;
 if not r.approved or r.minimum_age>18 or not('community_edges'=any(r.features)) or r.effective_from>checked or r.effective_to<=checked or r.review_at<=checked
 or not exists(select 1 from beta_public.profiles a where a.id=p.user_id and a.country=r.country and a.state=r.state and a.age_attested and a.disabled_at is null)
 or r.id is distinct from (select rp.id from beta_private.region_policies rp join beta_public.profiles a on a.country=rp.country and a.state=rp.state where a.id=p.user_id and rp.effective_from<=checked and rp.effective_to>checked order by rp.effective_from desc,rp.id desc limit 1) then raise exception 'Community jurisdiction denied'; end if;
 new.provider:='docked-market-reference';new.provider_event_id:=e.id;new.bookmaker:='Market reference';new.market_rules:=m.rules;new.competition:=e.competition_id;
 select sport_id into new.sport from beta_private.competitions where id=e.competition_id;
 new.reference_payload:=ref.reference;new.start_at:=e.start_at;new.source_at:=(ref.reference->>'sourceAt')::timestamptz;new.snapshot_at:=(ref.reference->>'snapshotAt')::timestamptz;new.received_at:=(ref.reference->>'receivedAt')::timestamptz;
 new.submitted_at:=checked;new.standard_units:=1;new.classification:='STANDARD_VERIFIED';return new;
end $$;
create trigger community_reference_guard before insert on beta_private.community_edges for each row when(new.pricing_model='market_reference_v1') execute function beta_private.community_reference_guard();

alter table beta_private.tip_publications add column pricing_model text not null default 'legacy_bookmaker_v1' check(pricing_model in ('legacy_bookmaker_v1','market_reference_v1'));
alter table beta_private.tip_publications add column market_reference_id uuid references beta_private.market_references(id);
alter table beta_private.tip_publications add constraint publication_benchmark_version check((pricing_model='legacy_bookmaker_v1' and market_reference_id is null) or (pricing_model='market_reference_v1' and market_reference_id is not null));
create function beta_private.publication_reference_guard() returns trigger language plpgsql set search_path='' as $$
declare ref beta_private.market_references;s beta_private.strategy_versions;
begin
 select * into ref from beta_private.market_references where id=new.market_reference_id for share;
 perform beta_private.assert_current_market_reference(new.market_reference_id);
 select * into s from beta_private.strategy_versions where id=new.strategy_id for share;
 if s.config->>'method' is distinct from 'market-reference-independent-cohorts' or s.config->'marketReference' is distinct from ref.configuration
 or ref.selection is distinct from new.selection or ref.region_policy_id is distinct from new.region_policy_id
 or new.odds is distinct from ref.decimal_price or new.probability is distinct from (ref.reference->'pricing'->>'probability')::numeric
 or ref.reference->'pricing' is null or ref.reference->'pricing'='null'::jsonb
 or ref.created_at<clock_timestamp()-interval '3 minutes'
 or not exists(select 1 from beta_private.markets where id=ref.market_id and event_id=new.event_id and rules=new.market_rules)
 then raise exception 'Immutable publication market reference required'; end if;
 if new.publication_payload->'reference' is distinct from ref.reference then raise exception 'Publication reference evidence mismatch'; end if;
 return new;
end $$;
create trigger publication_reference_guard before insert on beta_private.tip_publications for each row when(new.pricing_model='market_reference_v1') execute function beta_private.publication_reference_guard();
create table beta_private.market_reference_movements(id uuid primary key default gen_random_uuid(),tip_id uuid not null references beta_private.tip_publications(id),market_reference_id uuid references beta_private.market_references(id),status text not null check(status in ('ACTIVE','PRICE BELOW MINIMUM','EXPIRED','SUSPENDED','SETTLED')),observed_at timestamptz not null default clock_timestamp());
alter table beta_private.market_reference_movements enable row level security;
create index on beta_private.market_reference_movements(tip_id,observed_at desc,id desc);
create trigger immutable before update or delete on beta_private.market_reference_movements for each row execute function beta_private.immutable();
create function beta_private.reference_movement_guard() returns trigger language plpgsql set search_path='' as $$
declare p beta_private.tip_publications; ref beta_private.market_references; previous text;
begin
 select * into p from beta_private.tip_publications where id=new.tip_id for update;
 select status into previous from beta_private.market_reference_movements where tip_id=p.id order by observed_at desc,id desc limit 1;
 if p.pricing_model<>'market_reference_v1' then raise exception 'Reference publication required'; end if;
 if new.market_reference_id is not null then
  select * into ref from beta_private.market_references where id=new.market_reference_id;
  if ref.selection is distinct from p.selection or ref.configuration is distinct from p.publication_payload->'referenceConfig'
  or not exists(select 1 from beta_private.markets where id=ref.market_id and event_id=p.event_id and rules=p.market_rules) then raise exception 'Movement reference mismatch'; end if;
 end if;
 if ((previous='SETTLED' and new.status<>'SETTLED') or (previous='EXPIRED' and new.status not in ('EXPIRED','SETTLED'))) then raise exception 'Terminal reference status'; end if;
 if new.status='SETTLED' and not exists(select 1 from beta_private.settlement_events where tip_id=p.id and result in ('won','lost','void')) then raise exception 'Verified settlement required'; end if;
 if new.status='ACTIVE' and (exists(select 1 from beta_private.settlement_events where tip_id=p.id and result in ('won','lost','void')) or exists(select 1 from beta_private.events where id=p.event_id and (status<>'scheduled' or start_at<=clock_timestamp()+interval '10 minutes'))) then raise exception 'Publication already settled or expired'; end if;
 if new.status in ('ACTIVE','PRICE BELOW MINIMUM') then perform beta_private.assert_current_market_reference(new.market_reference_id); end if;
 if new.status='ACTIVE' and (coalesce(previous,'ACTIVE')<>'ACTIVE' or ref.id is null or ref.decimal_price<p.minimum_odds or ref.created_at<clock_timestamp()-interval '3 minutes') then raise exception 'Reference reactivation disabled'; end if;
 if new.status='PRICE BELOW MINIMUM' and (ref.id is null or ref.decimal_price>=p.minimum_odds) then raise exception 'Below-minimum evidence required'; end if;
 new.observed_at:=clock_timestamp();return new;
end $$;
create trigger reference_movement_guard before insert on beta_private.market_reference_movements for each row execute function beta_private.reference_movement_guard();
revoke all on beta_private.market_references,beta_private.market_reference_movements from public,anon,authenticated;
revoke all on function beta_private.market_reference_guard(),beta_private.community_reference_guard(),beta_private.publication_reference_guard(),beta_private.reference_movement_guard() from public,anon,authenticated;

revoke all on function beta_private.reference_cohort_sources(text,jsonb,uuid,timestamptz,text),beta_private.reference_expected_availability(text,jsonb,uuid,timestamptz,text) from public,anon,authenticated;

-- Optional claims are erasable social data, never part of the permanent accounting ledger.
create table beta_private.community_edge_personal_notes(edge_id uuid primary key references beta_private.community_edges(id),metadata jsonb not null,created_at timestamptz not null default clock_timestamp());
alter table beta_private.community_edge_personal_notes enable row level security;
create function beta_private.community_personal_note_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if not beta_private.active_member_session() or not exists(select 1 from beta_private.community_edges e join beta_private.social_profiles p on p.id=e.profile_id where e.id=new.edge_id and p.user_id=auth.uid() and p.status='active') then raise exception 'Own social commentary only'; end if;
 if jsonb_typeof(new.metadata)<>'object' or exists(select 1 from jsonb_object_keys(new.metadata)k where k not in ('bookmaker','price','promotional'))
 or length(coalesce(new.metadata->>'bookmaker',''))>100 or (new.metadata ? 'price' and not coalesce((new.metadata->>'price')::numeric>1 and (new.metadata->>'price')::numeric<=1000,false))
 or (new.metadata ? 'promotional' and jsonb_typeof(new.metadata->'promotional')<>'boolean') then raise exception 'Personal social metadata invalid'; end if;
 return new;
end $$;
create trigger community_personal_note_guard before insert or update on beta_private.community_edge_personal_notes for each row execute function beta_private.community_personal_note_guard();
create function beta_private.community_personal_note_erasure() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' and (new.disabled_at is null or old.disabled_at is not null) then return new; end if;
 delete from beta_private.community_edge_personal_notes where edge_id in(select e.id from beta_private.community_edges e join beta_private.social_profiles p on p.id=e.profile_id where p.user_id=old.id);
 if tg_op='DELETE' then return old;end if;return new;
end $$;
create trigger phase4_personal_note_erasure before delete or update of disabled_at on beta_public.profiles for each row execute function beta_private.community_personal_note_erasure();
revoke all on beta_private.community_edge_personal_notes from public,anon,authenticated;
revoke all on function beta_private.community_personal_note_guard(),beta_private.community_personal_note_erasure() from public,anon,authenticated;


-- SOURCE 20261003061548_hosted_preview_tester_community.sql sha256=40f39bc156e493f3330af7c24bf21f7760d8291917243202ca2302e7fb997b55
-- Infrastructure only. No account, grant, policy approval or sporting record is created.
alter table beta_private.region_policies add column preview_community_only boolean not null default false;
alter table beta_private.region_policies add constraint preview_community_scope check (
 (not preview_community_only or (
   country='XX' and state='DOCKED_PREVIEW' and minimum_age=18
   and cardinality(features)>0 and features <@ array['community_social','public_profiles']::text[]
   and cardinality(operators)=0 and evidence like 'PREVIEW TEST ONLY:%'
 )) and (country<>'XX' or state<>'DOCKED_PREVIEW' or preview_community_only)
);

create table beta_private.preview_tester_access (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references beta_public.profiles(id) on delete cascade,
 policy_id uuid not null references beta_private.region_policies(id),
 project_ref text not null check(project_ref='bckkllmndoxzpzdqrevb'),
 created_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null,
 granted_by text not null check(length(btrim(granted_by)) between 3 and 200),
 reason text not null check(length(btrim(reason)) between 10 and 1000),
 revoked_at timestamptz,
 revoked_by text,
 revocation_reason text,
 check(expires_at>created_at and expires_at<=created_at+interval '7 days'),
 check((revoked_at is null and revoked_by is null and revocation_reason is null)
   or (revoked_at is not null and revoked_by is not null and revocation_reason is not null
      and revoked_at>=created_at and length(btrim(revoked_by)) between 3 and 200
      and length(btrim(revocation_reason)) between 10 and 1000))
);
create index preview_tester_access_user on beta_private.preview_tester_access(user_id,policy_id) where revoked_at is null;
alter table beta_private.preview_tester_access enable row level security;
revoke all on beta_private.preview_tester_access from public,anon,authenticated;

create function beta_private.preview_tester_grant_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' and (
  old.revoked_at is not null or new.revoked_at is null
  or (to_jsonb(new)-array['revoked_at','revoked_by','revocation_reason']) is distinct from
     (to_jsonb(old)-array['revoked_at','revoked_by','revocation_reason'])
 ) then raise exception 'Preview grants are immutable except first revocation'; end if;
 if not exists(select 1 from beta_private.region_policies where id=new.policy_id and preview_community_only)
 then raise exception 'Preview community policy required'; end if;
 insert into beta_private.audit_events(actor,action,subject,details)
 values(case when tg_op='INSERT' then new.granted_by else new.revoked_by end,
  case when tg_op='INSERT' then 'preview_tester_granted' else 'preview_tester_revoked' end,
  new.id::text,jsonb_build_object('policyId',new.policy_id,'projectRef',new.project_ref,'expiresAt',new.expires_at,
   'reason',case when tg_op='INSERT' then new.reason else new.revocation_reason end));
 return new;
end $$;
create trigger preview_tester_grant_guard before insert or update on beta_private.preview_tester_access
 for each row execute function beta_private.preview_tester_grant_guard();

-- This GUC is set only by the trusted server after the complete hosted-preview guard.
-- Browser roles cannot access this function/schema/table; a GUC or user_metadata alone grants nothing.
create function beta_private.preview_tester_policy(p_actor uuid,p_feature text) returns uuid
 language sql volatile set search_path='' as $$
 select p.id from beta_private.preview_tester_access a
 join beta_private.region_policies p on p.id=a.policy_id
 join beta_public.profiles m on m.id=a.user_id
 where current_setting('docked.hosted_preview_project',true)='bckkllmndoxzpzdqrevb'
 and p_feature in ('community_social','public_profiles')
 and a.user_id=p_actor and a.project_ref='bckkllmndoxzpzdqrevb'
 and a.created_at<=clock_timestamp() and a.expires_at>clock_timestamp() and a.revoked_at is null
 and m.disabled_at is null and m.age_attested and m.accepted_version<>''
 and p.preview_community_only and p.approved and p.minimum_age=18
 and p.country='XX' and p.state='DOCKED_PREVIEW' and cardinality(p.operators)=0
 and p.features <@ array['community_social','public_profiles']::text[] and p_feature=any(p.features)
 and p.evidence like 'PREVIEW TEST ONLY:%'
 and p.effective_from<=clock_timestamp() and p.effective_to>clock_timestamp() and p.review_at>clock_timestamp()
 order by a.created_at desc,a.id desc limit 1
$$;

create or replace function beta_private.community_feature_allowed(p_actor uuid,p_feature text) returns boolean
 language sql volatile set search_path='' as $$
 select coalesce((select policy.approved and policy.minimum_age=18 and policy.review_at>clock_timestamp()
 and length(trim(policy.evidence))>0 and p_feature=any(policy.features)
 from beta_public.profiles member
 join lateral (select * from beta_private.region_policies r
   where not r.preview_community_only and r.country=member.country and r.state=member.state
   and r.effective_from<=clock_timestamp() and r.effective_to>clock_timestamp()
   order by r.effective_from desc,r.id desc limit 1) policy on true
 where member.id=p_actor and member.disabled_at is null and member.age_attested and member.accepted_version<>''),false)
 or beta_private.preview_tester_policy(p_actor,p_feature) is not null
$$;

create or replace function beta_private.community_assert_access(p_actor uuid,p_feature text) returns void
 language plpgsql set search_path='' as $$
declare member beta_public.profiles; policy beta_private.region_policies; preview_policy uuid;
begin
 if p_actor is distinct from auth.uid() or not beta_private.active_member_session()
 then raise exception 'Active authenticated session required'; end if;
 select * into member from beta_public.profiles where id=p_actor for share;
 if not found or member.disabled_at is not null or not member.age_attested or member.accepted_version=''
 then raise exception 'Account ineligible'; end if;
 select * into policy from beta_private.region_policies
 where not preview_community_only and country=member.country and state=member.state
 and effective_from<=clock_timestamp() and effective_to>clock_timestamp()
 order by effective_from desc,id desc limit 1 for share;
 if found and policy.approved and policy.minimum_age=18 and policy.review_at>clock_timestamp()
 and policy.effective_from<=clock_timestamp() and policy.effective_to>clock_timestamp()
 and length(trim(policy.evidence))>0 and p_feature=any(policy.features) then return; end if;
 preview_policy := beta_private.preview_tester_policy(p_actor,p_feature);
 if preview_policy is not null then
  -- Revocation/expiry checks happen again AFTER all potentially blocking locks.
  perform 1 from beta_private.preview_tester_access a join beta_private.region_policies p on p.id=a.policy_id
   where a.user_id=p_actor and p.id=preview_policy for share of a,p;
  if beta_private.active_member_session() and beta_private.preview_tester_policy(p_actor,p_feature)=preview_policy then return; end if;
 end if;
 raise exception 'Community feature restricted';
end $$;

revoke all on function beta_private.preview_tester_grant_guard(),beta_private.preview_tester_policy(uuid,text),
 beta_private.community_feature_allowed(uuid,text),beta_private.community_assert_access(uuid,text) from public,anon,authenticated;


-- SOURCE 20261003062615_session_wall_clock_revalidation.sql sha256=99af89216a8c37bcffd118143722985926b518b7dbeb5f99dd25fcb6ac4e2229
-- Preserve the existing narrow own-session helper and ACL. Wall-clock expiry
-- must be re-evaluated after blocking policy/grant locks, not at transaction start.
create or replace function beta_private.active_member_session() returns boolean
language sql volatile security definer set search_path='' as $$
 select exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id
 where s.user_id=(select auth.uid()) and s.id::text=(select auth.jwt()->>'session_id')
 and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false)
 and (s.not_after is null or s.not_after>clock_timestamp()))
$$;
revoke all on function beta_private.active_member_session() from public,anon;
grant execute on function beta_private.active_member_session() to authenticated;


-- SOURCE 20261003121257_phase45_preview_beta_auth.sql sha256=db71f25e8d290bcda43dcf15654aa97ca4d878a6532c69026e06ee618228d3a9
-- Isolated preview invitations and app onboarding. No grants, accounts or policy approvals are seeded.
create function beta_private.preview_capabilities_valid(value text[]) returns boolean
language sql immutable set search_path='' as $$
 select value is not null and value @> array['community_social','public_profiles']::text[]
 and value <@ array['community_social','public_profiles','preview_market_fixtures','preview_top_docked']::text[]
 and cardinality(value)=(select count(distinct x) from unnest(value) x)
$$;
alter table beta_private.preview_tester_access add column capabilities text[] not null default array['community_social','public_profiles']::text[]
 check(beta_private.preview_capabilities_valid(capabilities));

create table beta_private.app_onboarding (
 user_id uuid primary key references beta_public.profiles(id) on delete cascade,
 interests text not null check(interests in ('edges','community','both')),
 version text not null default 'app-beta-2026-10', completed_at timestamptz not null default clock_timestamp()
);

create table beta_private.preview_beta_invitations (
 id uuid primary key default gen_random_uuid(), project_ref text not null check(project_ref='bckkllmndoxzpzdqrevb'),
 policy_id uuid not null references beta_private.region_policies(id),
 token_hash text unique check(token_hash ~ '^[a-f0-9]{64}$'), email_hash text check(email_hash ~ '^[a-f0-9]{64}$'),
 capabilities text[] not null check(beta_private.preview_capabilities_valid(capabilities)),
 fixture boolean not null default false,
 created_at timestamptz not null default clock_timestamp(), expires_at timestamptz not null,
 grant_hours integer not null check(grant_hours between 1 and 168),
 status text not null default 'pending' check(status in ('pending','reserved','redeemed','revoked','failed')),
 created_by text not null check(length(btrim(created_by)) between 3 and 200), reason text not null check(length(btrim(reason)) between 12 and 1000),
 reservation_id uuid, reserved_user_id uuid, redeemed_user_id uuid references beta_public.profiles(id) on delete set null,
 changed_at timestamptz not null default clock_timestamp(),
 check(expires_at>created_at and expires_at<=created_at+interval '7 days'),
 check(status not in ('pending','reserved') or (token_hash is not null and email_hash is not null)),
 check(status<>'reserved' or (reservation_id is not null and reserved_user_id is not null))
);
create index preview_beta_invitation_status on beta_private.preview_beta_invitations(status,expires_at);

create function beta_private.preview_invitation_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' and old.redeemed_user_id is not null and new.redeemed_user_id is null
 and old.status in ('redeemed','failed','revoked') and (to_jsonb(new)-'redeemed_user_id')=(to_jsonb(old)-'redeemed_user_id')
 then return new; end if; -- Minimal FK erasure is permitted even after the environment/grant expires.
 if current_setting('docked.hosted_preview_project',true) is distinct from 'bckkllmndoxzpzdqrevb'
 then raise exception 'Exact hosted preview required'; end if;
 if tg_op='DELETE' then raise exception 'Revoke invitations; retain minimal audit'; end if;
 if not exists(select 1 from beta_private.region_policies p where p.id=new.policy_id and p.preview_community_only
   and p.country='XX' and p.state='DOCKED_PREVIEW' and p.minimum_age=18 and cardinality(p.operators)=0)
 then raise exception 'Isolated preview policy required'; end if;
 if tg_op='INSERT' and (new.status<>'pending' or new.reservation_id is not null or new.reserved_user_id is not null or new.redeemed_user_id is not null)
 then raise exception 'New invitation must be unused'; end if;
 if tg_op='UPDATE' then
  if (to_jsonb(new)-array['token_hash','email_hash','status','reservation_id','reserved_user_id','redeemed_user_id','changed_at']) is distinct from
     (to_jsonb(old)-array['token_hash','email_hash','status','reservation_id','reserved_user_id','redeemed_user_id','changed_at'])
  then raise exception 'Invitation authority is immutable'; end if;
  if not ((old.status='pending' and new.status in ('reserved','revoked')) or
    (old.status='reserved' and new.status in ('redeemed','failed','revoked')) or
    (old.status in ('redeemed','failed','revoked') and new.status=old.status and new.redeemed_user_id is null and old.redeemed_user_id is not null))
  then raise exception 'Invalid invitation lifecycle'; end if;
  if old.status<>'pending' and (new.reservation_id is distinct from old.reservation_id or new.reserved_user_id is distinct from old.reserved_user_id)
  then raise exception 'Reservation immutable'; end if;
  if old.status='pending' and new.status='reserved' and (old.token_hash is distinct from new.token_hash or old.email_hash is distinct from new.email_hash)
  then raise exception 'Reservation binding immutable'; end if;
  if new.status in ('reserved','redeemed') and (new.expires_at<=clock_timestamp() or not exists(select 1 from beta_private.region_policies p where p.id=new.policy_id and p.approved and p.effective_from<=clock_timestamp() and p.effective_to>clock_timestamp() and p.review_at>clock_timestamp()))
  then raise exception 'Invitation expired or restricted'; end if;
  if new.status='reserved' and new.redeemed_user_id is not null then raise exception 'Premature redemption'; end if;
  if new.status='redeemed' and (new.redeemed_user_id is null or new.redeemed_user_id is distinct from new.reserved_user_id)
  then raise exception 'Redemption must match reserved identity'; end if;
 end if;
 if new.status in ('redeemed','revoked','failed') then new.token_hash=null;new.email_hash=null; end if;
 new.changed_at=clock_timestamp();
 insert into beta_private.audit_events(actor,action,subject,details) values(coalesce(nullif(current_setting('docked.preview_actor',true),''),new.created_by),
  'preview_invitation_'||new.status,new.id::text,jsonb_build_object('projectRef',new.project_ref,'capabilities',new.capabilities,'expiresAt',new.expires_at));
 return new;
end $$;
create trigger preview_invitation_guard before insert or update or delete on beta_private.preview_beta_invitations
 for each row execute function beta_private.preview_invitation_guard();

create function beta_private.preview_tester_capability(p_actor uuid,p_capability text) returns boolean
language sql volatile set search_path='' as $$
 select coalesce(current_setting('docked.hosted_preview_project',true)='bckkllmndoxzpzdqrevb'
 and p_actor=auth.uid() and beta_private.active_member_session()
 and p_capability in ('community_social','public_profiles','preview_market_fixtures','preview_top_docked')
 and exists(select 1 from beta_private.preview_tester_access g join beta_private.region_policies p on p.id=g.policy_id
   join beta_public.profiles m on m.id=g.user_id
   where g.user_id=p_actor and g.project_ref='bckkllmndoxzpzdqrevb' and p_capability=any(g.capabilities)
   and g.created_at<=clock_timestamp() and g.expires_at>clock_timestamp() and g.revoked_at is null
   and m.disabled_at is null and m.age_attested and m.accepted_version<>''
   and p.preview_community_only and p.approved and p.country='XX' and p.state='DOCKED_PREVIEW' and p.minimum_age=18
   and p.features @> array['community_social','public_profiles']::text[] and p.features <@ array['community_social','public_profiles']::text[]
   and cardinality(p.operators)=0 and p.evidence like 'PREVIEW TEST ONLY:%'
   and p.effective_from<=clock_timestamp() and p.effective_to>clock_timestamp() and p.review_at>clock_timestamp()
   and (p_capability in ('community_social','public_profiles') or
    coalesce((select c.granted from beta_private.consent_events c where c.user_id=p_actor and c.purpose='privacy' order by c.created_at desc,c.id desc limit 1),false))
 ),false)
$$;

create function beta_private.assert_preview_tester_capability(p_actor uuid,p_capability text) returns uuid
language plpgsql set search_path='' as $$
declare g beta_private.preview_tester_access; p beta_private.region_policies;
begin
 if p_actor is distinct from auth.uid() or not beta_private.active_member_session()
 or current_setting('docked.hosted_preview_project',true) is distinct from 'bckkllmndoxzpzdqrevb'
 then raise exception 'Active exact preview session required'; end if;
 perform 1 from beta_public.profiles where id=p_actor for share;
 select * into g from beta_private.preview_tester_access where user_id=p_actor and p_capability=any(capabilities)
 and revoked_at is null and expires_at>clock_timestamp() order by created_at desc,id desc limit 1;
 if not found then raise exception 'Preview capability unavailable'; end if;
 select * into p from beta_private.region_policies where id=g.policy_id for share;
 select * into g from beta_private.preview_tester_access where id=g.id for share;
 if g.revoked_at is not null or g.expires_at<=clock_timestamp() or p.effective_to<=clock_timestamp()
 or p.review_at<=clock_timestamp() or p.effective_from>clock_timestamp() or not p.approved
 or not p.preview_community_only or p.minimum_age<>18 or cardinality(p.operators)<>0
 or not beta_private.preview_tester_capability(p_actor,p_capability)
 then raise exception 'Preview capability unavailable'; end if;
 return g.id;
end $$;

do $$ declare t text; begin foreach t in array array['app_onboarding','preview_beta_invitations'] loop
 execute format('alter table beta_private.%I enable row level security',t);
 execute format('revoke all on beta_private.%I from public,anon,authenticated',t);
end loop; end $$;
revoke all on function beta_private.preview_capabilities_valid(text[]),beta_private.preview_invitation_guard(),beta_private.preview_tester_capability(uuid,text),beta_private.assert_preview_tester_capability(uuid,text) from public,anon,authenticated;

create function beta_private.assert_preview_beta_admin() returns void language plpgsql set search_path='' as $$
