 if current_setting('docked.hosted_preview_project',true) is distinct from 'bckkllmndoxzpzdqrevb'
 or not beta_private.active_member_session() or auth.jwt()->>'aal' is distinct from 'aal2'
 or not exists(select 1 from beta_private.roles where user_id=auth.uid() and role in ('owner','admin'))
 then raise exception 'Preview administrator MFA required'; end if;
end $$;
