-- SOURCE 20261003121502_phase45_preview_market_fixtures.sql sha256=f962de05d2377856874891d8a3f18b904ad3f20683555f63f99ef670ab3a134a
-- Isolated synthetic UX records. Deliberately no canonical event/market/ledger
-- foreign keys and no social-post projection, outcomes, ranking or prize fields.
create table beta_private.preview_market_sessions(
 id uuid primary key, profile_id uuid not null references beta_private.social_profiles(id),
 fixture_id text not null check(fixture_id in ('demo-football','demo-basketball')),
 selection text not null check(length(selection) between 1 and 80),
 observed_at timestamptz not null,expires_at timestamptz not null,
 payload jsonb not null,payload_hash text not null check(payload_hash ~ '^[a-f0-9]{64}$')
);
create table beta_private.preview_fixture_edges(
 id uuid primary key default gen_random_uuid(),profile_id uuid not null references beta_private.social_profiles(id),
 session_id uuid not null references beta_private.preview_market_sessions(id),
 idempotency_key uuid not null,payload_hash text not null check(payload_hash ~ '^[a-f0-9]{64}$'),
 submitted_at timestamptz not null default clock_timestamp(),
 unique(profile_id,idempotency_key),unique(profile_id,session_id)
);
alter table beta_private.preview_market_sessions enable row level security;
alter table beta_private.preview_fixture_edges enable row level security;
revoke all on beta_private.preview_market_sessions,beta_private.preview_fixture_edges from public,anon,authenticated;
create trigger immutable before update or delete on beta_private.preview_market_sessions for each row execute function beta_private.immutable();
create trigger immutable before update or delete on beta_private.preview_fixture_edges for each row execute function beta_private.immutable();

create function beta_private.preview_fixture_guard() returns trigger language plpgsql security invoker set search_path='' as $$
declare actor uuid; snapshot beta_private.preview_market_sessions; checked_at timestamptz; source jsonb;
begin
 select p.user_id into actor from beta_private.social_profiles p where p.id=new.profile_id and p.status='active' for share;
 if actor is null or actor is distinct from auth.uid() then raise exception 'Preview fixture owner required'; end if;
 if tg_table_name='preview_fixture_edges' then
  select * into snapshot from beta_private.preview_market_sessions where id=new.session_id and profile_id=new.profile_id for update;
  if not found or new.payload_hash is distinct from snapshot.payload_hash then raise exception 'Preview review mismatch'; end if;
 end if;
 -- Rechecks exact project, expiry/revocation, verified active same-user session
 -- and explicit capability after source/profile locks. No metadata-based grant.
 perform beta_private.assert_preview_tester_capability(actor,'preview_market_fixtures');
 checked_at:=clock_timestamp();
 if tg_table_name='preview_market_sessions' then
  if new.observed_at>checked_at or new.observed_at<checked_at-interval '15 seconds'
   or new.expires_at is distinct from new.observed_at+interval '90 seconds'
   or new.payload->>'evidenceMode' is distinct from 'preview' or new.payload->'fixture' is distinct from 'true'::jsonb
   or new.payload->>'label' is distinct from 'DEMO / PREVIEW PRICE'
   or new.payload->>'fixtureId' is distinct from new.fixture_id or new.payload->>'selection' is distinct from new.selection
   or (new.payload->>'observedAt')::timestamptz is distinct from new.observed_at
   or (new.payload->>'expiresAt')::timestamptz is distinct from new.expires_at
   or (new.payload->>'startAt')::timestamptz is distinct from new.observed_at+interval '2 hours'
   or new.payload#>>'{rules,eventId}' is distinct from 'preview:'||new.id::text
   or new.payload#>>'{reference,evidenceMode}' is distinct from 'preview'
   or new.payload#>'{reference,fixture}' is distinct from 'true'::jsonb
   or new.payload#>>'{reference,label}' is distinct from 'DEMO / PREVIEW PRICE'
   or new.payload#>>'{reference,selection}' is distinct from new.selection
   or jsonb_typeof(new.payload->'sources') is distinct from 'array'
   or jsonb_array_length(new.payload->'sources') is distinct from 4
   or new.payload_hash is distinct from encode(sha256(convert_to(beta_private.reference_canonical_json(new.payload),'UTF8')),'hex')
  then raise exception 'Isolated synthetic preview evidence required'; end if;
  for source in select value from jsonb_array_elements(new.payload->'sources') loop
   if source->>'provenance' is distinct from 'fixture' or source->>'provider' is distinct from 'authored-preview-fixture'
    or source->>'bookmaker' not in ('DEMO-P1','DEMO-P2','DEMO-A1','DEMO-A2')
    or source->>'bookmaker' is null
   then raise exception 'Preview cannot import provider evidence'; end if;
  end loop;
 else
  if snapshot.expires_at<=checked_at or snapshot.observed_at>checked_at then raise exception 'Preview review expired'; end if;
  new.submitted_at:=checked_at;
 end if;
 return new;
end $$;
create trigger preview_fixture_guard before insert on beta_private.preview_market_sessions for each row execute function beta_private.preview_fixture_guard();
create trigger preview_fixture_guard before insert on beta_private.preview_fixture_edges for each row execute function beta_private.preview_fixture_guard();
create function beta_private.preview_fixture_audit() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 insert into beta_private.audit_events(actor,action,subject,details) values(new.profile_id::text,'preview_fixture_submitted',new.id::text,jsonb_build_object('fixture',true,'label','DEMO / PREVIEW PRICE','sessionId',new.session_id));
 return new;
end $$;
create trigger preview_fixture_audit after insert on beta_private.preview_fixture_edges for each row execute function beta_private.preview_fixture_audit();
revoke all on function beta_private.preview_fixture_guard(),beta_private.preview_fixture_audit() from public,anon,authenticated;


-- SOURCE 20261003143903_phase5_edge_scanner_market_data.sql sha256=6952403b415f2cfcd829c49d54493f072842bdffed14a6f776d6ee2783bd1287
-- Phase 5 infrastructure only. No provider, scanner, strategy or publication is activated.
-- Current sporting observations are not forward-paper selections or live publications.
alter type beta_public.evidence_type add value if not exists 'market_data';

-- New record serializer: UTF-8/C object order and plain normalized decimal numbers.
-- Existing strategy/reference serializers and hashes are deliberately unchanged.
create function beta_private.phase5_canonical_json(value jsonb) returns text language sql immutable set search_path='' as $$
 select case jsonb_typeof(value)
 when 'object' then '{'||coalesce((select string_agg(to_jsonb(key)::text||':'||beta_private.phase5_canonical_json(v),',' order by key collate "C") from jsonb_each(value)e(key,v)),'')||'}'
 when 'array' then '['||coalesce((select string_agg(beta_private.phase5_canonical_json(v),',' order by n) from jsonb_array_elements(value) with ordinality e(v,n)),'')||']'
 when 'number' then case when value::text::numeric=0 then '0' when position('.' in value::text)>0 then rtrim(rtrim(value::text,'0'),'.') else value::text end
 else value::text end
$$;
revoke all on function beta_private.phase5_canonical_json(jsonb) from public,anon,authenticated;


create table beta_private.scanner_schedules(
 id text primary key, configuration jsonb not null, enabled boolean not null default false,
 next_run timestamptz, updated_by uuid, updated_at timestamptz not null default clock_timestamp()
);
create table beta_private.scanner_runs(
 id uuid primary key default gen_random_uuid(),job_id uuid not null unique references beta_private.job_runs(id),
 schedule_id text references beta_private.scanner_schedules(id),purpose text not null check(purpose in ('research','paper','live')),
 strategy_id text not null references beta_private.strategy_versions(id),region_policy_id uuid not null references beta_private.region_policies(id),
 status text not null default 'RUNNING' check(status in ('RUNNING','SUCCEEDED','DEGRADED','FAILED')),
 started_at timestamptz not null default clock_timestamp(),finished_at timestamptz,
 metrics jsonb not null default '{}',rejections jsonb not null default '[]',error_code text
);
create table beta_private.scanner_candidates(
 id uuid primary key default gen_random_uuid(),dedupe_key text not null unique check(dedupe_key ~ '^[a-f0-9]{64}$'),
 run_id uuid not null references beta_private.scanner_runs(id),event_id text not null references beta_private.events(id),market_id text not null references beta_private.markets(id),
 strategy_id text not null references beta_private.strategy_versions(id),strategy_hash text not null,code_commit text not null check(code_commit ~ '^[a-f0-9]{40}$'),
 region_policy_id uuid not null references beta_private.region_policies(id),purpose text not null check(purpose in ('research','paper','live')),
 selection text not null,market_reference_id uuid not null references beta_private.market_references(id),model_version text not null,model_evidence jsonb not null,
 probability numeric not null check(probability>0 and probability<1),fair_odds numeric not null,minimum_odds numeric not null,
 required_ev numeric not null,estimated_ev numeric not null,window_seconds integer not null,
 scanned_at timestamptz not null,expires_at timestamptz not null,origin text not null check(origin in ('scheduled','manual')),
 created_by uuid,warnings jsonb not null default '[]',created_at timestamptz not null default clock_timestamp()
);
create table beta_private.scanner_run_markets(
 run_id uuid not null references beta_private.scanner_runs(id),market_id text not null references beta_private.markets(id),
 event_id text not null references beta_private.events(id),outcome jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(run_id,market_id)
);
create index scanner_candidate_recency on beta_private.scanner_candidates(scanned_at desc,id desc);
create table beta_private.scanner_reviews(
 id uuid primary key default gen_random_uuid(),candidate_id uuid not null references beta_private.scanner_candidates(id),
 status text not null check(status in ('NEEDS_REVIEW','APPROVED','REJECTED','EXPIRED','INVALIDATED')),
 actor uuid,reason text not null check(length(btrim(reason)) between 3 and 1000),category text,
 market_reference_id uuid references beta_private.market_references(id),publication_id uuid references beta_private.tip_publications(id),
 evidence jsonb not null default '{}',created_at timestamptz not null default clock_timestamp()
);
create index scanner_review_latest on beta_private.scanner_reviews(candidate_id,created_at desc,id desc);
create unique index scanner_once_approved on beta_private.scanner_reviews(candidate_id) where status='APPROVED';
create table beta_private.operational_alerts(
 id uuid primary key default gen_random_uuid(),dedupe_key text not null unique,kind text not null,
 severity text not null check(severity in ('info','warning','critical')),message text not null check(length(message) between 3 and 500),
 href text check(href ~ '^/admin(/|$)'),payload jsonb not null default '{}',created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null
);
create table beta_private.community_recognition_snapshots(
 id uuid primary key default gen_random_uuid(),rule_version text not null,week_start timestamptz not null,week_end timestamptz not null,
 as_of timestamptz not null,payload_hash text not null check(payload_hash ~ '^[a-f0-9]{64}$'),payload jsonb not null,actor text not null,
 created_at timestamptz not null default clock_timestamp(),unique(rule_version,week_start,as_of),check(week_end=week_start+interval '7 days' and as_of>=week_end)
);
insert into beta_private.feature_flags(key,enabled,reason) values('edge_scanner',false,'Scanner requires reviewed provider, research configuration and explicit activation'),('auto_publish_docked_edges',false,'Future auto-publication not implemented or activated') on conflict do nothing;

create function beta_private.scanner_assert_actor(p_manage boolean default false) returns uuid language plpgsql set search_path='' as $$
declare actor uuid:=auth.uid();
begin
 if actor is null or not beta_private.active_member_session() or auth.jwt()->>'aal' is distinct from 'aal2'
 or not exists(select 1 from beta_private.roles where user_id=actor and (role in ('owner','admin') or (not p_manage and role='analyst')))
 or not exists(select 1 from beta_public.profiles where id=actor and disabled_at is null)
 or not exists(select 1 from auth.users u where u.id=actor and coalesce(nullif(to_jsonb(u)->>'banned_until','')::timestamptz,'-infinity'::timestamptz)<=clock_timestamp())
 then raise exception 'Current scanner staff MFA required'; end if;
 return actor;
end $$;
create function beta_private.scanner_assert_worker(p_job uuid) returns void language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from beta_private.job_runs j where id=p_job and kind='edge-scan' and state='leased'
 and lease_token::text=current_setting('docked.scanner_lease',true) and id::text=current_setting('docked.scanner_job',true)
 and lease_until>clock_timestamp() and (
  (j.payload->>'origin'='manual' and exists(select 1 from beta_private.roles r join beta_public.profiles p on p.id=r.user_id join auth.users u on u.id=p.id join auth.sessions session on session.user_id=u.id where r.user_id::text=j.payload->>'actorId' and session.id::text=j.payload->>'actorSessionId' and (session.not_after is null or session.not_after>clock_timestamp()) and r.role in ('owner','admin','analyst') and p.disabled_at is null and coalesce(nullif(to_jsonb(u)->>'banned_until','')::timestamptz,'-infinity'::timestamptz)<=clock_timestamp()))
  or (coalesce(j.payload->>'origin','scheduled')='scheduled' and exists(select 1 from beta_private.feature_flags where key='edge_scanner' and enabled))
 )) then raise exception 'Active scanner worker lease and current authorization required'; end if;
end $$;
create function beta_private.scanner_schedule_guard() returns trigger language plpgsql set search_path='' as $$
declare actor uuid;
begin
 if tg_op='DELETE' then raise exception 'Disable scanner schedules; retain history'; end if;
 if tg_op='UPDATE' and current_setting('docked.scanner_scheduler',true)='true'
 and (to_jsonb(new)-array['next_run','updated_at'])=(to_jsonb(old)-array['next_run','updated_at']) then new.updated_at:=clock_timestamp();return new;end if;
 actor:=beta_private.scanner_assert_actor(true);
 if new.configuration->>'id' is distinct from new.id or (new.configuration->>'enabled')::boolean is distinct from new.enabled
 or new.configuration->>'provider' not in ('the-odds-api','odds-papi')
 or not coalesce((new.configuration->>'intervalSeconds')::int between 300 and 86400 and (new.configuration->>'nearIntervalSeconds')::int between 60 and (new.configuration->>'intervalSeconds')::int
 and (new.configuration->>'horizonSeconds')::int between 600 and 604800 and (new.configuration->>'nearEventSeconds')::int between 600 and (new.configuration->>'horizonSeconds')::int and (new.configuration->>'minQuotaRemaining')::int>=0,false)
 or not exists(select 1 from beta_private.strategy_versions where id=new.configuration->>'strategyId')
 or not exists(select 1 from beta_private.region_policies where id=(new.configuration->>'regionPolicyId')::uuid)
 then raise exception 'Bounded reviewed scanner schedule required';end if;
 new.updated_by:=actor;new.updated_at:=clock_timestamp();
 insert into beta_private.audit_events(actor,action,subject,details) values(actor::text,'scanner_schedule',new.id,jsonb_build_object('configuration',new.configuration));return new;
end $$;
create trigger scanner_schedule_guard before insert or update or delete on beta_private.scanner_schedules for each row execute function beta_private.scanner_schedule_guard();
create function beta_private.scanner_run_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Scanner run audit is retained';end if;
 perform beta_private.scanner_assert_worker(new.job_id);
 if tg_op='UPDATE' and ((to_jsonb(new)-array['status','finished_at','metrics','rejections','error_code']) is distinct from (to_jsonb(old)-array['status','finished_at','metrics','rejections','error_code']) or old.status<>'RUNNING') then raise exception 'Scanner run identity/completion immutable';end if;
 if new.status='RUNNING' then new.finished_at:=null;else new.finished_at:=clock_timestamp();end if;return new;
end $$;
create trigger scanner_run_guard before insert or update or delete on beta_private.scanner_runs for each row execute function beta_private.scanner_run_guard();
create function beta_private.scanner_market_guard() returns trigger language plpgsql set search_path='' as $$
declare run beta_private.scanner_runs;
begin
 select * into run from beta_private.scanner_runs where id=new.run_id for share;perform beta_private.scanner_assert_worker(run.job_id);
 if run.status is distinct from 'RUNNING' or not exists(select 1 from beta_private.markets where id=new.market_id and event_id=new.event_id) then raise exception 'Active canonical scan market required';end if;
 new.created_at:=clock_timestamp();return new;
end $$;
create trigger scanner_market_guard before insert on beta_private.scanner_run_markets for each row execute function beta_private.scanner_market_guard();
create trigger immutable before update or delete on beta_private.scanner_run_markets for each row execute function beta_private.immutable();
create function beta_private.scanner_strategy_allowed(p_strategy text,p_purpose text) returns boolean language sql stable set search_path='' as $$
 select coalesce((select case p_purpose when 'research' then lifecycle in ('RESEARCH','VALIDATED','FROZEN_FOR_FORWARD_PAPER','FORWARD_PAPER','APPROVED_FOR_LIVE')
 when 'paper' then lifecycle='FORWARD_PAPER' and active and frozen_at is not null and research_approved_at is not null
 when 'live' then lifecycle='APPROVED_FOR_LIVE' and active and frozen_at is not null and research_approved_at is not null and paper_approved_at is not null and owner_approved_at is not null else false end from beta_private.strategy_versions where id=p_strategy),false)
$$;
create function beta_private.scanner_candidate_guard() returns trigger language plpgsql set search_path='' as $$
declare run beta_private.scanner_runs;s beta_private.strategy_versions;r beta_private.market_references;m beta_private.markets;e beta_private.events;policy beta_private.region_policies;checked timestamptz;p numeric;
begin
 select * into run from beta_private.scanner_runs where id=new.run_id for share;perform beta_private.scanner_assert_worker(run.job_id);
 select * into s from beta_private.strategy_versions where id=new.strategy_id for share;
 select * into r from beta_private.market_references where id=new.market_reference_id for share;
 select * into m from beta_private.markets where id=new.market_id for share;select * into e from beta_private.events where id=m.event_id for share;
 select * into policy from beta_private.region_policies where id=new.region_policy_id for share;
 perform beta_private.assert_current_market_reference(r.id);checked:=clock_timestamp();
 perform beta_private.scanner_assert_worker(run.job_id);
 if run.status<>'RUNNING' or run.strategy_id is distinct from s.id or run.region_policy_id is distinct from new.region_policy_id or run.purpose is distinct from new.purpose
 or not beta_private.scanner_strategy_allowed(s.id,new.purpose) or s.config->>'method' is distinct from 'market-reference-independent-cohorts'
 or new.strategy_hash is distinct from s.config_hash
 or new.code_commit is distinct from s.code_commit or new.code_commit is distinct from current_setting('docked.scanner_commit',true)
 or r.market_id is distinct from m.id or new.event_id is distinct from e.id or r.region_policy_id is distinct from new.region_policy_id or r.selection is distinct from new.selection
 or r.configuration is distinct from s.config->'marketReference' or r.reference->'pricing' is null or r.reference->'pricing'='null'::jsonb
 or new.model_version is distinct from 'market-reference-baseline-v1' or new.model_evidence->>'referenceHash' is distinct from r.reference->>'evidenceHash'
 or new.model_evidence->>'method' is distinct from 'market-reference-baseline' or new.model_evidence->>'advantageClaim' is distinct from 'false'
 or new.model_evidence->>'validationStatus' is distinct from 'UNVALIDATED' or new.model_evidence->>'independentPredictiveModel' is distinct from 'false'
 or new.purpose='live'
 or new.model_evidence->>'codeCommit' is distinct from new.code_commit or (new.model_evidence->>'probability')::numeric is distinct from (r.reference#>>'{pricing,probability}')::numeric
 or new.model_evidence->>'configHash' is distinct from r.config_hash or new.model_evidence->>'modelId' is distinct from 'market-reference-baseline'
 or new.model_evidence->>'purpose' is distinct from 'RESEARCH_BASELINE' or new.model_evidence->>'selection' is distinct from r.selection or new.model_evidence->>'eventId' is distinct from e.id
 or (new.model_evidence->>'fairPrice')::numeric is distinct from (r.reference#>>'{pricing,fairPrice}')::numeric
 or (new.model_evidence->>'asOfTime')::timestamptz is distinct from r.observed_at or (new.model_evidence->>'generatedAt')::timestamptz is distinct from r.observed_at
 or new.model_evidence->'sourceIds' is distinct from r.reference#>'{pricing,sourceIds}' or new.model_evidence->>'sourceEvidenceHash' is distinct from r.reference->>'evidenceHash'
 or new.model_evidence->>'modelHash' is distinct from encode(sha256(convert_to(beta_private.phase5_canonical_json(jsonb_build_object('id','market-reference-baseline','version',new.model_version,'configHash',r.config_hash,'codeCommit',new.code_commit)),'UTF8')),'hex')
 or not coalesce(policy.approved and not policy.preview_community_only and policy.effective_from<=checked and least(policy.effective_to,policy.review_at)>checked and (case when new.purpose='research' then 'market_data' else 'tips' end)=any(policy.features),false)
 or new.scanned_at is distinct from r.observed_at or new.scanned_at>checked or new.expires_at<=checked
 or new.expires_at>least((r.reference->>'sourceAt')::timestamptz+least(180,(s.config->>'maxAgeSeconds')::int)*interval '1 second',e.start_at-greatest(600,(s.config->>'safetySeconds')::int)*interval '1 second',new.scanned_at+interval '120 seconds')
 then raise exception 'Trusted current scanner research linkage required';end if;
 p:=(r.reference#>>'{pricing,probability}')::numeric;
 if new.probability is distinct from p or abs(new.fair_odds-1/p)>0.00000001 or new.required_ev is distinct from (s.config->>'minEV')::numeric
 or new.minimum_odds is distinct from ceil((1+new.required_ev)/p*100)/100 or abs(new.estimated_ev-(p*r.decimal_price-1))>0.00000001
 or r.decimal_price<new.minimum_odds or r.decimal_price<(s.config->>'minOdds')::numeric or r.decimal_price>(s.config->>'maxOdds')::numeric or new.estimated_ev>(s.config->>'maxEV')::numeric
 or not(s.config->'competitions' ? e.competition_id) or not(s.config->'windowsSeconds' @> to_jsonb(new.window_seconds))
 or extract(epoch from(e.start_at-new.scanned_at))>new.window_seconds or extract(epoch from(e.start_at-new.scanned_at))<new.window_seconds-(s.config->>'windowToleranceSeconds')::int
 then raise exception 'Candidate cannot override the shared strategy calculation';end if;
 new.created_at:=clock_timestamp();return new;
end $$;
create trigger scanner_candidate_guard before insert on beta_private.scanner_candidates for each row execute function beta_private.scanner_candidate_guard();
create trigger immutable before update or delete on beta_private.scanner_candidates for each row execute function beta_private.immutable();
create function beta_private.scanner_review_guard() returns trigger language plpgsql set search_path='' as $$
declare c beta_private.scanner_candidates;s beta_private.strategy_versions;r beta_private.market_references;e beta_private.events;policy beta_private.region_policies;last_status text;actor uuid;checked timestamptz;
begin
 select * into c from beta_private.scanner_candidates where id=new.candidate_id for update;
 select status into last_status from beta_private.scanner_reviews where candidate_id=c.id order by created_at desc,id desc limit 1;
 if c.id is null or last_status in ('APPROVED','REJECTED','EXPIRED','INVALIDATED') then raise exception 'Candidate is final';end if;
 if new.status in ('EXPIRED','INVALIDATED') and current_setting('docked.scanner_scheduler',true)='true' then new.actor:=null;
 else actor:=beta_private.scanner_assert_actor(false);if new.actor is distinct from actor then raise exception 'Review actor mismatch';end if;end if;
 if new.status='APPROVED' then
  select * into s from beta_private.strategy_versions where id=c.strategy_id for share;
  select * into r from beta_private.market_references where id=new.market_reference_id for share;
  select * into e from beta_private.events where id=c.event_id for share;
  select * into policy from beta_private.region_policies where id=c.region_policy_id for share;
  perform beta_private.assert_current_market_reference(r.id);
  perform beta_private.scanner_assert_actor(false);checked:=clock_timestamp();
  if c.expires_at<=checked or not beta_private.scanner_strategy_allowed(c.strategy_id,c.purpose) or (c.purpose='live' and c.model_evidence->>'validationStatus' is distinct from 'VALIDATED')
   or s.config_hash is distinct from c.strategy_hash or s.code_commit is distinct from c.code_commit or c.code_commit is distinct from current_setting('docked.scanner_commit',true)
   or r.market_id is distinct from c.market_id or r.selection is distinct from c.selection or r.region_policy_id is distinct from c.region_policy_id
   or r.configuration is distinct from s.config->'marketReference' or r.reference->'pricing' is null or r.reference->'pricing'='null'::jsonb
   or r.decimal_price<ceil((1+(s.config->>'minEV')::numeric)/(r.reference#>>'{pricing,probability}')::numeric*100)/100
   or (r.reference#>>'{pricing,probability}')::numeric*r.decimal_price-1>(s.config->>'maxEV')::numeric
   or r.decimal_price<(s.config->>'minOdds')::numeric or r.decimal_price>(s.config->>'maxOdds')::numeric
   or extract(epoch from(e.start_at-r.observed_at))>c.window_seconds or extract(epoch from(e.start_at-r.observed_at))<c.window_seconds-(s.config->>'windowToleranceSeconds')::int
   or not coalesce(policy.approved and not policy.preview_community_only and policy.effective_from<=checked and least(policy.effective_to,policy.review_at)>checked and (case when c.purpose='research' then 'market_data' else 'tips' end)=any(policy.features),false)
  then raise exception 'Candidate no longer qualifies';end if;
  if c.purpose='research' and new.publication_id is not null then raise exception 'Research review cannot publish';end if;
  if c.purpose<>'research' and not exists(select 1 from beta_private.tip_publications t where t.id=new.publication_id and t.event_id=c.event_id and t.strategy_id=c.strategy_id and t.approved_by=actor and t.evidence::text=case when c.purpose='paper' then 'forward_paper' else 'live_published' end and t.market_reference_id=r.id) then raise exception 'Gated immutable publication required';end if;
  new.evidence:=jsonb_build_object('referenceId',r.id,'referenceHash',r.reference->>'evidenceHash','probability',r.reference#>>'{pricing,probability}','marketPrice',r.decimal_price,'strategyHash',s.config_hash,'purpose',c.purpose);
 elsif new.publication_id is not null then raise exception 'Only approval can link publication';end if;
 new.created_at:=clock_timestamp();insert into beta_private.audit_events(actor,action,subject,details) values(coalesce(new.actor::text,'scanner'),'scanner_candidate_review',c.id::text,jsonb_build_object('status',new.status,'purpose',c.purpose,'reason',new.reason));return new;
end $$;
