create function beta_private.recognition_snapshot_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if current_setting('docked.scanner_scheduler',true) is distinct from 'true' then perform beta_private.scanner_assert_actor(false);end if;
 if new.as_of>clock_timestamp() or new.week_end>new.as_of or date_trunc('week',new.week_start at time zone 'UTC') is distinct from new.week_start at time zone 'UTC'
 or new.payload_hash is distinct from encode(sha256(convert_to(beta_private.phase5_canonical_json(new.payload),'UTF8')),'hex') then raise exception 'Complete-week canonical recognition evidence required';end if;
 return new;
end $$;
