revoke all on function beta_private.scanner_assert_actor(boolean),beta_private.scanner_assert_worker(uuid),beta_private.scanner_schedule_guard(),beta_private.scanner_run_guard(),beta_private.scanner_market_guard(),beta_private.scanner_strategy_allowed(text,text),beta_private.scanner_candidate_guard(),beta_private.scanner_review_guard(),beta_private.recognition_snapshot_guard() from public,anon,authenticated;

create table beta_private.market_data_config(
 id uuid primary key default gen_random_uuid(),provider text not null check(provider in ('the-odds-api','odds-papi')),
 version text not null,config_hash text not null check(config_hash ~ '^[a-f0-9]{64}$'),configuration jsonb not null,
 enabled boolean not null default false,effective_from timestamptz not null,effective_to timestamptz not null,
 rights_reference text not null check(length(btrim(rights_reference))>=5),reviewed_by uuid not null,created_at timestamptz not null default clock_timestamp(),
 unique(provider,version),check(effective_to>effective_from)
);
create unique index market_data_one_enabled_provider on beta_private.market_data_config(provider) where enabled;
create table beta_private.market_data_payloads(
 id text primary key check(id ~ '^[a-f0-9]{64}$'),provider text not null,payload jsonb not null,
 received_at timestamptz not null,rights_reference text not null,retain_until timestamptz not null
);
create table beta_private.market_data_event_mappings(
 provider text not null,provider_event_id text not null,event_id text not null references beta_private.events(id),
 provider_competition_id text not null,canonical_competition_id text not null references beta_private.competitions(id),mapping_evidence text not null,
 created_at timestamptz not null default clock_timestamp(),primary key(provider,provider_event_id),unique(provider,event_id)
);
create table beta_private.market_data_fixture_observations(
 id text primary key check(id ~ '^[a-f0-9]{64}$'),provider text not null,event_id text not null references beta_private.events(id),provider_event_id text not null,
 observed_at timestamptz not null,payload jsonb not null,raw_payload_id text not null,
 foreign key(provider,provider_event_id) references beta_private.market_data_event_mappings(provider,provider_event_id)
);
create index market_data_fixture_latest on beta_private.market_data_fixture_observations(event_id,observed_at desc,id desc);
create function beta_private.market_data_config_guard() returns trigger language plpgsql set search_path='' as $$
declare actor uuid;
begin
 actor:=beta_private.scanner_assert_actor(true);
 if tg_op='DELETE' then raise exception 'Provider configuration history is retained';end if;
 if tg_op='UPDATE' and (not old.enabled or new.enabled or (to_jsonb(new)-'enabled') is distinct from (to_jsonb(old)-'enabled')) then raise exception 'Material provider changes require a new reviewed version';end if;
 if tg_op='INSERT' and (new.reviewed_by is distinct from actor or new.configuration->>'provider' is distinct from new.provider or new.configuration->>'version' is distinct from new.version
 or new.config_hash is distinct from encode(sha256(convert_to(beta_private.phase5_canonical_json(new.configuration),'UTF8')),'hex')
 or new.configuration#>>'{rights,reference}' is distinct from new.rights_reference
 or not coalesce(new.configuration#>>'{rights,display}'='true' and new.configuration#>>'{rights,storage}'='true' and new.configuration#>>'{rights,derived}'='true'
 and (new.configuration#>>'{rights,rawRetentionDays}')::int between 1 and 30 and (new.configuration->>'monthlyCreditLimit')::int between 1 and 1000000
 and (new.configuration->>'pollIntervalSeconds')::int between 60 and 86400 and (new.configuration->>'horizonHours')::int between 1 and 168
 and (new.configuration->>'maxEvents')::int between 1 and 100 and (new.configuration->>'maxRequestsPerRun')::int between 1 and 20,false)
 or jsonb_typeof(new.configuration->'competitions') is distinct from 'array' or jsonb_array_length(new.configuration->'competitions')<1
 or jsonb_typeof(new.configuration->'bookmakers') is distinct from 'object') then raise exception 'Reviewed bounded provider rights/configuration required';end if;
 insert into beta_private.audit_events(actor,action,subject,details) values(actor::text,'market_data_configuration',new.id::text,jsonb_build_object('provider',new.provider,'version',new.version,'enabled',new.enabled,'configHash',new.config_hash));return new;
end $$;
create trigger market_data_config_guard before insert or update or delete on beta_private.market_data_config for each row execute function beta_private.market_data_config_guard();
create function beta_private.market_data_payload_guard() returns trigger language plpgsql set search_path='' as $$
declare c beta_private.market_data_config;checked timestamptz;
begin
 if tg_op='DELETE' then
  if current_setting('docked.market_data_retention',true)='purge_expired' and old.retain_until<=clock_timestamp() then return old;end if;
  raise exception 'Only expired licensed raw payload purge is supported';
 end if;
 if tg_op='UPDATE' then raise exception 'Provider payloads are immutable';end if;
 select * into c from beta_private.market_data_config where provider=new.provider and enabled for share;checked:=clock_timestamp();
 if c.id is null or c.effective_from>checked or c.effective_to<=checked or new.rights_reference is distinct from c.rights_reference
 or new.received_at>checked or new.received_at<checked-interval '5 minutes' or new.retain_until<=new.received_at
 or new.retain_until>least(new.received_at+(c.configuration#>>'{rights,rawRetentionDays}')::int*interval '1 day',c.effective_to)
 or new.id is distinct from encode(sha256(convert_to(beta_private.phase5_canonical_json(jsonb_build_object('provider',new.provider,'payload',new.payload,'receivedAt',to_char(new.received_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))),'UTF8')),'hex') then raise exception 'Licensed bounded raw retention required';end if;
 return new;
end $$;
create trigger market_data_payload_guard before insert or update or delete on beta_private.market_data_payloads for each row execute function beta_private.market_data_payload_guard();
create function beta_private.purge_expired_market_payloads() returns integer language plpgsql set search_path='' as $$
declare total integer;
begin
 perform set_config('docked.market_data_retention','purge_expired',true);
 delete from beta_private.market_data_payloads where id in(select id from beta_private.market_data_payloads where retain_until<=clock_timestamp() order by retain_until limit 500 for update skip locked);
 get diagnostics total=row_count;perform set_config('docked.market_data_retention','',true);return total;
end $$;
create function beta_private.market_data_mapping_guard() returns trigger language plpgsql set search_path='' as $$
declare c beta_private.market_data_config;e beta_private.events;match jsonb;
begin
 select * into c from beta_private.market_data_config where provider=new.provider and enabled and effective_from<=clock_timestamp() and effective_to>clock_timestamp() for share;
 select * into e from beta_private.events where id=new.event_id for share;
 select value into match from jsonb_array_elements(c.configuration->'competitions') where value->>'providerCompetitionId'=new.provider_competition_id;
 if c.id is null or e.id is null or match is null or new.canonical_competition_id is distinct from e.competition_id
 or match->>'competitionId' is distinct from new.canonical_competition_id or match->>'mappingEvidence' is distinct from new.mapping_evidence
 or e.source_mappings->>new.provider is distinct from new.provider_event_id or c.effective_to<=clock_timestamp() then raise exception 'Reviewed exact provider event mapping required';end if;return new;
end $$;
create trigger market_data_mapping_guard before insert on beta_private.market_data_event_mappings for each row execute function beta_private.market_data_mapping_guard();
create trigger immutable before update or delete on beta_private.market_data_event_mappings for each row execute function beta_private.immutable();
create function beta_private.market_data_fixture_guard() returns trigger language plpgsql set search_path='' as $$
declare r beta_private.market_data_payloads;m beta_private.market_data_event_mappings;
begin
 select * into r from beta_private.market_data_payloads where id=new.raw_payload_id for share;
 select * into m from beta_private.market_data_event_mappings where provider=new.provider and provider_event_id=new.provider_event_id for share;
 if r.id is null or m.event_id is distinct from new.event_id or r.provider is distinct from new.provider or new.observed_at is distinct from r.received_at or r.retain_until<=clock_timestamp()
 or new.payload->>'providerEventId' is distinct from new.provider_event_id or new.payload->>'provider' is distinct from new.provider
 or new.id is distinct from encode(sha256(convert_to(beta_private.phase5_canonical_json(jsonb_build_object('provider',new.provider,'eventId',new.event_id,'fixture',new.payload)),'UTF8')),'hex')
 then raise exception 'Canonical fixture requires retained licensed observation';end if;return new;
end $$;
create trigger market_data_fixture_guard before insert on beta_private.market_data_fixture_observations for each row execute function beta_private.market_data_fixture_guard();
create trigger immutable before update or delete on beta_private.market_data_fixture_observations for each row execute function beta_private.immutable();
create function beta_private.market_data_snapshot_guard() returns trigger language plpgsql set search_path='' as $$
declare c beta_private.market_data_config;r beta_private.market_data_payloads;m beta_private.markets;e beta_private.events;b jsonb;checked timestamptz;
begin
 if new.evidence::text is distinct from 'market_data' then return new;end if;
 select * into c from beta_private.market_data_config where provider=new.provider and enabled for share;
 select * into r from beta_private.market_data_payloads where id=substring(new.raw_private_path from 4) and new.raw_private_path like 'db:%' for share;
 select * into m from beta_private.markets where id=new.market_id for share;select * into e from beta_private.events where id=m.event_id for share;
 checked:=clock_timestamp();b:=c.configuration->'bookmakers'->new.bookmaker;
 if c.id is null or r.id is null or m.id is null or e.id is null or c.effective_from>checked or c.effective_to<=checked or r.retain_until<=checked
 or r.provider is distinct from new.provider or new.provenance is distinct from c.rights_reference or r.rights_reference is distinct from c.rights_reference
 or new.received_at is distinct from r.received_at or new.payload->'rules' is distinct from m.rules
 or e.status is distinct from 'scheduled' or new.payload->>'id' is distinct from new.id or new.payload->>'rawPayloadId' is distinct from r.id
 or (new.payload->>'sourceAt')::timestamptz is distinct from new.source_at or (new.payload->>'snapshotAt')::timestamptz is distinct from new.snapshot_at or (new.payload->>'receivedAt')::timestamptz is distinct from new.received_at
 or new.payload->>'bookmaker' is distinct from new.bookmaker or new.payload->>'operator' is distinct from b->>'operator'
 or b is null or not coalesce((b->>'knownAt')::timestamptz<=new.received_at and (b->>'effectiveFrom')::timestamptz<=new.received_at and (b->>'effectiveTo')::timestamptz>checked,false)
 or not exists(select 1 from beta_private.market_data_event_mappings where provider=new.provider and event_id=e.id)
 then raise exception 'Current market observation requires reviewed retained provider provenance';end if;
 if new.payload ? 'communityMetadata' and (new.payload#>>'{communityMetadata,sourceKind}' is distinct from 'current_provider'
 or new.payload#>>'{communityMetadata,sourceType}' is distinct from b->>'sourceType'
 or new.payload#>>'{communityMetadata,priceClass}' is distinct from b->>'classification'
 or new.payload#>>'{communityMetadata,classificationVersion}' is distinct from b->>'classificationVersion'
 or new.payload#>>'{communityMetadata,classificationEvidence}' is distinct from b->>'classificationEvidence'
 or new.payload#>>'{communityMetadata,providerEventId}' is distinct from e.source_mappings->>new.provider
 or (new.payload#>>'{communityMetadata,observedStartAt}')::timestamptz is distinct from e.start_at
 or new.payload#>>'{communityMetadata,receivedByDocked}' is distinct from 'true'
 or new.payload#>'{communityMetadata,promotionFlags}' is distinct from case when b->>'classification'='STANDARD_VERIFIED' then '[]'::jsonb else jsonb_build_array(b->>'classification') end) then raise exception 'Provider classification cannot be upgraded';end if;
 return new;
end $$;
create trigger market_data_snapshot_guard before insert on beta_private.odds_snapshots for each row execute function beta_private.market_data_snapshot_guard();
do $$ declare t text;begin foreach t in array array['market_data_config','market_data_payloads','market_data_event_mappings','market_data_fixture_observations'] loop execute format('alter table beta_private.%I enable row level security',t);execute format('revoke all on beta_private.%I from public,anon,authenticated',t);end loop;end $$;
revoke all on function beta_private.market_data_config_guard(),beta_private.market_data_payload_guard(),beta_private.purge_expired_market_payloads(),beta_private.market_data_mapping_guard(),beta_private.market_data_fixture_guard(),beta_private.market_data_snapshot_guard() from public,anon,authenticated;

-- Reuse the reviewed evidence guards. Only their current-observation discriminator changes;
-- publication lifecycle, source re-derivation, clock, rights and immutable ledger checks remain identical.
create function beta_private.market_data_source_current(p_snapshot text,p_at timestamptz) returns boolean language sql stable set search_path='' as $$
 select coalesce((select q.evidence::text<>'market_data' or exists(
 select 1 from beta_private.market_data_config c join beta_private.market_data_payloads raw on raw.id=substring(q.raw_private_path from 4)
 join beta_private.markets m on m.id=q.market_id join beta_private.events e on e.id=m.event_id
 join beta_private.market_data_event_mappings map on map.provider=q.provider and map.event_id=e.id
 where c.provider=q.provider and c.enabled and c.effective_from<=p_at and c.effective_to>p_at and c.created_at<=q.received_at
 and q.received_at>=c.effective_from and c.rights_reference=q.provenance and raw.rights_reference=c.rights_reference and raw.retain_until>p_at and raw.provider=q.provider
 and exists(select 1 from jsonb_array_elements(c.configuration->'competitions') cfg where cfg->>'competitionId'=e.competition_id and cfg->>'providerCompetitionId'=map.provider_competition_id and cfg->>'mappingEvidence'=map.mapping_evidence)
 and c.configuration#>>array['bookmakers',q.bookmaker,'operator']=q.payload->>'operator'
 and c.configuration#>>array['bookmakers',q.bookmaker,'sourceType']=q.payload#>>'{communityMetadata,sourceType}'
 and c.configuration#>>array['bookmakers',q.bookmaker,'classification']=q.payload#>>'{communityMetadata,priceClass}'
 and c.configuration#>>array['bookmakers',q.bookmaker,'classificationVersion']=q.payload#>>'{communityMetadata,classificationVersion}'
 and c.configuration#>>array['bookmakers',q.bookmaker,'classificationEvidence']=q.payload#>>'{communityMetadata,classificationEvidence}'
 and (c.configuration#>>array['bookmakers',q.bookmaker,'knownAt'])::timestamptz<=q.received_at
 and (c.configuration#>>array['bookmakers',q.bookmaker,'effectiveFrom'])::timestamptz<=q.received_at
 and (c.configuration#>>array['bookmakers',q.bookmaker,'effectiveTo'])::timestamptz>p_at
 ) from beta_private.odds_snapshots q where q.id=p_snapshot),false)
$$;
create function beta_private.market_data_lock_sources(p_market text) returns void language plpgsql set search_path='' as $$
begin
 perform 1 from beta_private.market_data_config where provider in(select provider from beta_private.odds_snapshots where market_id=p_market and evidence::text='market_data') order by provider,id for share;
end $$;
revoke all on function beta_private.market_data_source_current(text,timestamptz),beta_private.market_data_lock_sources(text) from public,anon,authenticated;
do $$ declare signature text; definition text; changed text;
begin
 foreach signature in array array['beta_private.reference_cohort_sources(text,jsonb,uuid,timestamptz,text)','beta_private.market_reference_guard()','beta_private.community_quote_evidence_guard()'] loop
  definition:=pg_get_functiondef(signature::regprocedure);
  changed:=replace(replace(replace(definition,'q.evidence not in (''forward_paper'',''live_published'')','q.evidence::text not in (''market_data'',''forward_paper'',''live_published'')'),
   'q.evidence in (''forward_paper'',''live_published'')','q.evidence::text in (''market_data'',''forward_paper'',''live_published'')'),
   'evidence in (''forward_paper'',''live_published'')','evidence::text in (''market_data'',''forward_paper'',''live_published'')');
  if definition=changed then raise exception 'Current evidence guard upgrade mismatch';end if;
  if signature='beta_private.reference_cohort_sources(text,jsonb,uuid,timestamptz,text)' then
   changed:=replace(changed,'where p_config->p_cohort ? q.bookmaker','where beta_private.market_data_source_current(q.id,p_at) and p_config->p_cohort ? q.bookmaker');
  elsif signature='beta_private.market_reference_guard()' then
   changed:=replace(changed,' select * into m from beta_private.markets where id=new.market_id for update;',' perform beta_private.market_data_lock_sources(new.market_id); select * into m from beta_private.markets where id=new.market_id for update;');
   changed:=replace(changed,'if q.id is null or q.market_id','if not beta_private.market_data_source_current(q.id,checked) or q.id is null or q.market_id');
  end if;
  execute changed;
 end loop;
 definition:=pg_get_functiondef('beta_private.assert_current_market_reference(uuid)'::regprocedure);
 changed:=replace(definition,' perform 1 from beta_private.markets where id=r.market_id for update;',' perform beta_private.market_data_lock_sources(r.market_id); perform 1 from beta_private.markets where id=r.market_id for update;');
 if definition=changed then raise exception 'Reference authority lock upgrade mismatch';end if;execute changed;
end $$;


-- SOURCE 20261003214310_production_community_runtime_role.sql sha256=ab9e423ec1c5ef0142edc04f26e2e779544d73ab7ce9ef5aaa42f5365b35191d
-- Community-only server connection. Provisioning a password/login is a separate
-- exact-project operator action; this migration activates no account or feature.
-- This trusted backend role is NOT a browser JWT role. Application identity,
-- role/MFA and transactional authorization remain mandatory.
do $$ declare column_name text; managed boolean; begin
 select r.rolname='supabase_auth_admin' into managed from pg_class c join pg_roles r on r.oid=c.relowner where c.oid='auth.users'::regclass;
 if managed then
  foreach column_name in array array['id','email','email_confirmed_at','is_anonymous','raw_app_meta_data','banned_until'] loop
   if not exists(select 1 from pg_attribute where attrelid='auth.users'::regclass and attname=column_name and not attisdropped)
   then raise exception 'Managed Auth user schema differs from reviewed production contract'; end if;
  end loop;
  foreach column_name in array array['id','user_id','not_after'] loop
   if not exists(select 1 from pg_attribute where attrelid='auth.sessions'::regclass and attname=column_name and not attisdropped)
   then raise exception 'Managed Auth session schema differs from reviewed production contract'; end if;
  end loop;
  if not has_schema_privilege(current_user,'auth','USAGE')
   or not has_table_privilege(current_user,'auth.users','SELECT')
   or not has_table_privilege(current_user,'auth.sessions','SELECT')
   or not has_table_privilege(current_user,'auth.sessions','DELETE')
   or not exists(select 1 from pg_roles where rolname=current_user and (rolbypassrls or rolsuper))
  then raise exception 'Managed Auth projection-owner privileges require independent review'; end if;
 end if;
end $$;
do $$ begin
 if exists(select 1 from pg_roles where rolname='docked_beta_app') then
  raise exception 'Existing docked_beta_app role requires independent review';
 end if;
 create role docked_beta_app nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls;
end $$;
alter role docked_beta_app set search_path='';
grant usage on schema beta_public,beta_private to docked_beta_app;
do $$ begin execute format('grant connect on database %I to docked_beta_app',current_database()); end $$;

-- Exact, current read-model inventory; no ALL TABLES or default privileges.
-- Raw provider payloads, detailed quote evidence and preview fixture/invitation records
-- are deliberately absent. Derived ledgers remain read-only.
