 foreach relation in array array[
  'beta_public.profiles','beta_public.notification_preferences','beta_public.saved_tips','beta_public.personal_entries',
  'beta_private.roles','beta_private.consent_events','beta_private.region_policies','beta_private.bookmaker_eligibility',
