  'beta_private.correction_events','beta_private.closing_snapshots','beta_private.availability_observations',
  'beta_private.articles','beta_private.article_revisions','beta_private.schedules','beta_private.outbox','beta_private.delivery_attempts',
  'beta_private.job_runs','beta_private.feature_flags','beta_private.audit_events','beta_private.launch_record','beta_private.unsubscribe_tokens',
  'beta_private.rate_limits','beta_private.analytics_events','beta_private.provider_poll_runs',
  'beta_private.membership_plans','beta_private.plan_prices','beta_private.plan_entitlements','beta_private.member_subscriptions',
  'beta_private.subscription_events','beta_private.commercial_approvals','beta_private.community_competitions',
  'beta_private.competition_rules','beta_private.competition_prizes','beta_private.competition_qualifications',
  'beta_private.competition_rankings','beta_private.prize_award_events','beta_private.community_deals','beta_private.sponsor_campaigns',
  'beta_private.social_profiles','beta_private.social_handle_history','beta_private.social_follows','beta_private.social_blocks',
  'beta_private.social_mutes','beta_private.social_posts','beta_private.social_media','beta_private.social_post_media',
  'beta_private.social_comments','beta_private.social_reactions','beta_private.social_saved','beta_private.social_reports',
  'beta_private.social_moderation_events','beta_private.social_notification_preferences','beta_private.social_notifications',
  'beta_private.social_notification_jobs','beta_private.community_verification_rules','beta_private.community_edges',
  'beta_private.community_edge_status','beta_private.community_result_sources','beta_private.community_settlements',
  'beta_private.community_corrections','beta_private.leaderboard_rule_versions','beta_private.leaderboard_snapshots',
  'beta_private.leaderboard_notification_jobs','beta_private.market_references','beta_private.market_reference_methodologies',
  'beta_private.market_reference_movements','beta_private.community_edge_personal_notes','beta_private.preview_tester_access',
  'beta_private.app_onboarding','beta_private.scanner_schedules','beta_private.scanner_runs','beta_private.scanner_candidates',
  'beta_private.scanner_run_markets','beta_private.scanner_reviews','beta_private.operational_alerts',
  'beta_private.community_recognition_snapshots','beta_private.market_data_config','beta_private.market_data_event_mappings'
 ] loop
  execute format('grant select on %s to docked_beta_app',relation);
  execute format('create policy docked_app_select on %s for select to docked_beta_app using(true)',relation);
 end loop;
end $$;
-- Recognition checks provenance IDs without needing prices or provider payloads.
grant select(id,evidence) on beta_private.odds_snapshots to docked_beta_app;
create policy docked_app_select on beta_private.odds_snapshots for select to docked_beta_app using(true);
-- Admin operational classification counts do not require source payload access.
grant select(classification,created_at) on beta_private.community_quote_evidence to docked_beta_app;
create policy docked_app_select on beta_private.community_quote_evidence for select to docked_beta_app using(true);

-- Supabase Auth tables are owned by supabase_auth_admin. The migration role has
-- SELECT/DELETE but cannot change their policies or delegate DELETE. Private
-- security-barrier views use the existing migration-owner permissions; no Auth
-- table DDL/grants are issued. Only these fixed projection columns are exposed.
-- Minimal embedded Auth schemas omit optional columns. Hosted preflight must
-- confirm all six columns exist; fallback expressions are only test compatibility.
do $$ declare column_name text; expressions text[]:=array[]::text[]; fallback text; begin
 foreach column_name in array array['id','email','email_confirmed_at','is_anonymous','raw_app_meta_data','banned_until'] loop
  if exists(select 1 from pg_attribute where attrelid='auth.users'::regclass and attname=column_name and not attisdropped) then
   expressions:=array_append(expressions,format('u.%I',column_name));
  else
   fallback:=case column_name when 'id' then 'null::uuid' when 'email' then 'null::text' when 'is_anonymous' then 'false' when 'raw_app_meta_data' then '''{}''::jsonb' else 'null::timestamptz' end;
   expressions:=array_append(expressions,format('%s as %I',fallback,column_name));
  end if;
 end loop;
 execute 'create view beta_private.runtime_auth_users with (security_barrier=true) as select '||array_to_string(expressions,',')||' from auth.users u';
end $$;
create view beta_private.runtime_auth_sessions with (security_barrier=true) as select id,user_id,not_after from auth.sessions;
revoke all on beta_private.runtime_auth_users,beta_private.runtime_auth_sessions from public,anon,authenticated;
grant select on beta_private.runtime_auth_users,beta_private.runtime_auth_sessions to docked_beta_app;
grant delete on beta_private.runtime_auth_sessions to docked_beta_app;
-- Do not delegate managed Auth schema permissions. These invoker claim readers
-- read only the same transaction-local verified claims used by existing helpers.
create function beta_private.runtime_uid() returns uuid language sql stable set search_path='' as $$
 select coalesce(nullif(current_setting('request.jwt.claim.sub',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid
$$;
revoke all on function beta_private.runtime_uid() from public,anon,authenticated;
grant execute on function beta_private.runtime_uid() to docked_beta_app;
-- Only the two existing invoker helpers called by community web reads/writes
-- require direct auth.uid access. Preserve their complete current definitions,
-- replacing that fixed claim-reader reference alone. No authority check is removed.
do $$ declare signature regprocedure; definition text; begin
 foreach signature in array array['beta_private.community_assert_access(uuid,text)'::regprocedure,'beta_private.social_post_visible(uuid,uuid)'::regprocedure] loop
  definition:=pg_get_functiondef(signature);
  if position('auth.uid()' in definition)=0 then raise exception 'Expected community claim reader changed; review migration'; end if;
  definition:=replace(definition,'auth.uid()','beta_private.runtime_uid()');
  if signature='beta_private.community_assert_access(uuid,text)'::regprocedure then
   if position('and length(trim(policy.evidence))>0 and p_feature=any(policy.features) then return; end if;' in definition)=0
   then raise exception 'Expected ordinary-region authorization branch changed; review migration'; end if;
   -- The session may expire while either FOR SHARE lock waits. Recheck using
   -- wall-clock time after those locks, for ordinary approval as well as Preview.
   definition:=replace(definition,'and length(trim(policy.evidence))>0 and p_feature=any(policy.features) then return; end if;',
     'and length(trim(policy.evidence))>0 and p_feature=any(policy.features) and beta_private.active_member_session() then return; end if;');
  end if;
  execute definition;
 end loop;
end $$;

-- Preserve existing invoker erasure semantics. Session revocation goes through
-- the restricted updatable view, not a grant on the managed Auth table.
create or replace function beta_private.disable_account(p_user uuid) returns void language plpgsql set search_path='' as $$
begin
 update beta_public.profiles set disabled_at=coalesce(disabled_at,clock_timestamp()) where id=p_user;
 if not found then return; end if;
 update beta_public.notification_preferences set paused=true,digest='off',edge_alerts=false,education=false,updated_at=now() where user_id=p_user;
 update beta_private.outbox set state='suppressed',user_id=null,payload='{}',dedupe_key='erased:'||id::text,last_error='Account erased',lease_token=null,lease_until=null where user_id=p_user;
 update beta_private.delivery_attempts set user_id=null,provider_id=null where user_id=p_user;
 delete from beta_private.analytics_events where user_id=p_user;
 delete from beta_private.unsubscribe_tokens where user_id=p_user;
 delete from beta_public.saved_tips where user_id=p_user;
 delete from beta_public.personal_entries where user_id=p_user;
 delete from beta_private.runtime_auth_sessions where user_id=p_user;
 insert into beta_private.job_runs(dedupe_key,kind,payload) values('account-deletion:'||p_user::text,'account_deletion',jsonb_build_object('userId',p_user)) on conflict do nothing;
 insert into beta_private.audit_events(actor,action,subject) values('account-service','account_access_revoked',p_user::text);
end $$;

-- Reversible member/community state. Immutable trigger-protected identities and
-- posts receive no DELETE privilege. Browsers receive no additional grants.
do $$ declare relation text; begin
 foreach relation in array array[
  'beta_public.profiles','beta_private.social_follows','beta_private.social_notification_preferences','beta_private.social_notification_jobs'
 ] loop
  execute format('grant insert,update,delete on %s to docked_beta_app',relation);
  execute format('create policy docked_app_insert on %s for insert to docked_beta_app with check(true)',relation);
  execute format('create policy docked_app_update on %s for update to docked_beta_app using(true) with check(true)',relation);
  execute format('create policy docked_app_delete on %s for delete to docked_beta_app using(true)',relation);
 end loop;
 foreach relation in array array['beta_public.notification_preferences','beta_private.social_profiles','beta_private.social_media','beta_private.social_comments','beta_private.social_reports','beta_private.app_onboarding','beta_private.rate_limits'] loop
  execute format('grant insert,update on %s to docked_beta_app',relation);
  execute format('create policy docked_app_insert on %s for insert to docked_beta_app with check(true)',relation);
  execute format('create policy docked_app_update on %s for update to docked_beta_app using(true) with check(true)',relation);
 end loop;
 foreach relation in array array['beta_public.saved_tips','beta_public.personal_entries','beta_private.social_handle_history','beta_private.social_blocks','beta_private.social_mutes','beta_private.social_post_media','beta_private.social_reactions','beta_private.social_saved'] loop
  execute format('grant insert,delete on %s to docked_beta_app',relation);
  execute format('create policy docked_app_insert on %s for insert to docked_beta_app with check(true)',relation);
  execute format('create policy docked_app_delete on %s for delete to docked_beta_app using(true)',relation);
 end loop;
 foreach relation in array array['beta_private.audit_events','beta_private.consent_events','beta_private.social_moderation_events','beta_private.analytics_events'] loop
  execute format('grant insert on %s to docked_beta_app',relation);
  execute format('create policy docked_app_insert on %s for insert to docked_beta_app with check(true)',relation);
 end loop;
end $$;
grant delete on beta_private.analytics_events,beta_private.unsubscribe_tokens,beta_private.community_edge_personal_notes to docked_beta_app;
create policy docked_app_delete on beta_private.analytics_events for delete to docked_beta_app using(true);
create policy docked_app_delete on beta_private.unsubscribe_tokens for delete to docked_beta_app using(true);
create policy docked_app_delete on beta_private.community_edge_personal_notes for delete to docked_beta_app using(true);

grant insert,update on beta_private.social_posts to docked_beta_app;
create policy docked_app_insert on beta_private.social_posts for insert to docked_beta_app with check(
 kind in('discussion','analysis','question','celebration') and official_tip_id is null and community_edge_id is null
 and author_id<>'00000000-0000-4000-8000-000000000001'::uuid);
create policy docked_app_update on beta_private.social_posts for update to docked_beta_app using(
 kind in('discussion','analysis','question','celebration') and official_tip_id is null and community_edge_id is null)
 with check(kind in('discussion','analysis','question','celebration') and official_tip_id is null and community_edge_id is null);
grant insert,update,delete on beta_private.social_notifications to docked_beta_app;
create policy docked_app_insert on beta_private.social_notifications for insert to docked_beta_app with check(type in('followed_post','comment','reply','reaction','follower','account','system'));
create policy docked_app_update on beta_private.social_notifications for update to docked_beta_app using(true) with check(true);
create policy docked_app_delete on beta_private.social_notifications for delete to docked_beta_app using(true);

-- Account-service queues only; no provider/scanner/publication jobs or deliveries.
grant insert,update on beta_private.job_runs to docked_beta_app;
create policy docked_app_insert on beta_private.job_runs for insert to docked_beta_app with check(kind='account_deletion');
create policy docked_app_update on beta_private.job_runs for update to docked_beta_app using(kind='account_deletion') with check(kind='account_deletion');
grant insert,update on beta_private.outbox to docked_beta_app;
create policy docked_app_insert on beta_private.outbox for insert to docked_beta_app with check(kind in('service','education') and state='queued');
create policy docked_app_update on beta_private.outbox for update to docked_beta_app using(true) with check(state in('suppressed','dead'));
grant update(user_id,provider_id) on beta_private.delivery_attempts to docked_beta_app;
create policy docked_app_update on beta_private.delivery_attempts for update to docked_beta_app using(true) with check(user_id is null and provider_id is null);

grant execute on function beta_private.active_member_session(),beta_private.disable_account(uuid),
 beta_private.community_assert_access(uuid,text),beta_private.community_actor(uuid,text,boolean),
 beta_private.community_feature_allowed(uuid,text),beta_private.community_post_allowed(uuid,uuid),
 beta_private.social_profile_visible(uuid,uuid,boolean),beta_private.social_post_visible(uuid,uuid),
 beta_private.preview_tester_policy(uuid,text),beta_private.publication_region_matches(uuid,uuid) to docked_beta_app;

-- PostgreSQL row-locking SELECT requires UPDATE privilege. These identity-only
-- grants allow existing FOR SHARE authorization locks; WITH CHECK(false) denies
-- every actual UPDATE, including id=id. They cannot approve or edit a policy.
grant update(id) on beta_private.region_policies,beta_private.preview_tester_access to docked_beta_app;
create policy docked_app_lock on beta_private.region_policies for update to docked_beta_app using(true) with check(false);
create policy docked_app_lock on beta_private.preview_tester_access for update to docked_beta_app using(true) with check(false);

-- Future schemas/tables/functions stay inaccessible unless a reviewed migration
-- enumerates them. Fail rather than silently inheriting permanent DDL authority.
do $$ begin
 if has_schema_privilege('docked_beta_app','beta_public','CREATE') or has_schema_privilege('docked_beta_app','beta_private','CREATE')
 or has_schema_privilege('docked_beta_app','auth','CREATE') or exists(select 1 from pg_auth_members where member=(select oid from pg_roles where rolname='docked_beta_app'))
 then raise exception 'docked_beta_app inherited unexpected creation or role authority'; end if;
end $$;


-- SOURCE 20261003225203_phase5a_manual_provider_trial.sql sha256=6996602ed8a7d550667a651becbb682b0a02a295e5afca059a8622696731a452
-- Isolated manual trial only. No provider configuration, rights, policy or permit is activated.
create table beta_private.provider_trials (
 id uuid primary key default gen_random_uuid(), provider text not null unique check(provider='the-odds-api'),
 project_ref text not null check(project_ref='bckkllmndoxzpzdqrevb'),
 rights_reference text not null check(length(btrim(rights_reference))>=8),
 decision text not null check(decision in ('APPROVED_FOR_PREVIEW_TRIAL','REQUIRES_CLARIFICATION','NOT_PERMITTED')),
 reviewed_at timestamptz not null, next_review_at timestamptz not null, effective_to timestamptz not null,
 reviewed_by uuid not null, evidence_links jsonb not null check(jsonb_typeof(evidence_links)='array' and jsonb_array_length(evidence_links)>0),
 scopes jsonb not null, credit_cap integer not null check(credit_cap between 1 and 250), attempt_cap integer not null default 25 check(attempt_cap between 1 and 25),
 revoked_at timestamptz, revoke_reason text, created_at timestamptz not null default clock_timestamp(),
 check(reviewed_at<next_review_at and next_review_at<=effective_to)
);
create table beta_private.provider_trial_permits (
 id uuid primary key default gen_random_uuid(), trial_id uuid not null references beta_private.provider_trials(id),
 token_hash text not null check(token_hash ~ '^[a-f0-9]{64}$'), operation text not null check(operation in ('sports','events','odds','scores')),
 competition text, config_id uuid references beta_private.market_data_config(id),
 expires_at timestamptz not null, created_by uuid not null, created_at timestamptz not null default clock_timestamp(),
 check((operation='sports' and competition is null and config_id is null) or(operation in ('events','odds','scores') and competition ~ '^[a-z0-9_]{1,100}$' and config_id is not null))
);
create table beta_private.provider_trial_requests (
 id uuid primary key default gen_random_uuid(), permit_id uuid not null unique references beta_private.provider_trial_permits(id),
 trial_id uuid not null references beta_private.provider_trials(id), poll_run_id uuid not null unique references beta_private.provider_poll_runs(id),
 scope text not null, reserved_credits integer not null check(reserved_credits between 0 and 250),
 reported_credits integer check(reported_credits>=0), remaining integer check(remaining>=0), used integer check(used>=0),
 status text not null default 'RESERVED' check(status in ('RESERVED','SUCCESS','FAILED')),
 started_at timestamptz not null default clock_timestamp(), headers_at timestamptz, completed_at timestamptz, error_code text,
 diagnostics jsonb not null default '{}'
);
create table beta_private.provider_trial_diagnostics (
 id uuid primary key default gen_random_uuid(), trial_id uuid not null references beta_private.provider_trials(id),
 observed_at timestamptz not null default clock_timestamp(), payload jsonb not null
);
create function beta_private.provider_trial_active(p_rights text) returns boolean language sql volatile set search_path='' as $$
 select exists(select 1 from beta_private.provider_trials t where provider='the-odds-api' and project_ref='bckkllmndoxzpzdqrevb' and rights_reference=p_rights and decision='APPROVED_FOR_PREVIEW_TRIAL' and revoked_at is null and reviewed_at<=clock_timestamp() and next_review_at>clock_timestamp() and effective_to>clock_timestamp()
 and not exists(select 1 from beta_private.provider_trial_requests r where r.trial_id=t.id and (r.status='FAILED' or r.reported_credits>r.reserved_credits)))
$$;
create function beta_private.provider_trial_review_guard() returns trigger language plpgsql set search_path='' as $$
declare actor uuid;
begin
 actor:=beta_private.scanner_assert_actor(true);
 if tg_op='DELETE' then raise exception 'Trial history cannot be removed';end if;
 if tg_op='UPDATE' then
  if old.revoked_at is not null or new.revoked_at is null or new.revoked_at>clock_timestamp() or length(btrim(new.revoke_reason))<3
   or (to_jsonb(new)-array['revoked_at','revoke_reason']) is distinct from (to_jsonb(old)-array['revoked_at','revoke_reason']) then raise exception 'Trial terms and cumulative budget are immutable';end if;
 else
  if new.reviewed_by is distinct from actor or new.reviewed_at>clock_timestamp() or new.reviewed_at<clock_timestamp()-interval '1 day'
   or new.effective_to>new.reviewed_at+interval '32 days' or not coalesce(new.scopes @> '{"display":true,"storage":true,"derived":true,"auditRetention":true}'::jsonb,false)
   or exists(select 1 from jsonb_array_elements_text(new.evidence_links)e(link) where link !~ '^https://the-odds-api[.]com/') then raise exception 'Reviewed explicit trial rights required';end if;
 end if;
 insert into beta_private.audit_events(actor,action,subject,details) values(actor::text,'provider_trial_review',new.id::text,jsonb_build_object('decision',new.decision,'revoked',new.revoked_at is not null,'creditCap',new.credit_cap));return new;
end $$;
create trigger provider_trial_review before insert or update or delete on beta_private.provider_trials for each row execute function beta_private.provider_trial_review_guard();
create function beta_private.provider_trial_permit_guard() returns trigger language plpgsql set search_path='' as $$
declare actor uuid;t beta_private.provider_trials;c beta_private.market_data_config;
begin
 if tg_op<>'INSERT' then raise exception 'Manual permits are immutable and cannot be replayed';end if;
 actor:=beta_private.scanner_assert_actor(true);
 select * into t from beta_private.provider_trials where id=new.trial_id for share;
 if new.created_by is distinct from actor or not beta_private.provider_trial_active(t.rights_reference) or new.expires_at<=clock_timestamp()
 or new.expires_at>least(clock_timestamp()+interval '30 minutes',t.next_review_at,t.effective_to) then raise exception 'Current bounded manual permit required';end if;
 if new.operation<>'sports' then
  select * into c from beta_private.market_data_config where id=new.config_id for share;
  if c.id is null or not c.enabled or c.provider<>t.provider or c.rights_reference<>t.rights_reference or c.effective_from>clock_timestamp() or c.effective_to<=clock_timestamp()
  or not exists(select 1 from jsonb_array_elements(c.configuration->'competitions')v where v->>'providerCompetitionId'=new.competition)
  or (new.operation='odds' and new.competition='americanfootball_nfl') or (new.operation='scores' and t.scopes->>'resultsInspection' is distinct from 'true') then raise exception 'Exact reviewed trial competition required';end if;
 end if;
 perform beta_private.scanner_assert_actor(true);
 insert into beta_private.audit_events(actor,action,subject,details) values(actor::text,'provider_trial_permit',new.id::text,jsonb_build_object('operation',new.operation,'competition',new.competition,'expiresAt',new.expires_at));return new;
end $$;
create trigger provider_trial_permit before insert or update or delete on beta_private.provider_trial_permits for each row execute function beta_private.provider_trial_permit_guard();
create function beta_private.reserve_provider_trial(p_permit uuid,p_token_hash text,p_scope text,p_cost integer,p_poll uuid) returns uuid language plpgsql set search_path='' as $$
declare p beta_private.provider_trial_permits;t beta_private.provider_trials;h beta_private.source_health;c beta_private.market_data_config;spent bigint;attempts bigint;rid uuid;
begin
 select * into p from beta_private.provider_trial_permits where id=p_permit;
 if p.id is null or p.token_hash is distinct from p_token_hash then raise exception 'Manual permit unavailable';end if;
 -- One lock covers every request and every UTC month; no budget reset or concurrent double-spend.
 select * into t from beta_private.provider_trials where id=p.trial_id for update;
 insert into beta_private.source_health(provider) values(t.provider) on conflict do nothing;
 select * into h from beta_private.source_health where provider=t.provider for update;
 if p.config_id is not null then select * into c from beta_private.market_data_config where id=p.config_id for share;end if;
 if not beta_private.provider_trial_active(t.rights_reference) or p.expires_at<=clock_timestamp()
 or p_scope is distinct from (case when p.operation='sports' then 'sports' else p.operation||':'||p.competition end)
 or p_cost is null or p_cost<0 or p_cost is distinct from (case when p.operation='odds' then jsonb_array_length(c.configuration->'regions') when p.operation='scores' then 2 else 0 end)
 or (p.operation<>'sports' and (c.id is null or not c.enabled or c.rights_reference<>t.rights_reference or c.effective_from>clock_timestamp() or c.effective_to<=clock_timestamp()))
 or (p.operation<>'sports' and (h.rights_reference is distinct from t.rights_reference or h.capabilities->>'display' is distinct from 'true' or h.capabilities->>'retention' is distinct from 'true'))
 or exists(select 1 from beta_private.provider_trial_requests where permit_id=p.id)
 or exists(select 1 from beta_private.provider_trial_requests where trial_id=t.id and completed_at is null)
 or exists(select 1 from beta_private.feature_flags where enabled and key in ('edge_scanner','auto_publish_docked_edges','publication','forward_paper','sending'))
 then raise exception 'Expired, replayed or mismatched trial authority';end if;
 select count(*),coalesce(sum(greatest(reserved_credits,coalesce(reported_credits,0))),0) into attempts,spent from beta_private.provider_trial_requests where trial_id=t.id;
 if attempts>=t.attempt_cap or spent+p_cost>t.credit_cap or (p.operation<>'sports' and h.credits_remaining is null) or (p_cost>0 and h.credits_remaining<p_cost)
 or (h.circuit_until is not null and h.circuit_until>clock_timestamp()) then raise exception 'Trial credit or request budget exhausted or unknown';end if;
 if not exists(select 1 from beta_private.provider_poll_runs where id=p_poll and provider=t.provider and quota_charge=0) then raise exception 'New trial poll record required';end if;
 perform set_config('docked.trial_write','reserve',true);
 insert into beta_private.provider_trial_requests(permit_id,trial_id,poll_run_id,scope,reserved_credits) values(p.id,t.id,p_poll,p_scope,p_cost) returning id into rid;
 perform set_config('docked.trial_write','',true);
 update beta_private.provider_poll_runs set quota_charge=p_cost where id=p_poll;
 update beta_private.source_health set credits_remaining=case when credits_remaining is null then null else greatest(0,credits_remaining-p_cost) end where provider=t.provider;
 return rid;
end $$;
create function beta_private.provider_trial_request_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Trial request history is retained';end if;
 if tg_op='INSERT' and current_setting('docked.trial_write',true) is distinct from 'reserve' then raise exception 'Atomic trial reservation required';end if;
 if tg_op='UPDATE' and ((to_jsonb(new)-array['reported_credits','remaining','used','headers_at','status','completed_at','error_code','diagnostics']) is distinct from (to_jsonb(old)-array['reported_credits','remaining','used','headers_at','status','completed_at','error_code','diagnostics'])
 or old.completed_at is not null or (old.headers_at is not null and (new.reported_credits is distinct from old.reported_credits or new.remaining is distinct from old.remaining or new.used is distinct from old.used or new.headers_at is distinct from old.headers_at))) then raise exception 'Trial reservation and observed quota are immutable';end if;
 return new;
end $$;
create trigger provider_trial_request before insert or update or delete on beta_private.provider_trial_requests for each row execute function beta_private.provider_trial_request_guard();
create trigger provider_trial_diagnostics_immutable before update or delete on beta_private.provider_trial_diagnostics for each row execute function beta_private.immutable();
-- Existing current-evidence authority is additionally withdrawn when the trial review expires/revokes.
alter function beta_private.market_data_source_current(text,timestamptz) rename to market_data_source_current_before_trial;
create function beta_private.market_data_source_current(p_snapshot text,p_at timestamptz) returns boolean language sql volatile set search_path='' as $$
 select beta_private.market_data_source_current_before_trial(p_snapshot,p_at) and not exists(
  select 1 from beta_private.odds_snapshots q join beta_private.provider_trials t on t.provider=q.provider and t.rights_reference=q.provenance
  where q.id=p_snapshot and (not beta_private.provider_trial_active(t.rights_reference)))
$$;
do $$declare n text;begin
 foreach n in array array['provider_trials','provider_trial_permits','provider_trial_requests','provider_trial_diagnostics'] loop
  execute format('alter table beta_private.%I enable row level security',n);
  execute format('revoke all on beta_private.%I from public,anon,authenticated',n);
 end loop;
end $$;
revoke all on function beta_private.provider_trial_active(text),beta_private.provider_trial_review_guard(),beta_private.provider_trial_permit_guard(),beta_private.reserve_provider_trial(uuid,text,text,integer,uuid),beta_private.provider_trial_request_guard(),beta_private.market_data_source_current(text,timestamptz),beta_private.market_data_source_current_before_trial(text,timestamptz) from public,anon,authenticated;


-- SOURCE 20261003232606_phase5a_reviewed_driver_recovery.sql sha256=336877fac016f94cd80ad841a4db25659787675cfa2b269f33c33d1a5259b85b
-- Review one known legacy free-bootstrap driver failure; never rewrite its request or quota.
create table beta_private.provider_trial_failure_reviews (
 request_id uuid primary key references beta_private.provider_trial_requests(id),
 trial_id uuid not null unique references beta_private.provider_trials(id),
 reviewed_by uuid not null,
 reviewed_at timestamptz not null default clock_timestamp(),
 reason_code text not null check(reason_code='SERVER_TRANSACTION_COMPATIBILITY'),
 repair_code_commit text not null check(repair_code_commit ~ '^[a-f0-9]{40}$'),
 evidence_reference text not null check(length(btrim(evidence_reference)) between 10 and 300),
 evidence_sha256 text not null check(evidence_sha256 ~ '^[a-f0-9]{64}$')
);
alter table beta_private.provider_trial_failure_reviews enable row level security;
revoke all on beta_private.provider_trial_failure_reviews from public,anon,authenticated,docked_beta_app;

create function beta_private.provider_trial_failure_review_guard() returns trigger language plpgsql set search_path='' as $$
declare actor uuid;r beta_private.provider_trial_requests;p beta_private.provider_trial_permits;t beta_private.provider_trials;
begin
 if tg_op<>'INSERT' then raise exception 'Driver failure reviews are immutable';end if;
 actor:=beta_private.scanner_assert_actor(true);
 select * into t from beta_private.provider_trials where id=new.trial_id for update;
 select * into r from beta_private.provider_trial_requests where id=new.request_id for share;
 select * into p from beta_private.provider_trial_permits where id=r.permit_id;
 if t.id is null or r.id is null or r.trial_id is distinct from t.id or p.operation is distinct from 'sports'
 or r.scope is distinct from 'sports' or r.status is distinct from 'FAILED' or r.reserved_credits<>0
 or r.headers_at is not null or r.reported_credits is not null or r.remaining is not null or r.used is not null
 or r.completed_at is null or r.error_code is distinct from 'TRIAL_REQUEST_FAILED'
 -- Only the original serializer/transaction failure signature is reviewable here. New failures have object diagnostics.
 or r.diagnostics is distinct from to_jsonb('{}'::text)
 or exists(select 1 from beta_private.provider_trial_requests earlier where earlier.trial_id=t.id and (earlier.started_at,earlier.id)<(r.started_at,r.id))
 or t.provider<>'the-odds-api' or t.project_ref<>'bckkllmndoxzpzdqrevb' or t.decision<>'APPROVED_FOR_PREVIEW_TRIAL'
 or t.revoked_at is not null or t.reviewed_at>clock_timestamp() or least(t.next_review_at,t.effective_to)<=clock_timestamp()
 or new.reviewed_by is distinct from actor or new.reviewed_at>clock_timestamp() or new.reviewed_at<clock_timestamp()-interval '5 minutes'
 then raise exception 'Exact reviewed legacy free-bootstrap failure required';end if;
 perform beta_private.scanner_assert_actor(true);
 insert into beta_private.audit_events(actor,action,subject,details) values(actor::text,'provider_trial_driver_failure_review',r.id::text,
 jsonb_build_object('trialId',t.id,'reason',new.reason_code,'repairCommit',new.repair_code_commit,'evidenceReference',new.evidence_reference,'evidenceSha256',new.evidence_sha256,'originalFailureRetained',true,'quotaObservation','UNKNOWN'));
 return new;
end $$;
create trigger provider_trial_failure_review before insert or update or delete on beta_private.provider_trial_failure_reviews for each row execute function beta_private.provider_trial_failure_review_guard();

create or replace function beta_private.provider_trial_active(p_rights text) returns boolean language sql volatile set search_path='' as $$
 select exists(select 1 from beta_private.provider_trials t where provider='the-odds-api' and project_ref='bckkllmndoxzpzdqrevb' and rights_reference=p_rights and decision='APPROVED_FOR_PREVIEW_TRIAL' and revoked_at is null and reviewed_at<=clock_timestamp() and next_review_at>clock_timestamp() and effective_to>clock_timestamp()
 and not exists(select 1 from beta_private.provider_trial_requests r where r.trial_id=t.id and
 (r.reported_credits>r.reserved_credits or (r.status='FAILED' and not exists(select 1 from beta_private.provider_trial_failure_reviews review where review.request_id=r.id and review.trial_id=t.id)))))
$$;

-- New writes must carry an actual JSON object. Preserve existing completed legacy evidence unchanged.
create function beta_private.provider_trial_diagnostic_shape_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if jsonb_typeof(new.diagnostics) is distinct from 'object' then raise exception 'Trial diagnostics must be a JSON object';end if;
 return new;
end $$;
create trigger provider_trial_diagnostic_shape before insert or update on beta_private.provider_trial_requests for each row execute function beta_private.provider_trial_diagnostic_shape_guard();

-- Retain the reviewed reservation algorithm; additionally lock/recheck the permit issuer at execution.
alter function beta_private.reserve_provider_trial(uuid,text,text,integer,uuid) rename to reserve_provider_trial_before_driver_review;
create function beta_private.reserve_provider_trial(p_permit uuid,p_token_hash text,p_scope text,p_cost integer,p_poll uuid) returns uuid language plpgsql set search_path='' as $$
declare issuer uuid;rid uuid;
begin
 select created_by into issuer from beta_private.provider_trial_permits where id=p_permit;
 if issuer is null then raise exception 'Manual permit unavailable';end if;
 perform 1 from beta_public.profiles where id=issuer for share;
 perform 1 from beta_private.roles where user_id=issuer for share;
 perform 1 from auth.users where id=issuer for share;
 rid:=beta_private.reserve_provider_trial_before_driver_review(p_permit,p_token_hash,p_scope,p_cost,p_poll);
 -- All quota/config lock waits have completed. A removed role, erased/disabled profile or ban denies atomically.
 if not exists(select 1 from beta_public.profiles profile join beta_private.roles role on role.user_id=profile.id join auth.users u on u.id=profile.id
 where profile.id=issuer and profile.disabled_at is null and role.role in ('owner','admin')
 and coalesce(nullif(to_jsonb(u)->>'banned_until','')::timestamptz,'-infinity'::timestamptz)<=clock_timestamp())
 then raise exception 'Current manual permit issuer required';end if;
 return rid;
end $$;
revoke all on function beta_private.provider_trial_failure_review_guard(),beta_private.provider_trial_diagnostic_shape_guard(),beta_private.reserve_provider_trial_before_driver_review(uuid,text,text,integer,uuid),beta_private.reserve_provider_trial(uuid,text,text,integer,uuid),beta_private.provider_trial_active(text) from public,anon,authenticated,docked_beta_app;


-- SOURCE 20261004003850_phase5b_independent_football_model_ledger.sql sha256=779c6fafdac2343cd6f7dc1f7f5c063bc69d0dec4abbed845b3e30f4b3dafac3
-- Independent football infrastructure only. No model, source, probabilities or publication is activated.
create table beta_private.football_model_versions(
 id text primary key, method text not null check(method='independent-football-model'),
 configuration jsonb not null, config_hash text not null unique check(config_hash ~ '^[a-f0-9]{64}$'),
 code_commit text not null check(code_commit ~ '^[a-f0-9]{40}$'),
 lifecycle text not null default 'DRAFT' check(lifecycle in('DRAFT','RESEARCH','FORWARD_CALIBRATION','APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE','RETIRED')),
 created_by uuid not null, created_at timestamptz not null default clock_timestamp(), changed_at timestamptz not null default clock_timestamp()
);
create table beta_private.football_model_transitions(
 id uuid primary key default gen_random_uuid(),model_version text not null references beta_private.football_model_versions(id),
 from_state text not null,to_state text not null,actor uuid not null,reason text not null check(length(btrim(reason)) between 12 and 2000),
 config_hash text not null,code_commit text not null,configuration jsonb not null,evidence jsonb not null,created_at timestamptz not null default clock_timestamp()
);
-- A future reviewed estimator implementation must explicitly register its code/configuration binding.
-- No application endpoint creates these records; today's default provider cannot issue READY predictions.
create table beta_private.football_model_implementations(
 model_version text primary key references beta_private.football_model_versions(id),implementation_id text not null,
 code_commit text not null check(code_commit ~ '^[a-f0-9]{40}$'),config_hash text not null,
 training_data_hash text not null check(training_data_hash ~ '^[a-f0-9]{64}$'),
 reviewed_by uuid not null,evidence text not null check(length(btrim(evidence))>=20),created_at timestamptz not null default clock_timestamp()
);
create table beta_private.football_sporting_sources(
 id text primary key,provider text not null,source_version text not null,rights_reference text not null,
 purposes text[] not null,known_at timestamptz not null,effective_from timestamptz not null,effective_to timestamptz not null,
 approved_by uuid not null,revoked_at timestamptz,created_at timestamptz not null default clock_timestamp(),
 check(effective_from<effective_to),check(purposes @> array['model_training','derived_probabilities','retained_evidence'])
);
create table beta_private.football_sporting_inputs(
 id uuid primary key default gen_random_uuid(),event_id text not null references beta_private.events(id),
 payload jsonb not null,input_hash text not null unique check(input_hash ~ '^[a-f0-9]{64}$'),
 as_of_time timestamptz not null,input_cutoff timestamptz not null,source_ids text[] not null,
 created_by uuid not null,created_at timestamptz not null default clock_timestamp()
);
create table beta_private.football_model_attempts(
 id uuid primary key default gen_random_uuid(),idempotency_key text not null unique,
 job_id uuid not null references beta_private.job_runs(id),event_id text not null references beta_private.events(id),
 requested_model_version text not null,model_version text references beta_private.football_model_versions(id),
 input_snapshot_id uuid references beta_private.football_sporting_inputs(id),
 window_seconds integer not null check(window_seconds>0),status text not null check(status in('READY','ABSTAIN','NOT_CONFIGURED')),
 probabilities jsonb,fair_odds jsonb,quality jsonb not null,reason text,
 config_hash text,input_hash text,code_commit text not null check(code_commit ~ '^[a-f0-9]{40}$'),
 as_of_time timestamptz not null,calculated_at timestamptz not null,input_cutoff timestamptz,event_start_at timestamptz not null,event_participants jsonb not null,
 provenance jsonb not null,recorded_xid xid8 not null,created_at timestamptz not null default clock_timestamp(),
 unique(event_id,requested_model_version,window_seconds),
 check((status='READY' and probabilities is not null and model_version is not null and input_snapshot_id is not null and input_hash is not null and input_cutoff is not null)
 or(status<>'READY' and probabilities is null and reason is not null))
);
create table beta_private.football_model_outcomes(
 id uuid primary key default gen_random_uuid(),prediction_id uuid not null references beta_private.football_model_attempts(id),
 source_id text not null references beta_private.football_sporting_sources(id),source_event_id text not null,revision text not null,sequence integer not null default 1 check(sequence>0),
 result text not null check(result in('home','draw','away','void','manual_review')),
 home_goals integer check(home_goals>=0),away_goals integer check(away_goals>=0),
 observed_at timestamptz not null,evidence jsonb not null,corrects uuid references beta_private.football_model_outcomes(id),
 actor uuid not null,reason text not null check(length(btrim(reason))>=12),created_at timestamptz not null default clock_timestamp(),
 unique(prediction_id,source_id,source_event_id,revision)
);
create unique index football_outcome_initial on beta_private.football_model_outcomes(prediction_id) where corrects is null;
create unique index football_outcome_correction_once on beta_private.football_model_outcomes(corrects) where corrects is not null;
create table beta_private.football_edge_policy_approvals(
 strategy_id text primary key references beta_private.strategy_versions(id),model_version text not null references beta_private.football_model_versions(id),
 config_hash text not null,code_commit text not null,actor uuid not null,reason text not null check(length(btrim(reason))>=12),
 created_at timestamptz not null default clock_timestamp(),revoked_at timestamptz
);
alter table beta_private.strategy_versions add column football_model_version text references beta_private.football_model_versions(id);
alter table beta_private.scanner_candidates add column prediction_id uuid references beta_private.football_model_attempts(id);
alter table beta_private.tip_publications add column prediction_id uuid references beta_private.football_model_attempts(id);
create table beta_private.official_record_boundary(
 singleton boolean primary key default true check(singleton),first_tip_id uuid not null unique references beta_private.tip_publications(id),
 started_at timestamptz not null,actor uuid not null
);
create table beta_private.official_docked_publications(
 tip_id uuid primary key references beta_private.tip_publications(id),event_id text not null unique references beta_private.events(id),
 prediction_id uuid not null references beta_private.football_model_attempts(id),model_version text not null references beta_private.football_model_versions(id),
 published_at timestamptz not null,created_at timestamptz not null default clock_timestamp()
);

create function beta_private.football_json_hash(value jsonb) returns text language sql immutable set search_path='' as $$
 select encode(sha256(convert_to(beta_private.phase5_canonical_json(value),'UTF8')),'hex')
$$;
create function beta_private.football_sport_only(value jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare k text;v jsonb;
begin
 if jsonb_typeof(value)='object' then
  for k,v in select * from jsonb_each(value) loop
   if lower(k) in('odds','prices','price','bookmaker','bookmakers','marketreference','closingodds','probability','probabilities','impliedprobability','referenceodds','marketprice') or not beta_private.football_sport_only(v) then return false;end if;
  end loop;
 elsif jsonb_typeof(value)='array' then
  for v in select * from jsonb_array_elements(value) loop if not beta_private.football_sport_only(v) then return false;end if;end loop;
 end if;return true;
end $$;
create function beta_private.football_version_guard() returns trigger language plpgsql set search_path='' as $$
declare actor uuid;
begin
 actor:=beta_private.scanner_assert_actor(true);
 if tg_op='DELETE' then raise exception 'Model versions are retained';end if;
 if tg_op='INSERT' then
  if new.created_by is distinct from actor or new.lifecycle<>'DRAFT' or new.config_hash is distinct from beta_private.football_json_hash(new.configuration)
  or new.configuration->>'modelVersion' is distinct from new.id then raise exception 'Immutable model configuration binding required';end if;
  new.created_at:=clock_timestamp();new.changed_at:=new.created_at;
 elsif (to_jsonb(new)-array['lifecycle','changed_at']) is distinct from (to_jsonb(old)-array['lifecycle','changed_at'])
 or current_setting('docked.model_transition',true) is distinct from old.id then raise exception 'Create a new model version or use audited transition';end if;
 return new;
end $$;
create trigger football_version_guard before insert or update or delete on beta_private.football_model_versions for each row execute function beta_private.football_version_guard();

create function beta_private.transition_football_model(p_id text,p_to text,p_reason text,p_evidence jsonb) returns text language plpgsql set search_path='' as $$
declare actor uuid;s beta_private.football_model_versions;valid boolean;
begin
 actor:=beta_private.scanner_assert_actor(true);select * into s from beta_private.football_model_versions where id=p_id for update;
 if s.id is null or length(btrim(p_reason))<12 then raise exception 'Model and review reason required';end if;
 valid:=(s.lifecycle='DRAFT' and p_to='RESEARCH') or(s.lifecycle='RESEARCH' and p_to='FORWARD_CALIBRATION')
 or(s.lifecycle='FORWARD_CALIBRATION' and p_to='APPROVED_FOR_CANDIDATES') or(s.lifecycle='APPROVED_FOR_CANDIDATES' and p_to='APPROVED_FOR_LIVE')
 or(s.lifecycle<>'RETIRED' and p_to='RETIRED');
 if not valid then raise exception 'Invalid model lifecycle transition';end if;
 if p_to in('APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE') and (
 not exists(select 1 from beta_private.football_model_implementations i where i.model_version=s.id and i.code_commit=s.code_commit and i.config_hash=s.config_hash)
 or not exists(select 1 from beta_private.football_model_attempts p join lateral(select result from beta_private.football_model_outcomes where prediction_id=p.id order by sequence desc limit 1)o on true where p.model_version=s.id and p.status='READY' and o.result in('home','draw','away'))
 or not coalesce(p_evidence @> '{"probabilitySanity":true,"dataQuality":true,"operationalReadiness":true,"prospectiveCalibrationReviewed":true}'::jsonb,false)
 ) then raise exception 'Current implementation, prospective calibration and explicit quality review required';end if;
 perform beta_private.scanner_assert_actor(true);
 perform set_config('docked.model_transition',p_id,true);
 update beta_private.football_model_versions set lifecycle=p_to,changed_at=clock_timestamp() where id=p_id;
 perform set_config('docked.model_transition','',true);
 insert into beta_private.football_model_transitions(model_version,from_state,to_state,actor,reason,config_hash,code_commit,configuration,evidence)
 values(p_id,s.lifecycle,p_to,actor,p_reason,s.config_hash,s.code_commit,s.configuration,p_evidence);
 return p_to;
end $$;

create function beta_private.football_source_guard() returns trigger language plpgsql set search_path='' as $$
declare actor uuid;
begin
 actor:=beta_private.scanner_assert_actor(true);
 if tg_op='DELETE' then raise exception 'Source rights audit retained';end if;
 if tg_op='UPDATE' then
  if old.revoked_at is not null or new.revoked_at is null or new.revoked_at>clock_timestamp()
  or (to_jsonb(old)-'revoked_at') is distinct from(to_jsonb(new)-'revoked_at') then raise exception 'Source approval immutable except revocation';end if;
 elsif new.approved_by is distinct from actor or new.known_at>clock_timestamp() or length(btrim(new.rights_reference))<8 then raise exception 'Current reviewed sporting source required';end if;
 insert into beta_private.audit_events(actor,action,subject,details) values(actor::text,'football_source_review',new.id,jsonb_build_object('revoked',new.revoked_at is not null));
 return new;
end $$;
create trigger football_source_guard before insert or update or delete on beta_private.football_sporting_sources for each row execute function beta_private.football_source_guard();

create function beta_private.football_input_guard() returns trigger language plpgsql set search_path='' as $$
declare e beta_private.events;s beta_private.football_sporting_sources;m jsonb;sid text;actor uuid;checked timestamptz;approval jsonb;
begin
 actor:=beta_private.scanner_assert_actor(true);select * into e from beta_private.events where id=new.event_id for share;
 foreach sid in array new.source_ids loop select * into s from beta_private.football_sporting_sources where id=sid for share;
  if s.id is null or s.revoked_at is not null or s.known_at>new.as_of_time or s.effective_from>new.as_of_time or s.effective_to<=clock_timestamp() then raise exception 'Current dated sporting rights required';end if;
 end loop;
 checked:=clock_timestamp();perform beta_private.scanner_assert_actor(true);
 foreach sid in array new.source_ids loop
  select * into s from beta_private.football_sporting_sources where id=sid;
  if s.revoked_at is not null or s.effective_to<=checked then raise exception 'Sporting authority expired while waiting';end if;
 end loop;
 if e.id is null or e.status<>'scheduled' or e.start_at<=checked or new.created_by is distinct from actor or cardinality(new.source_ids)<1
 or new.as_of_time>checked or new.input_cutoff>new.as_of_time or new.input_hash is distinct from beta_private.football_json_hash(new.payload)
 or not beta_private.football_sport_only(new.payload) or new.payload#>>'{event,eventId}' is distinct from new.event_id
 or new.payload#>>'{event,competitionId}' is distinct from e.competition_id
 or (new.payload#>>'{event,startAt}')::timestamptz is distinct from e.start_at
 or jsonb_typeof(new.payload->'matches') is distinct from 'array' or jsonb_array_length(new.payload->'matches')=0
 or (new.payload->>'asOfTime')::timestamptz is distinct from new.as_of_time
 or new.payload->>'schemaVersion' is distinct from 'football-sporting-input-v1'
 or (new.payload-array['schemaVersion','event','asOfTime','calculatedAt','codeCommit','sourceApprovals','matches','missingRequired','missingOptional'])<>'{}'::jsonb
 or ((new.payload->'event')-array['eventId','competitionId','homeTeamId','awayTeamId','sport','startAt','status','knownAt','sourceId'])<>'{}'::jsonb
 or not coalesce(new.payload#>>'{event,sport}'='football' and new.payload#>>'{event,status}'='scheduled'
 and new.payload#>>'{event,homeTeamId}'<>new.payload#>>'{event,awayTeamId}' and length(new.payload#>>'{event,homeTeamId}')>0 and length(new.payload#>>'{event,awayTeamId}')>0
 and (new.payload#>>'{event,knownAt}')::timestamptz<=new.as_of_time and new.payload#>>'{event,sourceId}'=any(new.source_ids)
 and(new.payload->>'calculatedAt')::timestamptz>=new.as_of_time and(new.payload->>'calculatedAt')::timestamptz<=checked and(new.payload->>'codeCommit')~'^[a-f0-9]{40}$',false)
 or jsonb_typeof(new.payload->'sourceApprovals') is distinct from 'array'
 or jsonb_typeof(new.payload->'missingRequired') is distinct from 'array' or jsonb_array_length(new.payload->'missingRequired')<>0
 or jsonb_typeof(new.payload->'missingOptional') is distinct from 'array'
 or cardinality(new.source_ids)<>(select count(distinct x) from unnest(new.source_ids)x)
 or cardinality(new.source_ids)<>(select count(*) from jsonb_array_elements(new.payload->'sourceApprovals'))
 or (select count(*) from jsonb_array_elements(new.payload->'matches'))<>(select count(distinct x->>'eventId') from jsonb_array_elements(new.payload->'matches')x)
 or (select count(*) from jsonb_array_elements(new.payload->'matches'))<>(select count(distinct x->>'id') from jsonb_array_elements(new.payload->'matches')x)
 then raise exception 'Pre-event sporting-only input evidence required';end if;
 for approval in select * from jsonb_array_elements(new.payload->'sourceApprovals') loop
  select * into s from beta_private.football_sporting_sources where id=approval->>'sourceId';
  if s.id is null or not(s.id=any(new.source_ids)) or approval->>'provider' is distinct from s.provider or approval->>'sourceVersion' is distinct from s.source_version
  or approval->>'rightsReference' is distinct from s.rights_reference or (approval->>'knownAt')::timestamptz is distinct from s.known_at
  or (approval->>'effectiveFrom')::timestamptz is distinct from s.effective_from or (approval->>'effectiveTo')::timestamptz is distinct from s.effective_to
  or not coalesce(approval->'allowedPurposes' @> '["model_training","derived_probabilities","retained_evidence"]'::jsonb,false)
  or (approval-array['sourceId','provider','sourceVersion','rightsReference','allowedPurposes','knownAt','effectiveFrom','effectiveTo'])<>'{}'::jsonb
  then raise exception 'Source approval payload must match reviewed canonical authority';end if;
 end loop;
 for m in select * from jsonb_array_elements(new.payload->'matches') loop
  if m->>'eventId'=e.id or not(m->>'sourceId'=any(new.source_ids)) or m->>'status' is distinct from 'final'
  or not coalesce((m->>'startAt')::timestamptz<(m->>'completedAt')::timestamptz and (m->>'completedAt')::timestamptz<=(m->>'knownAt')::timestamptz
   and (m->>'knownAt')::timestamptz<=(m->>'receivedAt')::timestamptz and (m->>'receivedAt')::timestamptz<=new.input_cutoff,false)
  or m->>'competitionId' is distinct from e.competition_id
  or not coalesce(length(m->>'id')>0 and length(m->>'eventId')>0 and length(m->>'homeTeamId')>0 and length(m->>'awayTeamId')>0 and m->>'homeTeamId'<>m->>'awayTeamId'
   and(m->>'regulationHomeGoals')::integer between 0 and 100 and(m->>'regulationAwayGoals')::integer between 0 and 100 and(m->>'revision')::integer>0,false)
  or(m-array['id','eventId','competitionId','homeTeamId','awayTeamId','startAt','completedAt','knownAt','receivedAt','sourceId','revision','status','regulationHomeGoals','regulationAwayGoals'])<>'{}'::jsonb
  then raise exception 'No look-ahead in sporting results';end if;
 end loop;
 new.created_at:=checked;return new;
end $$;
create trigger football_input_guard before insert on beta_private.football_sporting_inputs for each row execute function beta_private.football_input_guard();

create function beta_private.football_prediction_guard() returns trigger language plpgsql set search_path='' as $$
declare e beta_private.events;v beta_private.football_model_versions;i beta_private.football_sporting_inputs;sid text;checked timestamptz;p numeric;
begin
 perform beta_private.scanner_assert_worker(new.job_id);
 select * into e from beta_private.events where id=new.event_id for share;
 if new.model_version is not null then select * into v from beta_private.football_model_versions where id=new.model_version for share;end if;
 if new.input_snapshot_id is not null then select * into i from beta_private.football_sporting_inputs where id=new.input_snapshot_id for share;end if;
 if new.status='READY' then foreach sid in array coalesce(i.source_ids,'{}') loop perform id from beta_private.football_sporting_sources where id=sid for share;end loop;end if;
 checked:=clock_timestamp();perform beta_private.scanner_assert_worker(new.job_id);
 if e.id is null or e.status<>'scheduled' or e.start_at<=checked or new.as_of_time>checked or new.calculated_at>checked or new.calculated_at<new.as_of_time
 or new.calculated_at<checked-interval '60 seconds' or new.code_commit is distinct from current_setting('docked.scanner_commit',true)
 or (v.id is not null and (v.id<>new.requested_model_version or v.code_commit<>new.code_commit or v.config_hash is distinct from new.config_hash or v.lifecycle not in('RESEARCH','FORWARD_CALIBRATION','APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE')))
 then raise exception 'Current pre-event model attempt required';end if;
 if new.status='READY' then
  if v.id is null or i.id is null or i.event_id<>e.id or i.input_hash is distinct from new.input_hash or i.input_cutoff is distinct from new.input_cutoff
   or i.as_of_time>new.as_of_time or i.created_at>new.as_of_time or i.created_at>=checked
   or not exists(select 1 from beta_private.football_model_implementations impl where impl.model_version=v.id and impl.code_commit=new.code_commit and impl.config_hash=new.config_hash)
   or jsonb_typeof(new.probabilities) is distinct from 'object' or (select count(*) from jsonb_object_keys(new.probabilities))<>3
   or not(new.probabilities ?& array['home','draw','away']) then raise exception 'Registered independent estimator and retained sporting input required';end if;
  foreach sid in array i.source_ids loop if not exists(select 1 from beta_private.football_sporting_sources where id=sid and revoked_at is null and effective_from<=new.as_of_time and known_at<=new.as_of_time and effective_to>checked) then raise exception 'Sporting source approval withdrawn';end if;end loop;
  if not coalesce((new.probabilities->>'home')::numeric>=0 and (new.probabilities->>'home')::numeric<=1
   and (new.probabilities->>'draw')::numeric>=0 and (new.probabilities->>'draw')::numeric<=1
   and (new.probabilities->>'away')::numeric>=0 and (new.probabilities->>'away')::numeric<=1
   and (new.probabilities->>'home')::numeric+(new.probabilities->>'draw')::numeric+(new.probabilities->>'away')::numeric=1,false)
  then raise exception 'Complete normalized independent probabilities required';end if;
 end if;
 if new.status='READY' then
  new.fair_odds:=jsonb_build_object('home',1/nullif((new.probabilities->>'home')::numeric,0),'draw',1/nullif((new.probabilities->>'draw')::numeric,0),'away',1/nullif((new.probabilities->>'away')::numeric,0));
 else new.fair_odds:=null;end if;
 new.recorded_xid:=pg_current_xact_id();new.event_start_at:=e.start_at;new.event_participants:=e.participants;new.created_at:=checked;return new;
end $$;
create trigger football_prediction_guard before insert on beta_private.football_model_attempts for each row execute function beta_private.football_prediction_guard();

create function beta_private.football_outcome_guard() returns trigger language plpgsql set search_path='' as $$
declare p beta_private.football_model_attempts;e beta_private.events;s beta_private.football_sporting_sources;latest uuid;actor uuid;
begin
 actor:=beta_private.scanner_assert_actor(true);select * into p from beta_private.football_model_attempts where id=new.prediction_id for update;
 select * into e from beta_private.events where id=p.event_id for share;select * into s from beta_private.football_sporting_sources where id=new.source_id for share;
 select id into latest from beta_private.football_model_outcomes where prediction_id=p.id order by created_at desc,id desc limit 1;
 perform beta_private.scanner_assert_actor(true);
 if p.status is distinct from 'READY' or e.start_at is distinct from p.event_start_at or p.event_start_at>clock_timestamp() or new.observed_at<p.event_start_at or new.observed_at>clock_timestamp()
 or s.id is null or s.revoked_at is not null or s.effective_to<=clock_timestamp() or new.actor is distinct from actor or latest is distinct from new.corrects
 or not beta_private.football_sport_only(new.evidence) then raise exception 'Authorized outcome or linked correction required';end if;
 if new.result in('home','draw','away') and (new.home_goals is null or new.away_goals is null or new.result is distinct from(case when new.home_goals>new.away_goals then 'home' when new.home_goals<new.away_goals then 'away' else 'draw' end)) then raise exception 'Regulation outcome mismatch';end if;
 new.sequence:=coalesce((select max(sequence)+1 from beta_private.football_model_outcomes where prediction_id=p.id),1);
 new.created_at:=clock_timestamp();return new;
end $$;
create trigger football_outcome_guard before insert on beta_private.football_model_outcomes for each row execute function beta_private.football_outcome_guard();

do $$declare n text;begin
 foreach n in array array['football_model_versions','football_model_transitions','football_model_implementations','football_sporting_sources','football_sporting_inputs','football_model_attempts','football_model_outcomes','football_edge_policy_approvals','official_record_boundary','official_docked_publications'] loop
  execute format('alter table beta_private.%I enable row level security',n);
  execute format('revoke all on beta_private.%I from public,anon,authenticated,docked_beta_app',n);
  if n not in('football_model_versions','football_sporting_sources','football_edge_policy_approvals') then
   execute format('create trigger immutable before update or delete on beta_private.%I for each row execute function beta_private.immutable()',n);
  end if;
 end loop;
end $$;
revoke all on function beta_private.football_json_hash(jsonb),beta_private.football_sport_only(jsonb),beta_private.football_version_guard(),beta_private.transition_football_model(text,text,text,jsonb),beta_private.football_source_guard(),beta_private.football_input_guard(),beta_private.football_prediction_guard(),beta_private.football_outcome_guard() from public,anon,authenticated,docked_beta_app;

create function beta_private.football_implementation_guard() returns trigger language plpgsql set search_path='' as $$
declare v beta_private.football_model_versions;a uuid;
begin
 a:=beta_private.scanner_assert_actor(true);select * into v from beta_private.football_model_versions where id=new.model_version for share;
 if new.reviewed_by is distinct from a or v.config_hash is distinct from new.config_hash or v.code_commit is distinct from new.code_commit
 or v.configuration->>'trainingDataHash' is distinct from new.training_data_hash or v.configuration->'parameters' is null or v.configuration->'parameters'='null'::jsonb
 or v.lifecycle not in('RESEARCH','FORWARD_CALIBRATION') then raise exception 'A separately reviewed fitted implementation and real sporting dataset are required';end if;
 new.created_at:=clock_timestamp();return new;
end $$;
create trigger football_implementation_guard before insert on beta_private.football_model_implementations for each row execute function beta_private.football_implementation_guard();

create function beta_private.football_strategy_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' and old.config->>'method'='football-independent-model' and (new.config is distinct from old.config or new.config_hash is distinct from old.config_hash or new.code_commit is distinct from old.code_commit or new.football_model_version is distinct from old.football_model_version) then raise exception 'Material football policy changes require a new version';end if;
 if new.config->>'method'='football-independent-model' then
  new.football_model_version:=new.config->>'modelVersion';
  if new.football_model_version is null or new.config->>'version' is distinct from new.id
  or not coalesce(new.config->>'maxEdgesPerEvent'='1' and (new.config->>'stakeUnits')::numeric=1 and (new.config->>'minEV')::numeric>=0.03
  and (new.config->>'minOdds')::numeric>=1.5 and (new.config->>'maxOdds')::numeric<=5 and (new.config->>'maxEV')::numeric<=0.20
  and (new.config->>'maxAgeSeconds')::integer between 1 and 180 and (new.config->>'safetySeconds')::integer>=600
  and (new.config->>'maxSportDataAgeSeconds')::integer between 1 and 604800,false) then raise exception 'Versioned bounded football strategy required';end if;
 elsif new.football_model_version is not null then raise exception 'Model binding requires independent football strategy';end if;
 return new;
end $$;
create trigger football_strategy_guard before insert or update on beta_private.strategy_versions for each row execute function beta_private.football_strategy_guard();
create function beta_private.football_policy_guard() returns trigger language plpgsql set search_path='' as $$
declare s beta_private.strategy_versions;v beta_private.football_model_versions;a uuid;
begin
 a:=beta_private.scanner_assert_actor(true);
 if tg_op='DELETE' then raise exception 'Policy approval history retained';end if;
 if tg_op='UPDATE' then
  if old.revoked_at is not null or new.revoked_at is null or new.revoked_at>clock_timestamp() or (to_jsonb(new)-'revoked_at') is distinct from(to_jsonb(old)-'revoked_at') then raise exception 'Approval immutable except withdrawal';end if;
 else
  select * into s from beta_private.strategy_versions where id=new.strategy_id for share;select * into v from beta_private.football_model_versions where id=new.model_version for share;
  if new.actor is distinct from a or s.football_model_version is distinct from v.id or s.config_hash is distinct from new.config_hash or s.code_commit is distinct from new.code_commit or v.code_commit is distinct from new.code_commit
  or v.lifecycle not in('RESEARCH','FORWARD_CALIBRATION','APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE') then raise exception 'Current independent model policy review required';end if;
  new.created_at:=clock_timestamp();
 end if;
 perform beta_private.scanner_assert_actor(true);insert into beta_private.audit_events(actor,action,subject,details) values(a::text,'football_edge_policy_review',new.strategy_id,jsonb_build_object('reason',new.reason,'withdrawn',new.revoked_at is not null));return new;
end $$;
create trigger football_policy_guard before insert or update or delete on beta_private.football_edge_policy_approvals for each row execute function beta_private.football_policy_guard();
create function beta_private.set_football_policy_active(p_strategy text,p_active boolean,p_reason text) returns boolean language plpgsql set search_path='' as $$
declare s beta_private.strategy_versions;a uuid;
begin
 a:=beta_private.scanner_assert_actor(true);select * into s from beta_private.strategy_versions where id=p_strategy for update;
 if s.config->>'method' is distinct from 'football-independent-model' or p_active is null or not coalesce(length(btrim(p_reason))>=12,false) then raise exception 'Explicit independent policy activation review required';end if;
 if p_active and not exists(select 1 from beta_private.football_edge_policy_approvals approval join beta_private.football_model_versions v on v.id=approval.model_version where approval.strategy_id=s.id and approval.revoked_at is null and approval.config_hash=s.config_hash and approval.code_commit=s.code_commit and v.code_commit=s.code_commit and v.lifecycle in('RESEARCH','FORWARD_CALIBRATION','APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE')) then raise exception 'Current reviewed model policy required';end if;
 perform beta_private.scanner_assert_actor(true);perform set_config('docked.strategy_transition',s.id,true);
 update beta_private.strategy_versions set active=p_active where id=s.id;perform set_config('docked.strategy_transition','',true);
 insert into beta_private.audit_events(actor,action,subject,details)values(a::text,'football_policy_activation',s.id,jsonb_build_object('active',p_active,'reason',p_reason,'configHash',s.config_hash));return p_active;
end $$;

create function beta_private.assert_football_prediction(p_id uuid) returns void language plpgsql set search_path='' as $$
declare p beta_private.football_model_attempts;v beta_private.football_model_versions;i beta_private.football_sporting_inputs;e beta_private.events;s beta_private.football_sporting_sources;sid text;checked timestamptz;
begin
 select * into p from beta_private.football_model_attempts where id=p_id for share;select * into v from beta_private.football_model_versions where id=p.model_version for share;
 select * into i from beta_private.football_sporting_inputs where id=p.input_snapshot_id for share;select * into e from beta_private.events where id=p.event_id for share;
 foreach sid in array coalesce(i.source_ids,'{}') loop perform id from beta_private.football_sporting_sources where id=sid for share;end loop;
 checked:=clock_timestamp();
 if p.status is distinct from 'READY' or v.lifecycle not in('FORWARD_CALIBRATION','APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE')
 or pg_xact_status(p.recorded_xid) is distinct from 'committed'
 or e.status is distinct from 'scheduled' or e.start_at is distinct from p.event_start_at or e.participants is distinct from p.event_participants or e.start_at<=checked or p.created_at>=checked or p.created_at>=p.event_start_at or p.config_hash is distinct from v.config_hash or p.code_commit is distinct from v.code_commit
 or not exists(select 1 from beta_private.football_model_implementations x where x.model_version=v.id and x.config_hash=p.config_hash and x.code_commit=p.code_commit)
 then raise exception 'Current independently retained prospective prediction required';end if;
 foreach sid in array i.source_ids loop select * into s from beta_private.football_sporting_sources where id=sid;
  if s.id is null or s.revoked_at is not null or s.effective_to<=checked or s.effective_from>p.as_of_time or s.known_at>p.as_of_time then raise exception 'Sporting source authority withdrawn';end if;
 end loop;
end $$;

-- Preserve the old research/paper strategy path; live authority is now independent-model only.
do $$declare definition text;begin
 select pg_get_functiondef('beta_private.scanner_strategy_allowed(text,text)'::regprocedure) into definition;
 execute replace(definition,'FUNCTION beta_private.scanner_strategy_allowed(','FUNCTION beta_private.legacy_scanner_strategy_allowed(');
end $$;
create or replace function beta_private.scanner_strategy_allowed(p_strategy text,p_purpose text) returns boolean language sql stable set search_path='' as $$
 select coalesce((select case when s.config->>'method'='football-independent-model' then s.active and exists(
 select 1 from beta_private.football_model_versions v join beta_private.football_edge_policy_approvals a on a.model_version=v.id
 where a.strategy_id=s.id and a.revoked_at is null and a.config_hash=s.config_hash and a.code_commit=s.code_commit and v.code_commit=s.code_commit
 and case p_purpose when 'research' then v.lifecycle in('RESEARCH','FORWARD_CALIBRATION','APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE') when 'paper' then v.lifecycle in('APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE') when 'live' then v.lifecycle='APPROVED_FOR_LIVE' else false end)
 else p_purpose<>'live' and beta_private.legacy_scanner_strategy_allowed(p_strategy,p_purpose) end from beta_private.strategy_versions s where s.id=p_strategy),false)
$$;
create function beta_private.assert_football_comparison(p_prediction uuid,p_strategy text,p_reference uuid,p_purpose text,p_selection text) returns numeric language plpgsql set search_path='' as $$
declare p beta_private.football_model_attempts;s beta_private.strategy_versions;r beta_private.market_references;e beta_private.events;policy beta_private.region_policies;v numeric;checked timestamptz;
begin
 select * into s from beta_private.strategy_versions where id=p_strategy for share;select * into r from beta_private.market_references where id=p_reference for share;
 select * into p from beta_private.football_model_attempts where id=p_prediction for share;select * into e from beta_private.events where id=p.event_id for share;
 select * into policy from beta_private.region_policies where id=r.region_policy_id for share;
 perform beta_private.assert_football_prediction(p.id);perform beta_private.assert_current_market_reference(r.id);checked:=clock_timestamp();
 if not beta_private.scanner_strategy_allowed(s.id,p_purpose) or s.config->>'method' is distinct from 'football-independent-model' or p.model_version is distinct from s.football_model_version
 or p.code_commit is distinct from s.code_commit or s.code_commit is distinct from current_setting('docked.scanner_commit',true)
 or r.configuration is distinct from s.config->'marketReference' or r.selection is distinct from p_selection
 or not exists(select 1 from beta_private.markets m where m.id=r.market_id and m.event_id=p.event_id and m.rules->>'market'='football_1x2')
 or r.observed_at<p.created_at or checked-p.input_cutoff>(s.config->>'maxSportDataAgeSeconds')::integer*interval '1 second'
 or e.start_at<=checked+greatest(600,(s.config->>'safetySeconds')::integer)*interval '1 second'
 or not coalesce(policy.approved and not policy.preview_community_only and policy.effective_from<=checked and least(policy.effective_to,policy.review_at)>checked and(case when p_purpose='research' then 'market_data' else 'tips' end)=any(policy.features),false)
 then raise exception 'Fresh independent prediction, availability reference and current authority required';end if;
 v:=case when p_selection=e.participants->>0 then(p.probabilities->>'home')::numeric when p_selection='Draw' then(p.probabilities->>'draw')::numeric when p_selection=e.participants->>1 then(p.probabilities->>'away')::numeric else null end;
 if v is null or v<=0 or v>=1 then raise exception 'Selected boundary probability is not an eligible price comparison';end if;
 if r.decimal_price<ceil((1+(s.config->>'minEV')::numeric)/v*100)/100 or r.decimal_price<(s.config->>'minOdds')::numeric or r.decimal_price>(s.config->>'maxOdds')::numeric or v*r.decimal_price-1>(s.config->>'maxEV')::numeric then raise exception 'Independent probability comparison no longer qualifies';end if;
 return v;
end $$;
create function beta_private.football_candidate_check(n beta_private.scanner_candidates) returns beta_private.scanner_candidates language plpgsql set search_path='' as $$
declare run beta_private.scanner_runs;s beta_private.strategy_versions;p beta_private.football_model_attempts;r beta_private.market_references;e beta_private.events;v numeric;
begin
 select * into run from beta_private.scanner_runs where id=n.run_id for share;perform beta_private.scanner_assert_worker(run.job_id);
 select * into s from beta_private.strategy_versions where id=n.strategy_id for share;select * into p from beta_private.football_model_attempts where id=n.prediction_id for share;select * into r from beta_private.market_references where id=n.market_reference_id for share;select * into e from beta_private.events where id=n.event_id for share;
 v:=beta_private.assert_football_comparison(p.id,s.id,r.id,n.purpose,n.selection);perform beta_private.scanner_assert_worker(run.job_id);
 if run.status is distinct from 'RUNNING' or run.strategy_id is distinct from s.id or run.purpose is distinct from n.purpose or run.region_policy_id is distinct from n.region_policy_id
 or p.event_id is distinct from n.event_id or n.market_id is distinct from r.market_id or n.region_policy_id is distinct from r.region_policy_id
 or n.strategy_hash is distinct from s.config_hash or n.code_commit is distinct from s.code_commit or n.model_version is distinct from p.model_version
 or n.model_evidence->>'predictionId' is distinct from p.id::text or n.model_evidence->>'inputHash' is distinct from p.input_hash or n.model_evidence->'probabilities' is distinct from p.probabilities
 or n.probability is distinct from v or abs(n.fair_odds-1/v)>0.00000001 or n.required_ev is distinct from(s.config->>'minEV')::numeric or n.minimum_odds is distinct from ceil((1+n.required_ev)/v*100)/100 or abs(n.estimated_ev-(v*r.decimal_price-1))>0.00000001
 or n.scanned_at is distinct from r.observed_at or n.scanned_at>clock_timestamp() or n.expires_at<=clock_timestamp() or n.expires_at>least((r.reference->>'sourceAt')::timestamptz+least(180,(s.config->>'maxAgeSeconds')::int)*interval '1 second',e.start_at-greatest(600,(s.config->>'safetySeconds')::int)*interval '1 second',n.scanned_at+interval '120 seconds')
 or not(s.config->'competitions' ? e.competition_id) or not(s.config->'windowsSeconds' @> to_jsonb(n.window_seconds)) or p.window_seconds<>n.window_seconds
 or extract(epoch from(e.start_at-n.scanned_at))>n.window_seconds or extract(epoch from(e.start_at-n.scanned_at))<n.window_seconds-(s.config->>'windowToleranceSeconds')::int
 then raise exception 'Immutable independent candidate linkage required';end if;
 n.created_at:=clock_timestamp();return n;
end $$;
do $$declare definition text;begin
 select pg_get_functiondef('beta_private.scanner_candidate_guard()'::regprocedure) into definition;
 definition:=replace(definition,E'begin\n',E'begin\n if new.prediction_id is not null then return beta_private.football_candidate_check(new);end if;\n');execute definition;
end $$;

alter table beta_private.tip_publications drop constraint tip_publications_pricing_model_check;
alter table beta_private.tip_publications add constraint tip_publications_pricing_model_check check(pricing_model in('legacy_bookmaker_v1','market_reference_v1','football_independent_v1'));
alter table beta_private.tip_publications drop constraint publication_benchmark_version;
alter table beta_private.tip_publications add constraint publication_benchmark_version check((pricing_model='legacy_bookmaker_v1' and market_reference_id is null and prediction_id is null) or(pricing_model='market_reference_v1' and market_reference_id is not null and prediction_id is null) or(pricing_model='football_independent_v1' and market_reference_id is not null and prediction_id is not null));
drop trigger publication_guard on beta_private.tip_publications;
create trigger publication_guard before insert on beta_private.tip_publications for each row when(new.pricing_model<>'football_independent_v1') execute function beta_private.publication_guard();
create function beta_private.football_publication_guard() returns trigger language plpgsql set search_path='' as $$
declare c beta_private.candidate_decisions;s beta_private.strategy_versions;p beta_private.football_model_attempts;r beta_private.market_references;m beta_private.markets;v numeric;a uuid;
begin
 if new.evidence='live_published' and new.pricing_model<>'football_independent_v1' then raise exception 'Official record accepts new independent-model publications only';end if;
 if new.pricing_model<>'football_independent_v1' then return new;end if;
 a:=beta_private.scanner_assert_actor(false);if new.evidence='live_published' then perform pg_advisory_xact_lock(hashtext('official-football-record'));end if;select * into c from beta_private.candidate_decisions where id=new.candidate_id for update;
 select * into s from beta_private.strategy_versions where id=new.strategy_id for share;select * into p from beta_private.football_model_attempts where id=new.prediction_id for share;select * into r from beta_private.market_references where id=new.market_reference_id for share;select * into m from beta_private.markets where id=r.market_id for share;
 v:=beta_private.assert_football_comparison(p.id,s.id,r.id,case when new.evidence='live_published' then 'live' else 'paper' end,new.selection);
 perform beta_private.scanner_assert_actor(false);
 if new.evidence not in('live_published','forward_paper') or new.approved_by is distinct from a or c.status is distinct from 'review' or c.event_id is distinct from p.event_id or c.strategy_id is distinct from s.id or new.event_id is distinct from p.event_id
 or c.payload->>'predictionId' is distinct from p.id::text or c.payload->>'referenceId' is distinct from r.id::text
 or new.config_hash is distinct from s.config_hash or new.region_policy_id is distinct from r.region_policy_id or new.market_rules is distinct from m.rules
 or new.probability is distinct from v or new.odds is distinct from r.decimal_price or new.minimum_odds is distinct from ceil((1+(s.config->>'minEV')::numeric)/v*100)/100 or abs(new.estimated_ev-(v*r.decimal_price-1))>0.00000001 or new.benchmark_stake<>1
 or new.publication_payload->'reference' is distinct from r.reference or new.publication_payload#>>'{modelEvidence,predictionId}' is distinct from p.id::text
 or not coalesce((select enabled from beta_private.feature_flags where key=case when new.evidence='live_published' then 'publication' else 'forward_paper' end),false)
 then raise exception 'Canonical prospective independent publication required';end if;
 new.published_at:=clock_timestamp();return new;
end $$;
create trigger aa_football_publication_guard before insert on beta_private.tip_publications for each row execute function beta_private.football_publication_guard();

create function beta_private.official_record_insert_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if pg_trigger_depth()<2 or current_setting('docked.official_publication',true) is distinct from(case when tg_table_name='official_record_boundary' then to_jsonb(new)->>'first_tip_id' else to_jsonb(new)->>'tip_id' end) then raise exception 'Official record can only originate at canonical live insertion';end if;
 return new;
end $$;
create trigger official_record_insert_guard before insert on beta_private.official_record_boundary for each row execute function beta_private.official_record_insert_guard();
create trigger official_record_insert_guard before insert on beta_private.official_docked_publications for each row execute function beta_private.official_record_insert_guard();
create function beta_private.record_official_football() returns trigger language plpgsql set search_path='' as $$
declare version text;
begin
 if new.evidence='live_published' then
  perform pg_advisory_xact_lock(hashtext('official-football-record'));
  select model_version into version from beta_private.football_model_attempts where id=new.prediction_id;
  if version is null or new.pricing_model<>'football_independent_v1' then raise exception 'Independent publication lineage required';end if;
  perform set_config('docked.official_publication',new.id::text,true);
  insert into beta_private.official_record_boundary(singleton,first_tip_id,started_at,actor) values(true,new.id,new.published_at,new.approved_by) on conflict do nothing;
  insert into beta_private.official_docked_publications(tip_id,event_id,prediction_id,model_version,published_at) values(new.id,new.event_id,new.prediction_id,version,new.published_at);
  perform set_config('docked.official_publication','',true);
 end if;return new;
end $$;
create trigger record_official_football after insert on beta_private.tip_publications for each row execute function beta_private.record_official_football();
create function beta_private.publish_football_candidate(p_id uuid,p_reference uuid default null) returns uuid language plpgsql set search_path='' as $$
declare c beta_private.scanner_candidates;s beta_private.strategy_versions;p beta_private.football_model_attempts;r beta_private.market_references;m beta_private.markets;a uuid;v numeric;decision uuid;publication uuid;purpose beta_public.evidence_type;
begin
 a:=beta_private.scanner_assert_actor(false);select * into c from beta_private.scanner_candidates where id=p_id for update;
 if c.prediction_id is null or c.purpose not in('paper','live') or c.expires_at<=clock_timestamp() or exists(select 1 from beta_private.scanner_reviews where candidate_id=c.id and status in('APPROVED','REJECTED','EXPIRED','INVALIDATED')) then raise exception 'Unexpired independent publication candidate required';end if;
 select * into s from beta_private.strategy_versions where id=c.strategy_id for share;select * into p from beta_private.football_model_attempts where id=c.prediction_id for share;select * into r from beta_private.market_references where id=coalesce(p_reference,c.market_reference_id) for share;select * into m from beta_private.markets where id=r.market_id for share;
 v:=beta_private.assert_football_comparison(p.id,s.id,r.id,c.purpose,c.selection);
 if r.market_id is distinct from c.market_id or r.region_policy_id is distinct from c.region_policy_id or s.config_hash is distinct from c.strategy_hash then raise exception 'Candidate cannot change its event, region or strategy';end if;
 purpose:=case when c.purpose='live' then 'live_published'::beta_public.evidence_type else 'forward_paper'::beta_public.evidence_type end;
 insert into beta_private.candidate_decisions(event_id,strategy_id,decision_at,window_seconds,payload,rejection_reasons,status) values(c.event_id,c.strategy_id,clock_timestamp(),c.window_seconds,jsonb_build_object('predictionId',p.id,'referenceId',r.id,'scannerCandidateId',c.id),'{}','review') returning id into decision;
 insert into beta_private.tip_publications(candidate_id,event_id,strategy_id,evidence,selection,market_rules,probability,odds,minimum_odds,estimated_ev,config_hash,sources,publication_payload,approved_by,region_policy_id,pricing_model,market_reference_id,prediction_id)
 values(decision,c.event_id,s.id,purpose,c.selection,m.rules,v,r.decimal_price,ceil((1+(s.config->>'minEV')::numeric)/v*100)/100,v*r.decimal_price-1,s.config_hash,'[]',jsonb_build_object('pricingModel','football_independent_v1','marketId',m.id,'reference',r.reference,'referenceConfig',s.config->'marketReference','fairOdds',1/v,'modelEvidence',jsonb_build_object('id',p.id,'predictionId',p.id,'modelVersion',p.model_version,'configHash',p.config_hash,'inputHash',p.input_hash,'dataCutoff',p.input_cutoff,'asOfTime',p.as_of_time,'calculatedAt',p.calculated_at,'codeCommit',p.code_commit,'probabilities',p.probabilities),'offer',jsonb_build_object('bookmaker','Market reference','sourceAt',r.reference->>'sourceAt')),a,r.region_policy_id,'football_independent_v1',r.id,p.id) returning id into publication;
 update beta_private.candidate_decisions set status='published' where id=decision;return publication;
end $$;

-- Independent candidate review preserves the complete retained vector and cannot substitute a price-derived probability.
create function beta_private.football_review_check(n beta_private.scanner_reviews) returns beta_private.scanner_reviews language plpgsql set search_path='' as $$
declare c beta_private.scanner_candidates;r beta_private.market_references;a uuid;v numeric;
begin
 select * into c from beta_private.scanner_candidates where id=n.candidate_id for update;
 if exists(select 1 from beta_private.scanner_reviews where candidate_id=c.id and status in('APPROVED','REJECTED','EXPIRED','INVALIDATED')) then raise exception 'Candidate is final';end if;
 if n.status in('EXPIRED','INVALIDATED') and current_setting('docked.scanner_scheduler',true)='true' then n.actor:=null;else a:=beta_private.scanner_assert_actor(false);if n.actor is distinct from a then raise exception 'Review actor mismatch';end if;end if;
 if n.status='APPROVED' then
  if c.expires_at<=clock_timestamp() then raise exception 'Candidate expired';end if;
  select * into r from beta_private.market_references where id=n.market_reference_id for share;v:=beta_private.assert_football_comparison(c.prediction_id,c.strategy_id,r.id,c.purpose,c.selection);perform beta_private.scanner_assert_actor(false);
  if r.market_id is distinct from c.market_id or r.region_policy_id is distinct from c.region_policy_id then raise exception 'Candidate reference mismatch';end if;
  if c.purpose='research' and n.publication_id is not null then raise exception 'Research cannot publish';end if;
  if c.purpose<>'research' and not exists(select 1 from beta_private.tip_publications t where t.id=n.publication_id and t.prediction_id=c.prediction_id and t.market_reference_id=r.id and t.approved_by=a and t.strategy_id=c.strategy_id and t.evidence::text=case when c.purpose='live' then 'live_published' else 'forward_paper' end) then raise exception 'Canonical publication required';end if;
  n.evidence:=jsonb_build_object('predictionId',c.prediction_id,'referenceId',r.id,'probability',v,'purpose',c.purpose);
 elsif n.publication_id is not null then raise exception 'Only approval can publish';end if;
 n.created_at:=clock_timestamp();insert into beta_private.audit_events(actor,action,subject,details) values(coalesce(n.actor::text,'scanner'),'football_candidate_review',c.id::text,jsonb_build_object('status',n.status,'reason',n.reason));return n;
end $$;
do $$declare definition text;begin
 select pg_get_functiondef('beta_private.scanner_review_guard()'::regprocedure) into definition;
 definition:=replace(definition,E'begin\n',E'begin\n if exists(select 1 from beta_private.scanner_candidates where id=new.candidate_id and prediction_id is not null) then return beta_private.football_review_check(new);end if;\n');execute definition;
end $$;
-- Fixed private privileges; this migration never broadens browser or community runtime permissions.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='beta_private' and (p.proname like 'football_%' or p.proname like '%_football_%' or p.proname in('official_record_insert_guard','legacy_scanner_strategy_allowed','record_official_football')) loop execute format('revoke all on function %s from public,anon,authenticated,docked_beta_app',f.signature);end loop;end $$;

grant select on beta_private.official_docked_publications,beta_private.official_record_boundary to docked_beta_app;
create policy runtime_official_read on beta_private.official_docked_publications for select to docked_beta_app using(true);
create policy runtime_official_boundary_read on beta_private.official_record_boundary for select to docked_beta_app using(true);
grant select(model_version,to_state,created_at,id) on beta_private.football_model_transitions to docked_beta_app;
create policy runtime_model_changelog_read on beta_private.football_model_transitions for select to docked_beta_app using(true);

-- Reuse existing terminal/no-reactivation movement logic and add independent authority checks.
do $$declare definition text;begin
 select pg_get_functiondef('beta_private.reference_movement_guard()'::regprocedure) into definition;
 definition:=replace(definition,'p.pricing_model<>''market_reference_v1''','p.pricing_model not in(''market_reference_v1'',''football_independent_v1'')');
 definition:=replace(definition,'new.observed_at:=clock_timestamp();', $fragment$
 if p.pricing_model='football_independent_v1' and new.status in('ACTIVE','PRICE BELOW MINIMUM') then
  perform beta_private.assert_football_prediction(p.prediction_id);
  if not beta_private.scanner_strategy_allowed(p.strategy_id,case when p.evidence='live_published' then 'live' else 'paper' end)
  or not exists(select 1 from beta_private.strategy_versions s join beta_private.football_model_attempts prediction on prediction.id=p.prediction_id
   join beta_private.region_policies region on region.id=p.region_policy_id where s.id=p.strategy_id
   and s.code_commit=current_setting('docked.scanner_commit',true) and s.config_hash=p.config_hash
   and clock_timestamp()-prediction.input_cutoff<=(s.config->>'maxSportDataAgeSeconds')::integer*interval '1 second'
   and region.approved and not region.preview_community_only and region.effective_from<=clock_timestamp() and least(region.effective_to,region.review_at)>clock_timestamp() and 'tips'=any(region.features)
   and (new.status<>'ACTIVE' or(ref.decimal_price<=(s.config->>'maxOdds')::numeric and p.probability*ref.decimal_price-1<=(s.config->>'maxEV')::numeric)))
  then raise exception 'Independent publication authority withdrawn';end if;
 end if;
 new.observed_at:=clock_timestamp();$fragment$);
 execute definition;
end $$;


-- SOURCE 20261004023247_phase5c_governed_match_research.sql sha256=8eac0a97fce84dfb34c1b00f7ba5f6270857433a8f536155cbfbd870eca75f5b
-- Governed research is separate from models, betting ledgers and provider-price authority.
create table beta_private.research_source_versions(
 id uuid primary key default gen_random_uuid(),source_key text not null,version text not null,
 revision bigint generated always as identity,configuration jsonb not null,config_hash text not null check(config_hash~'^[a-f0-9]{64}$'),
 supersedes uuid references beta_private.research_source_versions,created_by uuid not null,reason text not null,
 created_at timestamptz not null default clock_timestamp(),unique(source_key,version)
);
create table beta_private.research_policies(
 id uuid primary key default gen_random_uuid(),version text not null unique,configuration jsonb not null,config_hash text not null,
 created_by uuid not null,reason text not null,created_at timestamptz not null default clock_timestamp()
);
create table beta_private.research_feature_versions(
 id uuid primary key default gen_random_uuid(),feature_key text not null,version text not null,model_version text references beta_private.football_model_versions,
 configuration jsonb not null,config_hash text not null,supersedes uuid references beta_private.research_feature_versions,
 created_by uuid not null,reason text not null,created_at timestamptz not null default clock_timestamp(),unique(feature_key,version)
);
create table beta_private.research_facts(
 id text primary key,event_id text not null references beta_private.events,source_review_id uuid not null references beta_private.research_source_versions,
 source_item_id text not null,source_revision text not null,fact_type text not null,team_id text,player_id text,
 fact_key text not null,fact_hash text not null check(fact_hash~'^[a-f0-9]{64}$'),
 source_published_at timestamptz,source_observed_at timestamptz not null,ingested_at timestamptz not null,effective_at timestamptz not null,expires_at timestamptz not null,
 confidence text not null,reliability text not null,evidence_url text not null,evidence_hash text not null,
 record_state text not null check(record_state in('ASSERTED','WITHDRAWN')),supersedes_id text unique references beta_private.research_facts,
 created_by uuid,job_id uuid references beta_private.job_runs,created_at timestamptz not null default clock_timestamp(),
 unique(source_review_id,source_item_id,source_revision,fact_key)
);
create index research_facts_event_clock on beta_private.research_facts(event_id,ingested_at,id);
create table beta_private.research_fact_payloads(
 fact_id text primary key references beta_private.research_facts,payload jsonb not null,retain_until timestamptz not null
);
create table beta_private.research_match_snapshots(
 id uuid primary key default gen_random_uuid(),event_id text not null references beta_private.events,policy_id uuid not null references beta_private.research_policies,
 event_start_at timestamptz not null,event_participants jsonb not null,as_of_time timestamptz not null,
 fact_ids text[] not null,feature_ids uuid[] not null default '{}',manifest jsonb not null,manifest_hash text not null,
 research_hash text not null,created_by uuid,job_id uuid references beta_private.job_runs,created_at timestamptz not null default clock_timestamp(),
 unique(event_id,policy_id,research_hash)
);
create table beta_private.research_content(
 id uuid primary key default gen_random_uuid(),snapshot_id uuid not null references beta_private.research_match_snapshots,event_id text not null references beta_private.events,
 content_type text not null check(content_type in('DOCKED_RESEARCH','MATCH_UPDATE','LINEUP_UPDATE')),
 headline text not null,fact_ids text[] not null,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),
 unique(snapshot_id,content_type)
);
create table beta_private.research_content_reviews(
 id uuid primary key default gen_random_uuid(),content_id uuid not null references beta_private.research_content,
 action text not null check(action in('PUBLISH','WITHDRAW')),actor uuid not null,reason text not null,created_at timestamptz not null default clock_timestamp()
);
create table beta_private.research_schedules(
 id uuid primary key default gen_random_uuid(),source_review_id uuid not null references beta_private.research_source_versions,
 policy_id uuid not null references beta_private.research_policies,enabled boolean not null default false,
 next_run timestamptz,last_success timestamptz,last_failure timestamptz,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),
 unique(source_review_id,policy_id)
);
create table beta_private.research_fetch_requests(
 id uuid primary key default gen_random_uuid(),source_review_id uuid not null references beta_private.research_source_versions,
 job_id uuid not null references beta_private.job_runs,started_at timestamptz not null default clock_timestamp(),completed_at timestamptz,
 status text not null default 'RESERVED' check(status in('RESERVED','SUCCESS','NOT_MODIFIED','FAILED','BLOCKED')),
 http_status integer check(http_status between 100 and 599),response_hash text,etag text,last_modified text,
 measured jsonb,error_code text,retry_after timestamptz,credits_reserved integer not null default 0 check(credits_reserved=0)
);
create index research_requests_source_time on beta_private.research_fetch_requests(source_review_id,started_at desc);
create table beta_private.research_source_health(
 source_key text primary key,last_success timestamptz,last_failure timestamptz,error_code text,
 etag text,last_modified text,circuit_until timestamptz,updated_at timestamptz not null default clock_timestamp()
);
create table beta_private.research_dataset_snapshots(
 id uuid primary key default gen_random_uuid(),source_review_id uuid not null references beta_private.research_source_versions,
 request_id uuid not null unique references beta_private.research_fetch_requests,observed_at timestamptz not null,
 raw_hash text not null check(raw_hash~'^[a-f0-9]{64}$'),payload_hash text not null check(payload_hash~'^[a-f0-9]{64}$'),
 record_count integer not null check(record_count between 1 and 1000),quality jsonb not null,
 created_at timestamptz not null default clock_timestamp()
);
create table beta_private.research_dataset_payloads(snapshot_id uuid primary key references beta_private.research_dataset_snapshots,payload jsonb not null,retain_until timestamptz not null);
create table beta_private.research_recalculations(
 id uuid primary key default gen_random_uuid(),snapshot_id uuid not null references beta_private.research_match_snapshots,
 model_version text not null references beta_private.football_model_versions,prior_prediction_id uuid references beta_private.football_model_attempts,
 new_prediction_id uuid references beta_private.football_model_attempts,status text not null check(status in('DISPLAY_ONLY','NOT_CONFIGURED','WITHHELD')),
 trigger_fact_ids text[] not null,feature_ids uuid[] not null,reason text not null,actor uuid not null,
 created_at timestamptz not null default clock_timestamp(),unique(snapshot_id,model_version)
);
insert into beta_private.feature_flags(key,enabled,reason)values('research_engine',false,'Research automation needs reviewed sources, explicit schedules and runtime activation')on conflict do nothing;
alter table beta_private.social_notification_preferences add column research_updates boolean not null default false,add column lineup_updates boolean not null default false,add column team_updates boolean not null default false;

create function beta_private.research_keys_only(p jsonb,allowed text[]) returns boolean language sql immutable set search_path='' as $$
 select jsonb_typeof(p)='object' and not exists(select 1 from jsonb_object_keys(p) k where not k=any(allowed))
$$;
create function beta_private.research_hash(p jsonb) returns text language sql immutable set search_path='' as $$
 select encode(sha256(convert_to(beta_private.phase5_canonical_json(p),'UTF8')),'hex')
$$;
create function beta_private.research_public_url(p text)returns boolean language sql immutable set search_path='' as $$
 select coalesce(p~'^https://[a-zA-Z0-9.-]+(/[A-Za-z0-9_./%:@+-]*)?$' and p!~'[?#]' and p!~'^https://([0-9.]+|localhost|[^/]*[.]local)(/|$)' and length(p)<=2000,false)
$$;
create function beta_private.research_lock_sources(p_event text)returns void language plpgsql set search_path='' as $$
declare r record;begin
 for r in select distinct s.source_key from beta_private.research_facts f join beta_private.research_source_versions s on s.id=f.source_review_id where f.event_id=p_event order by s.source_key loop
 perform pg_advisory_xact_lock(hashtext('research-source:'||r.source_key));
 end loop;
end $$;
create function beta_private.research_actor(p_mode text default 'FACT') returns uuid language plpgsql set search_path='' as $$
declare actor uuid:=beta_private.runtime_uid();begin
 if actor is null or not beta_private.active_member_session() or coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb->>'aal' is distinct from 'aal2'
 or not exists(select 1 from beta_private.roles r where r.user_id=actor and(r.role in('owner','admin') or(p_mode='FACT' and r.role='analyst')or(p_mode='CONTENT' and r.role='editor')))
 or not exists(select 1 from beta_public.profiles p where p.id=actor and p.disabled_at is null)
 or not exists(select 1 from beta_private.runtime_auth_users u where u.id=actor and coalesce(u.banned_until,'-infinity'::timestamptz)<=clock_timestamp())
 then raise exception 'Current research staff MFA required';end if;return actor;
end $$;
create function beta_private.research_worker(p_job uuid) returns void language plpgsql set search_path='' as $$
declare j beta_private.job_runs;sched beta_private.research_schedules;e beta_private.events;begin
 select * into j from beta_private.job_runs where id=p_job for share;
 if j.kind is distinct from 'research-update' or j.state is distinct from 'leased' or j.lease_token::text is distinct from current_setting('docked.research_lease',true)
 or j.id::text is distinct from current_setting('docked.research_job',true) or j.lease_until<=clock_timestamp() then raise exception 'Current research worker lease required';end if;
 if j.payload->>'origin'='manual' then
  if not exists(select 1 from beta_private.roles r join beta_public.profiles p on p.id=r.user_id join beta_private.runtime_auth_users u on u.id=p.id join beta_private.runtime_auth_sessions s on s.user_id=u.id where r.user_id::text=j.payload->>'actorId' and s.id::text=j.payload->>'actorSessionId' and(s.not_after is null or s.not_after>clock_timestamp())and r.role in('owner','admin','analyst')and p.disabled_at is null and coalesce(u.banned_until,'-infinity'::timestamptz)<=clock_timestamp())then raise exception 'Research initiator authority withdrawn';end if;
 elsif j.payload->>'origin' is distinct from 'scheduled' then raise exception 'Research origin required';end if;
 select * into sched from beta_private.research_schedules where id=(j.payload->>'scheduleId')::uuid for share;
 select * into e from beta_private.events where id=j.payload->>'eventId' for share;
 if sched.id is null or e.id is null or e.competition_id is distinct from 'soccer_epl' or e.status is distinct from 'scheduled' or e.start_at<=clock_timestamp() or e.start_at is distinct from(j.payload->>'startAt')::timestamptz or beta_private.research_hash(e.participants)is distinct from j.payload->>'participantHash' or(j.payload->>'origin'='scheduled' and not sched.enabled) then raise exception 'Current scheduled research context required';end if;
 if not exists(select 1 from beta_private.feature_flags where key='research_engine' and enabled)then raise exception 'Research automation disabled';end if;
end $$;
create function beta_private.research_source_allowed(p_id uuid,p_purpose text,p_jurisdiction text,p_at timestamptz default clock_timestamp())returns boolean language sql volatile set search_path='' as $$
 select coalesce((select s.id=(select x.id from beta_private.research_source_versions x where x.source_key=s.source_key order by revision desc limit 1)
 and s.configuration->>'rightsState' in('APPROVED_AUTOMATED','APPROVED_MANUAL_ONLY')
 and(s.configuration->>'reviewedAt')::timestamptz<=p_at and(s.configuration->>'effectiveFrom')::timestamptz<=p_at
 and least((s.configuration->>'reviewDueAt')::timestamptz,(s.configuration->>'effectiveTo')::timestamptz)>p_at
 and s.configuration->'jurisdictions'?p_jurisdiction and s.configuration->>'commercialUse'='ALLOWED'
 and s.configuration#>>'{storage,permission}'='ALLOWED' and s.configuration#>>'{storage,immutableEvidenceAllowed}'='true'
 and case p_purpose when 'RETAIN' then true when 'DISPLAY' then s.configuration->>'publicDisplay'='ALLOWED' when 'MODEL' then s.configuration->>'modelUse'='ALLOWED' and s.configuration->>'derivedUse'='ALLOWED' and s.configuration->>'reliability'<>'TIER_4_UNCONFIRMED'
 when 'AUTOMATED_FETCH' then s.configuration->>'rightsState'='APPROVED_AUTOMATED' and s.configuration->>'automation'='ALLOWED' and s.configuration->>'robots' in('ALLOWED','NOT_APPLICABLE') and s.configuration->>'accessMethod' in('API','FEED','DATASET') and(s.configuration#>>'{etiquette,minimumIntervalSeconds}')::integer>0 and(s.configuration#>>'{etiquette,maximumRequestsPerDay}')::integer>0 else false end
 from beta_private.research_source_versions s where s.id=p_id),false)
$$;
create function beta_private.research_governance_guard()returns trigger language plpgsql set search_path='' as $$
declare a uuid;c jsonb;prior uuid;begin
 if tg_op<>'INSERT' then raise exception 'Versioned research governance is append-only';end if;
 a:=beta_private.research_actor('MANAGE');c:=new.configuration;
 if new.created_by is distinct from a or length(btrim(new.reason))<12 or new.config_hash is distinct from beta_private.research_hash(c) then raise exception 'Audited canonical research configuration required';end if;
 if tg_table_name='research_source_versions' then
  perform pg_advisory_xact_lock(hashtext('research-source:'||new.source_key));select id into prior from beta_private.research_source_versions where source_key=new.source_key order by revision desc limit 1;
  if new.supersedes is distinct from prior or new.source_key is distinct from c->>'sourceId' or new.version is distinct from c->>'version'
  or c->>'schemaVersion' is distinct from 'research-source-v1' or not beta_private.research_keys_only(c,array['schemaVersion','sourceId','version','name','domain','category','accessMethod','endpoint','rightsState','commercialUse','publicDisplay','storage','derivedUse','modelUse','automation','robots','etiquette','attribution','dataTypes','reliability','jurisdictions','reviewedAt','reviewDueAt','effectiveFrom','effectiveTo','evidenceUrls','notes'])
  or not coalesce(c->>'rightsState' in('APPROVED_AUTOMATED','APPROVED_MANUAL_ONLY','PERMISSION_REQUIRED','REVIEW_REQUIRED','PROHIBITED') and c->>'endpoint' like 'https://%' and length(c->>'name') between 1 and 200 and jsonb_array_length(c->'evidenceUrls')between 1 and 20 and jsonb_array_length(c->'jurisdictions')>0 and jsonb_array_length(c->'dataTypes')>0
  and(c->>'reviewedAt')::timestamptz<=clock_timestamp() and(c->>'reviewedAt')::timestamptz>=clock_timestamp()-interval '5 minutes'
  and(c->>'reviewDueAt')::timestamptz>(c->>'reviewedAt')::timestamptz and(c->>'effectiveTo')::timestamptz>(c->>'effectiveFrom')::timestamptz,false)
  then raise exception 'Current complete source rights review required';end if;
  if not coalesce(c->>'sourceId'~'^[A-Za-z0-9_.:-]{1,160}$' and c->>'version'~'^[A-Za-z0-9_.:-]{1,160}$' and c->>'publicDisplay' in('ALLOWED','UNKNOWN','DENIED')and c->>'commercialUse' in('ALLOWED','UNKNOWN','DENIED')and c->>'derivedUse' in('ALLOWED','UNKNOWN','DENIED')and c->>'modelUse' in('ALLOWED','UNKNOWN','DENIED')and c->>'automation' in('ALLOWED','UNKNOWN','DENIED')and c#>>'{storage,permission}' in('ALLOWED','UNKNOWN','DENIED')and jsonb_typeof(c#>'{storage,immutableEvidenceAllowed}')='boolean' and(c#>>'{storage,permission}'<>'ALLOWED' or(c#>>'{storage,maxDays}')::integer between 1 and 36500)and c->>'category' in('OFFICIAL','STRUCTURED_DATA','NEWS','WEATHER','DERIVED')and c->>'accessMethod' in('API','FEED','PAGE','MANUAL','DATASET')and c->>'robots' in('ALLOWED','DISALLOWED','UNKNOWN','NOT_APPLICABLE')and c->>'reliability' in('TIER_1_CONFIRMED_OFFICIAL','TIER_2_AUTHORISED_STRUCTURED','TIER_3_RELIABLE_REPORTED','TIER_4_UNCONFIRMED')and beta_private.research_public_url(c->>'endpoint')and split_part(split_part(c->>'endpoint','://',2),'/',1)=c->>'domain' and beta_private.research_public_url(c#>>'{attribution,url}')and length(c#>>'{attribution,label}')between 1 and 200,false)
  or exists(select 1 from jsonb_array_elements_text(c->'evidenceUrls')u where not beta_private.research_public_url(u))
  or exists(select 1 from jsonb_array_elements_text(c->'dataTypes')v where v not in('PLAYER_INJURY','PLAYER_SUSPENSION','PLAYER_RETURN','EXPECTED_LINEUP','CONFIRMED_LINEUP','MANAGER_CHANGE','TEAM_FORM_UPDATE','PLAYER_FORM_UPDATE','MATCH_RESULT','TEAM_STAT_UPDATE','PLAYER_STAT_UPDATE','REST_ADVANTAGE','SCHEDULE_CONGESTION','WEATHER_UPDATE','VENUE_CHANGE','MATCH_POSTPONED','MATCH_CANCELLED'))then raise exception 'Strict research rights and public provenance required';end if;
 elsif tg_table_name='research_policies' then
  if new.version is distinct from c->>'version' or not beta_private.research_keys_only(c,array['version','jurisdiction','requiredFactTypes','maxFactAgeSeconds','windowsSeconds'])
  or not coalesce(jsonb_array_length(c->'requiredFactTypes')>0 and(c->>'maxFactAgeSeconds')::integer between 1 and 31536000 and jsonb_array_length(c->'windowsSeconds')between 1 and 12 and length(c->>'jurisdiction')>0,false)
  or exists(select 1 from jsonb_array_elements_text(c->'windowsSeconds')v where v::integer<60 or v::integer>604800)
  then raise exception 'Explicit research completeness and scheduling policy required';end if;
 else
  perform pg_advisory_xact_lock(hashtext('research-feature:'||new.feature_key));select id into prior from beta_private.research_feature_versions where feature_key=new.feature_key order by created_at desc,id desc limit 1;
  if new.supersedes is distinct from prior or new.feature_key is distinct from c->>'featureId' or new.version is distinct from c->>'version' then raise exception 'New immutable feature version required';end if;
  if not beta_private.research_keys_only(c,array['schemaVersion','featureId','version','state','inputKind','factTypes','transformId','transformVersion','modelVersion','modelConfigHash','causalRationale','limitations','acceptedConfidence','maxAgeSeconds','trainingCutoff','reviewedAt','effectiveFrom','effectiveTo','reviewReference'])
  or not coalesce(c->>'schemaVersion'='research-feature-v1' and c->>'inputKind'='STRUCTURED_SPORTING_FACT' and c->>'state' in('DISPLAY_ONLY','MODEL_ELIGIBLE','MODEL_ACTIVE')and c->>'transformId'~'^[A-Za-z0-9_.:-]{1,160}$' and c->>'transformVersion'~'^[A-Za-z0-9_.:-]{1,160}$'and jsonb_array_length(c->'factTypes')>0 and jsonb_array_length(c->'acceptedConfidence')>0 and length(c->>'causalRationale')between 20 and 2000 and length(c->>'limitations')between 1 and 2000 and(c->>'maxAgeSeconds')::integer>0 and(c->>'reviewedAt')::timestamptz<=clock_timestamp()and(c->>'effectiveTo')::timestamptz>(c->>'effectiveFrom')::timestamptz and(c->>'trainingCutoff' is null or(c->>'trainingCutoff')::timestamptz<=(c->>'reviewedAt')::timestamptz)and length(c->>'reviewReference')>0,false)
  or new.model_version is distinct from c->>'modelVersion' or exists(select 1 from jsonb_array_elements_text(c->'acceptedConfidence')v where v not in('CONFIRMED','REPORTED'))then raise exception 'Strict immutable sporting feature definition required';end if;
  if c->>'state'<>'DISPLAY_ONLY' and not exists(select 1 from beta_private.football_model_versions v where v.id=new.model_version and v.config_hash=c->>'modelConfigHash' and c->>'trainingCutoff' is not null)then raise exception 'Feature requires exact model configuration and training cutoff';end if;
  if c->>'state'='MODEL_ACTIVE' and not exists(select 1 from beta_private.football_model_versions v where v.id=new.model_version and v.configuration->'activeResearchFeatureHashes'?beta_private.research_hash(jsonb_build_object('schemaVersion','research-feature-definition-v1','featureId',c->'featureId','inputKind',c->'inputKind','factTypes',(select jsonb_agg(x order by x collate "C")from jsonb_array_elements_text(c->'factTypes')x),'transformId',c->'transformId','transformVersion',c->'transformVersion','causalRationale',c->'causalRationale','limitations',c->'limitations','acceptedConfidence',(select jsonb_agg(x order by x collate "C")from jsonb_array_elements_text(c->'acceptedConfidence')x),'maxAgeSeconds',c->'maxAgeSeconds','trainingCutoff',c->'trainingCutoff')))then raise exception 'A new model version must freeze active research feature definitions';end if;
 end if;
 perform beta_private.research_actor('MANAGE');new.created_at:=clock_timestamp();insert into beta_private.audit_events(actor,action,subject,details)values(a::text,'research_governance',tg_table_name,jsonb_build_object('id',new.id,'hash',new.config_hash,'reason',new.reason));return new;
end $$;
create trigger research_source_guard before insert or update or delete on beta_private.research_source_versions for each row execute function beta_private.research_governance_guard();
create trigger research_policy_guard before insert or update or delete on beta_private.research_policies for each row execute function beta_private.research_governance_guard();
create trigger research_feature_guard before insert or update or delete on beta_private.research_feature_versions for each row execute function beta_private.research_governance_guard();

create function beta_private.research_fact_guard()returns trigger language plpgsql set search_path='' as $$
declare s beta_private.research_source_versions;p beta_private.research_facts;checked timestamptz;jur text;begin
 if tg_op<>'INSERT' then raise exception 'Research fact/correction ledger is immutable';end if;
 if new.job_id is null then if new.created_by is distinct from beta_private.research_actor('FACT')then raise exception 'Fact actor mismatch';end if;else perform beta_private.research_worker(new.job_id);end if;
 perform id from beta_private.events where id=new.event_id for update;
 select * into s from beta_private.research_source_versions where id=new.source_review_id for share;
 perform pg_advisory_xact_lock(hashtext('research-source:'||s.source_key));checked:=clock_timestamp();jur:=s.configuration->'jurisdictions'->>0;
 if not beta_private.research_source_allowed(s.id,case when new.job_id is null then 'RETAIN' else 'AUTOMATED_FETCH' end,jur,checked)
 or not coalesce(s.configuration->'dataTypes'?new.fact_type and new.reliability=s.configuration->>'reliability'
 and new.confidence in('CONFIRMED','REPORTED','RUMOUR','MODEL_DERIVED') and new.ingested_at<=checked and new.ingested_at>=checked-interval '5 minutes' and new.source_observed_at<=new.ingested_at and(new.source_published_at is null or new.source_published_at<=new.source_observed_at)
 and(s.configuration->>'reviewedAt')::timestamptz<=new.ingested_at and(s.configuration->>'effectiveFrom')::timestamptz<=new.ingested_at and new.expires_at>new.effective_at and new.expires_at>checked and new.expires_at<=least((s.configuration->>'effectiveTo')::timestamptz,new.ingested_at+(s.configuration#>>'{storage,maxDays}')::integer*interval '1 day')
 and new.evidence_url like 'https://%' and new.evidence_hash~'^[a-f0-9]{64}$' and new.fact_key~'^[a-f0-9]{64}$',false)
 or(new.reliability='TIER_4_UNCONFIRMED' and new.confidence='CONFIRMED') then raise exception 'Current source rights, provenance and bounded retention required';end if;
 if new.supersedes_id is not null then select * into p from beta_private.research_facts where id=new.supersedes_id for share;
  if p.id is null or p.event_id<>new.event_id or p.fact_key<>new.fact_key or p.ingested_at>=new.ingested_at or not exists(select 1 from beta_private.research_source_versions x where x.id=p.source_review_id and x.source_key=s.source_key)then raise exception 'Matching earlier correction predecessor required';end if;
 elsif new.record_state='WITHDRAWN' then raise exception 'Withdrawal requires prior fact';end if;
 if new.fact_type='MATCH_RESULT' and not exists(select 1 from beta_private.events e where e.id=new.event_id and e.start_at<coalesce(new.source_published_at,new.source_observed_at))then raise exception 'Prospective target result cannot precede kickoff';end if;
 if new.job_id is null then perform beta_private.research_actor('FACT');else perform beta_private.research_worker(new.job_id);end if;new.created_at:=clock_timestamp();return new;
end $$;
create trigger research_fact_guard before insert or update or delete on beta_private.research_facts for each row execute function beta_private.research_fact_guard();

create function beta_private.research_payload_guard()returns trigger language plpgsql set search_path='' as $$
declare f beta_private.research_facts;s beta_private.research_source_versions;p jsonb;v jsonb;keys text[];begin
 if tg_op='UPDATE' then raise exception 'Research fact payload is immutable';end if;
 if tg_op='DELETE' then if old.retain_until>clock_timestamp()then raise exception 'Unexpired research evidence retained';end if;return old;end if;
 select * into f from beta_private.research_facts where id=new.fact_id for share;select * into s from beta_private.research_source_versions where id=f.source_review_id for share;p:=new.payload;v:=p->'value';
 if f.job_id is null then perform beta_private.research_actor('FACT');else perform beta_private.research_worker(f.job_id);end if;
 if beta_private.research_hash(p) is distinct from f.fact_hash or p->>'id' is distinct from f.id or p->>'eventId' is distinct from f.event_id or p->>'sourceId' is distinct from s.source_key or p->>'sourceVersion' is distinct from s.version or p->>'type' is distinct from f.fact_type
 or(p->>'ingestedAt')::timestamptz is distinct from f.ingested_at or(p->>'sourcePublishedAt')::timestamptz is distinct from f.source_published_at or(p->>'sourceObservedAt')::timestamptz is distinct from f.source_observed_at or(p->>'effectiveAt')::timestamptz is distinct from f.effective_at or(p->>'expiresAt')::timestamptz is distinct from f.expires_at
 or p->>'confidence' is distinct from f.confidence or p->>'reliability' is distinct from f.reliability or p->>'recordState' is distinct from f.record_state or p->>'supersedesId' is distinct from f.supersedes_id
 or p->>'teamId' is distinct from f.team_id or p->>'playerId' is distinct from f.player_id or p->>'evidenceUrl' is distinct from f.evidence_url or p->>'evidenceHash' is distinct from f.evidence_hash
 or p->>'sourceItemId' is distinct from f.source_item_id or p->>'sourceRevision' is distinct from f.source_revision
 or new.retain_until is distinct from f.expires_at or p->>'schemaVersion' is distinct from 'research-fact-v1' or not beta_private.research_keys_only(p,array['schemaVersion','id','type','eventId','teamId','playerId','value','sourceId','sourceVersion','sourceItemId','sourceRevision','sourcePublishedAt','sourceObservedAt','ingestedAt','effectiveAt','expiresAt','confidence','reliability','evidenceUrl','evidenceHash','supersedesId','recordState','correctionReason'])
 then raise exception 'Exact immutable structured fact payload required';end if;
 keys:=case f.fact_type
 when 'PLAYER_INJURY' then array['status','reason'] when 'PLAYER_SUSPENSION' then array['status','reason'] when 'PLAYER_RETURN' then array['status','reason']
 when 'EXPECTED_LINEUP' then array['playerIds','formation'] when 'CONFIRMED_LINEUP' then array['playerIds','formation'] when 'MANAGER_CHANGE' then array['previousManagerId','newManagerId']
 when 'TEAM_FORM_UPDATE' then array['metric','value','unit','competitionId','season','venue','periodStart','periodEnd','sampleMatches','sampleMinutes','opponentAdjustment','adjustmentVersion']
 when 'PLAYER_FORM_UPDATE' then array['metric','value','unit','competitionId','season','venue','periodStart','periodEnd','sampleMatches','sampleMinutes','opponentAdjustment','adjustmentVersion']
 when 'TEAM_STAT_UPDATE' then array['metric','value','unit','competitionId','season','venue','periodStart','periodEnd','sampleMatches','sampleMinutes','opponentAdjustment','adjustmentVersion']
 when 'PLAYER_STAT_UPDATE' then array['metric','value','unit','competitionId','season','venue','periodStart','periodEnd','sampleMatches','sampleMinutes','opponentAdjustment','adjustmentVersion']
 when 'MATCH_RESULT' then array['homeGoals','awayGoals','period','status'] when 'REST_ADVANTAGE' then array['restHours','opponentRestHours','previousEventId','opponentPreviousEventId'] when 'SCHEDULE_CONGESTION' then array['windowStart','windowEnd','eventIds'] when 'WEATHER_UPDATE' then array['temperatureCelsius','windKph','precipitationMm','forecastFor'] when 'VENUE_CHANGE' then array['previousVenueId','venueId'] when 'MATCH_POSTPONED' then array['status','newStartAt'] when 'MATCH_CANCELLED' then array['status'] else null end;
 if keys is null or not coalesce(beta_private.research_keys_only(v,keys) and(v?&keys),false)then raise exception 'Unsupported research value shape';end if;
 if f.fact_type='MATCH_RESULT' and not coalesce(v->>'period'='REGULATION' and v->>'status'='FINAL' and(v->>'homeGoals')::integer between 0 and 100 and(v->>'awayGoals')::integer between 0 and 100,false)then raise exception 'Verified regulation result required';end if;
 if f.fact_type like 'PLAYER_%' and(f.team_id is null or f.player_id is null)then raise exception 'Player/team identity required';end if;
 if f.fact_type='CONFIRMED_LINEUP' and not coalesce(f.confidence='CONFIRMED' and jsonb_array_length(v->'playerIds')=11,false)then raise exception 'Confirmed eleven required';end if;
 if f.supersedes_id is not null and coalesce(length(p->>'correctionReason'),0)=0 then raise exception 'Correction reason required';end if;
 return new;
end $$;
create trigger research_payload_guard before insert or update or delete on beta_private.research_fact_payloads for each row execute function beta_private.research_payload_guard();

create function beta_private.research_fact_current(p_id text,p_jurisdiction text,p_at timestamptz default clock_timestamp())returns boolean language sql volatile set search_path='' as $$
 select coalesce((select f.record_state='ASSERTED' and f.ingested_at<=p_at and coalesce(f.source_published_at,f.source_observed_at)<=p_at and f.effective_at<=p_at and f.expires_at>p_at and p.retain_until>p_at
 and not exists(select 1 from beta_private.research_facts x where x.supersedes_id=f.id and x.ingested_at<=p_at and x.effective_at<=p_at)
 and beta_private.research_source_allowed(f.source_review_id,'DISPLAY',p_jurisdiction,p_at)
 from beta_private.research_facts f join beta_private.research_fact_payloads p on p.fact_id=f.id where f.id=p_id),false)
$$;
create function beta_private.research_snapshot_guard()returns trigger language plpgsql set search_path='' as $$
declare e beta_private.events;p beta_private.research_policies;fid text;checked timestamptz;begin
 if tg_op<>'INSERT' then raise exception 'Research snapshots are immutable';end if;
 if new.job_id is null then if new.created_by is distinct from beta_private.research_actor('FACT')then raise exception 'Snapshot actor mismatch';end if;else perform beta_private.research_worker(new.job_id);end if;
 select * into e from beta_private.events where id=new.event_id for share;select * into p from beta_private.research_policies where id=new.policy_id for share;
 perform beta_private.research_lock_sources(new.event_id);
 foreach fid in array new.fact_ids loop perform id from beta_private.research_facts where id=fid for share;end loop;checked:=clock_timestamp();
 if e.competition_id is distinct from 'soccer_epl' or e.status is distinct from 'scheduled' or e.start_at<=checked or new.event_start_at is distinct from e.start_at or new.event_participants is distinct from e.participants
 or new.as_of_time>checked or new.as_of_time<checked-interval '5 minutes' or new.manifest_hash is distinct from beta_private.research_hash(new.manifest) or new.research_hash!~'^[a-f0-9]{64}$'
 or new.manifest->>'eventId' is distinct from e.id or new.manifest->'factIds' is distinct from to_jsonb(new.fact_ids)
 or new.manifest#>>'{event,eventId}' is distinct from e.id or new.manifest#>>'{event,homeTeamId}' is distinct from e.participants->>0 or new.manifest#>>'{event,awayTeamId}' is distinct from e.participants->>1 or(new.manifest#>>'{event,startAt}')::timestamptz is distinct from e.start_at
 then raise exception 'Current prematch canonical research snapshot required';end if;
 foreach fid in array new.fact_ids loop
  if not beta_private.research_fact_current(fid,p.configuration->>'jurisdiction',new.as_of_time)or not beta_private.research_fact_current(fid,p.configuration->>'jurisdiction',checked)or not exists(select 1 from beta_private.research_facts f where f.id=fid and f.event_id=e.id)then raise exception 'Snapshot fact authority unavailable';end if;
 end loop;
 if new.job_id is null then perform beta_private.research_actor('FACT');else perform beta_private.research_worker(new.job_id);end if;new.created_at:=clock_timestamp();return new;
end $$;
create trigger research_snapshot_guard before insert or update or delete on beta_private.research_match_snapshots for each row execute function beta_private.research_snapshot_guard();

create function beta_private.research_content_guard()returns trigger language plpgsql set search_path='' as $$
declare a uuid;content beta_private.research_content;s beta_private.research_match_snapshots;p beta_private.research_policies;f text;publishing boolean;begin
 if tg_op<>'INSERT' then raise exception 'Research editorial history is append-only';end if;a:=beta_private.research_actor('CONTENT');
 if tg_table_name='research_content' then
  if new.created_by is distinct from a or length(new.headline)not between 1 and 240 or cardinality(new.fact_ids)=0 then raise exception 'Evidence-bound research draft required';end if;
  content:=new;publishing:=true;
 else
  if new.actor is distinct from a or length(btrim(new.reason))<12 then raise exception 'Audited editorial decision required';end if;
  select * into content from beta_private.research_content where id=new.content_id for share;publishing:=new.action='PUBLISH';
 end if;
 select * into s from beta_private.research_match_snapshots where id=content.snapshot_id for share;select * into p from beta_private.research_policies where id=s.policy_id for share;
 if content.event_id is distinct from s.event_id or not(content.fact_ids<@s.fact_ids)then raise exception 'Draft must use its immutable snapshot';end if;
 if publishing then
  perform id from beta_private.events where id=content.event_id for share;perform beta_private.research_lock_sources(content.event_id);
  if not exists(select 1 from beta_private.events e where e.id=content.event_id and e.status='scheduled' and e.start_at>clock_timestamp()and e.start_at=s.event_start_at and e.participants=s.event_participants)then raise exception 'Current snapshot event identity required';end if;
  foreach f in array content.fact_ids loop
   if not beta_private.research_fact_current(f,p.configuration->>'jurisdiction')or exists(select 1 from beta_private.research_facts x where x.id=f and x.confidence='RUMOUR')
   or exists(select 1 from beta_private.research_facts x join beta_private.research_fact_payloads xp on xp.fact_id=x.id join beta_private.research_facts other on other.event_id=x.event_id and other.fact_key=x.fact_key join beta_private.research_fact_payloads op on op.fact_id=other.id where x.id=f and beta_private.research_fact_current(other.id,p.configuration->>'jurisdiction') and xp.payload->'value' is distinct from op.payload->'value')then raise exception 'Current reviewed non-conflicting fact rights required';end if;
  end loop;
 end if;
 perform beta_private.research_actor('CONTENT');new.created_at:=clock_timestamp();return new;
end $$;
create trigger research_content_guard before insert or update or delete on beta_private.research_content for each row execute function beta_private.research_content_guard();
create trigger research_content_review_guard before insert or update or delete on beta_private.research_content_reviews for each row execute function beta_private.research_content_guard();

create function beta_private.research_schedule_guard()returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Disable research schedule; retain audit';end if;
 if tg_op='UPDATE' and current_setting('docked.research_scheduler',true)='true' and(to_jsonb(new)-array['next_run','last_success','last_failure'])=(to_jsonb(old)-array['next_run','last_success','last_failure'])then return new;end if;
 perform beta_private.research_actor('MANAGE');if tg_op='UPDATE' and(to_jsonb(new)-array['enabled','next_run'])is distinct from(to_jsonb(old)-array['enabled','next_run'])then raise exception 'Research schedule source/policy immutable';end if;
 if new.enabled and not exists(select 1 from beta_private.research_policies p where p.id=new.policy_id and beta_private.research_source_allowed(new.source_review_id,'AUTOMATED_FETCH',p.configuration->>'jurisdiction'))then raise exception 'Automatic source approval required';end if;return new;
end $$;
create trigger research_schedule_guard before insert or update or delete on beta_private.research_schedules for each row execute function beta_private.research_schedule_guard();

create function beta_private.research_request_guard()returns trigger language plpgsql set search_path='' as $$
declare s beta_private.research_source_versions;checked timestamptz;begin
 if tg_op='DELETE' then raise exception 'Research request ledger retained';end if;perform beta_private.research_worker(new.job_id);
 if tg_op='UPDATE' then
  if old.status<>'RESERVED' or new.status='RESERVED' or(to_jsonb(new)-array['completed_at','status','http_status','response_hash','etag','last_modified','measured','error_code','retry_after'])is distinct from(to_jsonb(old)-array['completed_at','status','http_status','response_hash','etag','last_modified','measured','error_code','retry_after'])then raise exception 'Request authority/history immutable';end if;
  new.completed_at:=clock_timestamp();return new;
 end if;
 if new.status is distinct from 'RESERVED' or new.completed_at is not null or new.http_status is not null or new.response_hash is not null or new.measured is not null or new.error_code is not null or new.retry_after is not null then raise exception 'Research request must reserve before network';end if;
 select * into s from beta_private.research_source_versions where id=new.source_review_id for share;perform pg_advisory_xact_lock(hashtext('research-fetch:'||s.source_key));checked:=clock_timestamp();
 if not exists(select 1 from beta_private.job_runs j join beta_private.research_schedules schedule on schedule.id=(j.payload->>'scheduleId')::uuid where j.id=new.job_id and schedule.source_review_id=new.source_review_id)then raise exception 'Request source must match authorized job';end if;
 if not beta_private.research_source_allowed(s.id,'AUTOMATED_FETCH',s.configuration->'jurisdictions'->>0,checked)
 or exists(select 1 from beta_private.research_source_health h where h.source_key=s.source_key and h.circuit_until>checked)
 or exists(select 1 from beta_private.research_fetch_requests r join beta_private.research_source_versions v on v.id=r.source_review_id where v.source_key=s.source_key and(r.status='RESERVED' or r.started_at>checked-(s.configuration#>>'{etiquette,minimumIntervalSeconds}')::integer*interval '1 second'))
 or(select count(*) from beta_private.research_fetch_requests r join beta_private.research_source_versions v on v.id=r.source_review_id where v.source_key=s.source_key and r.started_at>=date_trunc('day',checked at time zone 'UTC')at time zone 'UTC')>=(s.configuration#>>'{etiquette,maximumRequestsPerDay}')::integer
 then raise exception 'Source rights, rate, circuit or durable quota blocked';end if;
 perform beta_private.research_worker(new.job_id);new.started_at:=clock_timestamp();return new;
end $$;
create trigger research_request_guard before insert or update or delete on beta_private.research_fetch_requests for each row execute function beta_private.research_request_guard();

create function beta_private.research_recalculation_guard()returns trigger language plpgsql set search_path='' as $$
declare a uuid;s beta_private.research_match_snapshots;begin
 if tg_op<>'INSERT' then raise exception 'Recalculation request/abstention is immutable';end if;a:=beta_private.research_actor('FACT');select * into s from beta_private.research_match_snapshots where id=new.snapshot_id for share;
 if new.actor is distinct from a or new.new_prediction_id is not null or not(new.trigger_fact_ids<@s.fact_ids) or length(btrim(new.reason))<12
 or(new.prior_prediction_id is not null and not exists(select 1 from beta_private.football_model_attempts p where p.id=new.prior_prediction_id and p.event_id=s.event_id and p.requested_model_version=new.model_version))then raise exception 'Preserve original canonical prediction; no fitted recalculation executor installed';end if;
 new.created_at:=clock_timestamp();return new;
end $$;
create trigger research_recalculation_guard before insert or update or delete on beta_private.research_recalculations for each row execute function beta_private.research_recalculation_guard();

create function beta_private.research_dataset_guard()returns trigger language plpgsql set search_path='' as $$
declare d beta_private.research_dataset_snapshots;r beta_private.research_fetch_requests;s beta_private.research_source_versions;p jsonb;begin
 if tg_op='DELETE' and tg_table_name='research_dataset_payloads' then if old.retain_until>clock_timestamp()then raise exception 'Unexpired dataset evidence retained';end if;return old;end if;
 if tg_op<>'INSERT' then raise exception 'Research dataset evidence is immutable';end if;
 if tg_table_name='research_dataset_snapshots' then d:=new;else select * into d from beta_private.research_dataset_snapshots where id=new.snapshot_id for share;end if;
 select * into r from beta_private.research_fetch_requests where id=d.request_id for share;perform beta_private.research_worker(r.job_id);
 select * into s from beta_private.research_source_versions where id=r.source_review_id for share;
 if d.source_review_id is distinct from r.source_review_id or r.status<>'RESERVED' or not beta_private.research_source_allowed(s.id,'AUTOMATED_FETCH',s.configuration->'jurisdictions'->>0)
 or d.observed_at>clock_timestamp() or d.observed_at<r.started_at or d.quality->>'status' is distinct from 'RESEARCH_ONLY' or d.quality->>'modelReady' is distinct from 'false' or d.quality->>'settlementReady' is distinct from 'false' then raise exception 'Current bounded research-only dataset authority required';end if;
 if tg_table_name='research_dataset_payloads' then p:=new.payload;
 if beta_private.research_hash(p) is distinct from d.payload_hash or p->>'schemaVersion' is distinct from 'openfootball-research-dataset-v1' or p->>'sourceId' is distinct from s.source_key or p->>'sourceVersion' is distinct from s.version or p->>'sourcePublishedAt' is not null or(p->>'sourceObservedAt')::timestamptz is distinct from d.observed_at or jsonb_array_length(p->'matches')is distinct from d.record_count
 or new.retain_until<=clock_timestamp() or new.retain_until>least((s.configuration->>'effectiveTo')::timestamptz,d.observed_at+(s.configuration#>>'{storage,maxDays}')::integer*interval '1 day') then raise exception 'Exact retained research dataset required';end if;
 if not beta_private.research_keys_only(p,array['schemaVersion','competitionId','season','sourceId','sourceVersion','sourcePublishedAt','sourceObservedAt','matches'])or p->>'competitionId' is distinct from 'soccer_epl' or exists(select 1 from jsonb_array_elements(p->'matches')m where not beta_private.research_keys_only(m,array['sourceItemId','homeTeam','awayTeam','scheduledDate','scheduledTime','homeGoals','awayGoals','resultSemantics','scoreField'])or m->>'resultSemantics' is distinct from 'REPORTED_UNVERIFIED_REGULATION')then raise exception 'Research-only dataset shape required';end if;
 end if;return new;
end $$;
create trigger research_dataset_guard before insert or update or delete on beta_private.research_dataset_snapshots for each row execute function beta_private.research_dataset_guard();
create trigger research_dataset_payload_guard before insert or update or delete on beta_private.research_dataset_payloads for each row execute function beta_private.research_dataset_guard();

create function beta_private.research_health_guard()returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'Research health history retained';end if;
 perform beta_private.research_worker(nullif(current_setting('docked.research_job',true),'')::uuid);
 if not exists(select 1 from beta_private.research_fetch_requests r join beta_private.research_source_versions s on s.id=r.source_review_id where r.job_id::text=current_setting('docked.research_job',true) and s.source_key=new.source_key)then raise exception 'Own research request required';end if;
 new.updated_at:=clock_timestamp();return new;
end $$;
create trigger research_health_guard before insert or update or delete on beta_private.research_source_health for each row execute function beta_private.research_health_guard();

-- Independent typed-value validation at the SQL boundary, including direct trusted-server writes.
create function beta_private.research_decimal(p jsonb,p_nonnegative boolean default true)returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(p)='string'and length(p#>>'{}')<=60 and(p#>>'{}')~case when p_nonnegative then '^(0|[1-9][0-9]*)([.][0-9]+)?$'else '^-?(0|[1-9][0-9]*)([.][0-9]+)?$'end,false)
$$;
create function beta_private.research_identifier(p jsonb)returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(p)='string'and(p#>>'{}')~'^[A-Za-z0-9_.:-]{1,160}$',false)
$$;
create function beta_private.research_value_guard()returns trigger language plpgsql set search_path='' as $$
declare p jsonb:=new.payload;v jsonb:=p->'value';t text:=p->>'type';context jsonb;begin
 if tg_op<>'INSERT' then return new;end if;
 context:=case when v?'metric' then jsonb_build_object('metric',v->'metric','unit',v->'unit','competitionId',v->'competitionId','season',v->'season','venue',v->'venue','periodStart',v->'periodStart','periodEnd',v->'periodEnd','opponentAdjustment',v->'opponentAdjustment','adjustmentVersion',v->'adjustmentVersion')else 'null'::jsonb end;
 if not exists(select 1 from beta_private.research_facts f where f.id=new.fact_id and f.fact_key=beta_private.research_hash(jsonb_build_object('eventId',p->'eventId','teamId',p->'teamId','playerId',p->'playerId','type',p->'type','context',context)))then raise exception 'Canonical fact identity required';end if;
 if (t like 'TEAM_%' or t like '%LINEUP' or t in('MANAGER_CHANGE','REST_ADVANTAGE','SCHEDULE_CONGESTION'))and p->>'teamId' is null then raise exception 'Canonical team identity required';end if;
 if p->>'teamId' is not null and not exists(select 1 from beta_private.events e where e.id=p->>'eventId' and e.participants?(p->>'teamId'))then raise exception 'Team must match canonical participants';end if;
 if t in('PLAYER_INJURY','PLAYER_RETURN','PLAYER_SUSPENSION')and not coalesce(v->>'status' in('OUT','DOUBTFUL','AVAILABLE','UNKNOWN')and v->>'reason' in('INJURY','SUSPENSION','RETURN','OTHER','UNKNOWN'),false)then raise exception 'Structured availability required';end if;
 if t in('EXPECTED_LINEUP','CONFIRMED_LINEUP')and not coalesce(jsonb_array_length(v->'playerIds')between 1 and 11 and(select count(distinct x)from jsonb_array_elements_text(v->'playerIds')x)=jsonb_array_length(v->'playerIds')and not exists(select 1 from jsonb_array_elements_text(v->'playerIds')x where x!~'^[A-Za-z0-9_.:-]{1,160}$'),false)then raise exception 'Distinct structured lineup required';end if;
 if t in('EXPECTED_LINEUP','CONFIRMED_LINEUP') and not coalesce((v->>'formation' is null or v->>'formation'~'^[0-9](-[0-9]){1,4}$')and not exists(select 1 from jsonb_array_elements(v->'playerIds')x where not beta_private.research_identifier(x)),false)then raise exception 'Typed lineup identity required';end if;
 if v?'metric' and not coalesce(v->>'metric' in('goals','goals_conceded','shots','shots_on_target','xg','xg_conceded','xg_per_90','goals_per_90','assists','minutes','clean_sheets','wins','draws','losses','points','possession_pct','passes','tackles','saves')and v->>'value'~'^(0|[1-9][0-9]*)([.][0-9]+)?$' and v->>'unit' in('count','minutes','per_90','percent','per_match')and v->>'venue' in('HOME','AWAY','ALL')and(v->>'sampleMatches')::integer>0 and(v->>'sampleMinutes' is null or(v->>'sampleMinutes')::integer>=0)and(v->>'periodStart')::timestamptz<(v->>'periodEnd')::timestamptz and(v->>'periodEnd')::timestamptz<=(p->>'effectiveAt')::timestamptz and v->>'opponentAdjustment' in('UNADJUSTED','ADJUSTED')and(v->>'opponentAdjustment'<>'ADJUSTED' or v->>'adjustmentVersion' is not null),false)then raise exception 'Structured completed sporting statistic required';end if;
 if t='MATCH_POSTPONED' and v->>'status' is distinct from 'POSTPONED' or t='MATCH_CANCELLED' and v->>'status' is distinct from 'CANCELLED' then raise exception 'Explicit event status required';end if;
 if v?'metric' and not coalesce(beta_private.research_decimal(v->'value')and jsonb_typeof(v->'sampleMatches')='number'and(v->>'sampleMinutes' is null or jsonb_typeof(v->'sampleMinutes')='number')and beta_private.research_identifier(v->'competitionId')and beta_private.research_identifier(v->'season')and(v->>'unit'<>'percent' or(v->>'value')::numeric<=100)and(v->>'metric'<>'possession_pct' or v->>'unit'='percent')and(v->>'metric' not like '%_per_90' or v->>'unit'='per_90')and((v->>'opponentAdjustment'='UNADJUSTED' and v->>'adjustmentVersion' is null)or(v->>'opponentAdjustment'='ADJUSTED' and beta_private.research_identifier(v->'adjustmentVersion'))),false)then raise exception 'Typed sporting statistic context required';end if;
 if t='MATCH_RESULT' and not coalesce(jsonb_typeof(v->'homeGoals')='number'and jsonb_typeof(v->'awayGoals')='number'and v->>'homeGoals'~'^[0-9]+$'and v->>'awayGoals'~'^[0-9]+$',false)then raise exception 'Typed regulation goals required';end if;
 if t='REST_ADVANTAGE'and not coalesce(beta_private.research_decimal(v->'restHours')and beta_private.research_decimal(v->'opponentRestHours')and beta_private.research_identifier(v->'previousEventId')and beta_private.research_identifier(v->'opponentPreviousEventId'),false)then raise exception 'Typed nonnegative rest evidence required';end if;
 if t='WEATHER_UPDATE'and not coalesce((v->>'temperatureCelsius' is not null or v->>'windKph' is not null or v->>'precipitationMm' is not null)and(v->>'temperatureCelsius' is null or beta_private.research_decimal(v->'temperatureCelsius',false))and(v->>'windKph' is null or beta_private.research_decimal(v->'windKph'))and(v->>'precipitationMm' is null or beta_private.research_decimal(v->'precipitationMm'))and(v->>'forecastFor')::timestamptz is not null,false)then raise exception 'Typed available weather evidence required';end if;
 if t='MANAGER_CHANGE'and not coalesce(beta_private.research_identifier(v->'newManagerId')and(v->>'previousManagerId' is null or beta_private.research_identifier(v->'previousManagerId')),false)then raise exception 'Typed manager identities required';end if;
 if t='VENUE_CHANGE'and not coalesce(beta_private.research_identifier(v->'venueId')and(v->>'previousVenueId' is null or beta_private.research_identifier(v->'previousVenueId')),false)then raise exception 'Typed venue identities required';end if;
 if t='SCHEDULE_CONGESTION'and not coalesce((v->>'windowStart')::timestamptz is not null and(v->>'windowEnd')::timestamptz is not null and jsonb_array_length(v->'eventIds')>0 and(select count(distinct x)from jsonb_array_elements_text(v->'eventIds')x)=jsonb_array_length(v->'eventIds')and not exists(select 1 from jsonb_array_elements(v->'eventIds')x where not beta_private.research_identifier(x)),false)then raise exception 'Typed event schedule required';end if;
 if t='MATCH_POSTPONED'and v->>'newStartAt' is not null then perform(v->>'newStartAt')::timestamptz;end if;
 if p->>'evidenceUrl'!~'^https://[A-Za-z0-9.-]+/[^?#@]*$' then raise exception 'Public credential-free evidence URL required';end if;
 return new;
end $$;
create trigger research_value_guard before insert on beta_private.research_fact_payloads for each row execute function beta_private.research_value_guard();

do $$declare t text;f record;begin
 foreach t in array array['research_source_versions','research_policies','research_feature_versions','research_facts','research_fact_payloads','research_match_snapshots','research_content','research_content_reviews','research_schedules','research_fetch_requests','research_source_health','research_recalculations','research_dataset_snapshots','research_dataset_payloads']loop
  execute format('alter table beta_private.%I enable row level security',t);execute format('revoke all on beta_private.%I from public,anon,authenticated,docked_beta_app',t);
 end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='beta_private' and p.proname like 'research_%'loop execute format('revoke all on function %s from public,anon,authenticated,docked_beta_app',f.signature);end loop;
end $$;


-- SOURCE 20261004044506_phase5d_fitted_poisson_research.sql sha256=dc0b36b56e3b7bf3f762a2ac2dfa572e4b1d29a33cbccf10a10beadc8c722d89
-- Retained research fit. No source/model/schedule/publication activation or seed data.
create table beta_private.football_training_manifests (
 id uuid primary key default gen_random_uuid(),
 model_version text not null unique references beta_private.football_model_versions(id),
 training jsonb not null, training_hash text not null check(training_hash ~ '^[a-f0-9]{64}$'),
 manifest jsonb not null, manifest_hash text not null check(manifest_hash ~ '^[a-f0-9]{64}$'),
 fitted jsonb not null, fitted_hash text not null check(fitted_hash ~ '^[a-f0-9]{64}$'),
 source_ids text[] not null, code_commit text not null check(code_commit ~ '^[a-f0-9]{40}$'),
 input_cutoff timestamptz not null, fitted_at timestamptz not null,
 actor uuid not null, created_at timestamptz not null default clock_timestamp()
);
alter table beta_private.football_training_manifests enable row level security;
revoke all on beta_private.football_training_manifests from public,anon,authenticated,docked_beta_app;
create trigger immutable before update or delete on beta_private.football_training_manifests for each row execute function beta_private.immutable();

create function beta_private.football_training_guard() returns trigger language plpgsql set search_path='' as $$
declare v beta_private.football_model_versions;s beta_private.football_sporting_sources;m jsonb;sid text;checked timestamptz;
begin
 perform beta_private.scanner_assert_actor(true);
 select * into v from beta_private.football_model_versions where id=new.model_version for share;
 foreach sid in array new.source_ids loop
  select * into s from beta_private.football_sporting_sources where id=sid for share;
  if s.id is null or s.revoked_at is not null or s.known_at>new.fitted_at or s.effective_from>new.fitted_at or s.effective_to<=clock_timestamp() then raise exception 'Current training rights required';end if;
 end loop;
 checked:=clock_timestamp();
 if new.actor is distinct from beta_private.scanner_assert_actor(true) or v.id is null or v.lifecycle not in('RESEARCH','FORWARD_CALIBRATION')
 or v.code_commit is distinct from new.code_commit or new.fitted_at>checked or new.input_cutoff>new.fitted_at
 or cardinality(new.source_ids)<1 or cardinality(new.source_ids)<>(select count(distinct x) from unnest(new.source_ids)x)
 or new.training_hash is distinct from beta_private.football_json_hash(new.training)
 or new.manifest_hash is distinct from beta_private.football_json_hash(new.manifest)
 or new.fitted_hash is distinct from beta_private.football_json_hash(new.fitted)
 or v.configuration->>'trainingDataHash' is distinct from new.training_hash
 or v.configuration->'parameters' is distinct from new.fitted->'parameters'
 or v.configuration->>'fittedHash' is distinct from new.fitted_hash
 or new.fitted->>'trainingHash' is distinct from new.training_hash
 or new.fitted->>'configHash' is distinct from beta_private.football_json_hash(new.fitted->'config')
 or new.fitted#>>'{diagnostics,converged}' is distinct from 'true'
 or new.training->>'schemaVersion' is distinct from 'epl-poisson-training-v1'
 or new.training->>'competitionId' is distinct from 'soccer_epl'
 or (new.training->>'asOfTime')::timestamptz>new.fitted_at
 or (new.training->>'asOfTime')::timestamptz<new.input_cutoff
 or (new.fitted->>'asOfTime')::timestamptz is distinct from (new.training->>'asOfTime')::timestamptz
 or (new.training-array['schemaVersion','competitionId','asOfTime','matches'])<>'{}'::jsonb
 or not beta_private.football_sport_only(new.training)
 or jsonb_typeof(new.training->'matches') is distinct from 'array'
 or jsonb_array_length(new.training->'matches')<20
 or jsonb_typeof(new.manifest->'canonicalAliases') is distinct from 'object'
 or new.manifest->>'mappingVersion' is null
 then raise exception 'Bound reviewed training manifest required';end if;
 if jsonb_array_length(new.training->'matches')<>(select count(distinct x->>'id') from jsonb_array_elements(new.training->'matches')x) then raise exception 'Duplicate training match';end if;
 if new.input_cutoff is distinct from(select max((x->>'observedAt')::timestamptz) from jsonb_array_elements(new.training->'matches')x) then raise exception 'Actual source observation cutoff required';end if;
 for m in select * from jsonb_array_elements(new.training->'matches') loop
  if (m-array['id','home','away','date','homeGoals','awayGoals','observedAt','sourceId'])<>'{}'::jsonb
  or not coalesce(length(m->>'id')>0 and length(m->>'home')>0 and length(m->>'away')>0 and m->>'home'<>m->>'away'
   and(m->>'homeGoals')~'^[0-9]+$' and(m->>'awayGoals')~'^[0-9]+$'
   and(m->>'homeGoals')::integer between 0 and 100 and(m->>'awayGoals')::integer between 0 and 100
   and(m->>'date')::date<substring(m->>'observedAt',1,10)::date
   and(m->>'observedAt')::timestamptz<=new.input_cutoff and m->>'sourceId'=any(new.source_ids),false)
  then raise exception 'Dated sporting-only training evidence required';end if;
 end loop;
 new.created_at:=checked;return new;
end $$;
create trigger football_training_guard before insert on beta_private.football_training_manifests for each row execute function beta_private.football_training_guard();

-- Preserve the original schema's full validation. The new schema records date-only
-- training provenance without inventing exact historical completion timestamps.
drop trigger football_input_guard on beta_private.football_sporting_inputs;
create trigger football_input_guard before insert on beta_private.football_sporting_inputs for each row
 when(new.payload->>'schemaVersion' is distinct from 'football-fitted-input-v1') execute function beta_private.football_input_guard();
create function beta_private.football_fitted_input_guard() returns trigger language plpgsql set search_path='' as $$
declare e beta_private.events;t beta_private.football_training_manifests;s beta_private.football_sporting_sources;sid text;checked timestamptz;
begin
 perform beta_private.scanner_assert_actor(true);
 select * into e from beta_private.events where id=new.event_id for share;
 select * into t from beta_private.football_training_manifests where id=(new.payload->>'manifestId')::uuid for share;
 foreach sid in array new.source_ids loop
  select * into s from beta_private.football_sporting_sources where id=sid for share;
  if s.id is null or s.revoked_at is not null or s.known_at>new.as_of_time or s.effective_from>new.as_of_time or s.effective_to<=clock_timestamp() then raise exception 'Current sporting rights required';end if;
 end loop;
 checked:=clock_timestamp();
 if new.created_by is distinct from beta_private.scanner_assert_actor(true) or e.id is null or e.competition_id<>'soccer_epl'
 or e.status<>'scheduled' or e.start_at<=checked or t.id is null or t.created_at>new.as_of_time
 or new.as_of_time>checked or new.input_cutoff is distinct from t.input_cutoff or new.input_cutoff>new.as_of_time
 or new.source_ids is distinct from t.source_ids or new.input_hash is distinct from beta_private.football_json_hash(new.payload)
 or not beta_private.football_sport_only(new.payload)
 or(new.payload-array['schemaVersion','event','asOfTime','calculatedAt','codeCommit','manifestId','modelVersion','mappingVersion','missingRequired','missingOptional'])<>'{}'::jsonb
 or((new.payload->'event')-array['eventId','competitionId','homeTeamId','awayTeamId','sport','startAt','status','knownAt','sourceId'])<>'{}'::jsonb
 or new.payload->>'modelVersion' is distinct from t.model_version
 or new.payload->>'codeCommit' is distinct from t.code_commit
 or new.payload->>'mappingVersion' is distinct from t.manifest->>'mappingVersion'
 or new.payload#>>'{event,eventId}' is distinct from e.id
 or new.payload#>>'{event,competitionId}' is distinct from e.competition_id
 or new.payload#>>'{event,sport}' is distinct from 'football' or new.payload#>>'{event,status}' is distinct from 'scheduled'
 or new.payload#>>'{event,homeTeamId}' is distinct from t.manifest->'canonicalAliases'->>(e.participants->>0)
 or new.payload#>>'{event,awayTeamId}' is distinct from t.manifest->'canonicalAliases'->>(e.participants->>1)
 or not coalesce(length(new.payload#>>'{event,homeTeamId}')>0 and length(new.payload#>>'{event,awayTeamId}')>0
 and new.payload#>>'{event,homeTeamId}'<>new.payload#>>'{event,awayTeamId}'
 and (new.payload#>>'{event,knownAt}')::timestamptz<=new.as_of_time
 and length(new.payload#>>'{event,sourceId}')>0
 and(new.payload#>>'{event,startAt}')::timestamptz=e.start_at
 and(new.payload->>'asOfTime')::timestamptz=new.as_of_time
 and(new.payload->>'calculatedAt')::timestamptz between new.as_of_time and checked,false)
 or new.payload->'missingRequired' is distinct from '[]'::jsonb
 or jsonb_typeof(new.payload->'missingOptional') is distinct from 'array'
 then raise exception 'Current mapped fitted-model input required';end if;
 new.created_at:=checked;return new;
end $$;
create trigger football_fitted_input_guard before insert on beta_private.football_sporting_inputs for each row
 when(new.payload->>'schemaVersion'='football-fitted-input-v1') execute function beta_private.football_fitted_input_guard();
revoke all on function beta_private.football_training_guard(),beta_private.football_fitted_input_guard() from public,anon,authenticated,docked_beta_app;

create function beta_private.football_fitted_prediction_binding() returns trigger language plpgsql set search_path='' as $$
declare i beta_private.football_sporting_inputs;t beta_private.football_training_manifests;
begin
 if new.status='READY' then
  select * into i from beta_private.football_sporting_inputs where id=new.input_snapshot_id;
  if i.payload->>'schemaVersion'='football-fitted-input-v1' then
   select * into t from beta_private.football_training_manifests where id=(i.payload->>'manifestId')::uuid;
   if t.id is null or new.model_version is distinct from t.model_version or new.code_commit is distinct from t.code_commit
   then raise exception 'Prediction must use its retained fitted revision';end if;
  end if;
 end if;
 return new;
end $$;
create trigger football_fitted_prediction_binding before insert on beta_private.football_model_attempts for each row execute function beta_private.football_fitted_prediction_binding();
revoke all on function beta_private.football_fitted_prediction_binding() from public,anon,authenticated,docked_beta_app;

-- Statistical training permission never implies authoritative settlement permission.
create function beta_private.football_outcome_authority() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from beta_private.football_sporting_sources where id=new.source_id and revoked_at is null
  and purposes @> array['regulation_results'] and effective_from<=clock_timestamp() and effective_to>clock_timestamp())
 then raise exception 'Separate authoritative regulation-results permission required';end if;
 return new;
end $$;
create trigger football_outcome_authority before insert on beta_private.football_model_outcomes for each row execute function beta_private.football_outcome_authority();
revoke all on function beta_private.football_outcome_authority() from public,anon,authenticated,docked_beta_app;

create index football_fitted_inputs_lookup on beta_private.football_sporting_inputs(event_id,(payload->>'manifestId'),created_at desc)
 where payload->>'schemaVersion'='football-fitted-input-v1';


-- SOURCE 20261007204317_fantasy_cards_preview_v1.sql sha256=a4dd4a291109443e0c5a196e465c15cd86ef035373f136d28257775ad557b2d4
-- Isolated, closed, test-credit-only Preview. Never enables existing production flags.
create schema beta_fantasy;
revoke all on schema beta_fantasy from public,anon,authenticated;
create table beta_fantasy.settings(id boolean primary key default true check(id), enabled boolean not null default false, fee_bps integer not null default 750 check(fee_bps between 0 and 10000));
insert into beta_fantasy.settings default values;
create table beta_fantasy.members(user_id uuid primary key, expires_at timestamptz not null, revoked_at timestamptz, joined_at timestamptz not null default clock_timestamp());
create table beta_fantasy.sports(id text primary key, positions jsonb not null, team_size integer not null check(team_size between 1 and 30));
insert into beta_fantasy.sports values('football','{"GK":1,"DEF":4,"MID":4,"FWD":2}',11);
create table beta_fantasy.tiers(id text primary key, rank integer unique not null, reference_supply integer not null check(reference_supply>0));
insert into beta_fantasy.tiers values('CORE',1,10000),('RARE',2,2500),('ELITE',3,500),('LEGENDARY',4,100),('ICON',5,10);
create table beta_fantasy.players(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 80), sport text not null references beta_fantasy.sports, position text not null, team text not null, colour text not null check(colour ~ '^#[0-9A-Fa-f]{6}$'), shirt integer not null check(shirt between 1 and 99), first_season text not null, prospect_rank integer check(prospect_rank>0), status text not null default 'active' check(status in('active','injured','suspended','unavailable','dropped','retired','delisted')));
create table beta_fantasy.editions(id uuid primary key default gen_random_uuid(), player_id uuid not null references beta_fantasy.players, tier text not null references beta_fantasy.tiers, season text not null, kind text not null check(kind in('first_year','regular','special')), max_supply integer not null check(max_supply>0), issued integer not null default 0 check(issued>=0 and issued<=max_supply), prospect_rank integer, launch_at timestamptz not null default clock_timestamp(), status text not null default 'draft' check(status in('draft','launched','closed')), locked_at timestamptz, unique(player_id,tier,season,kind));
create table beta_fantasy.cards(id uuid primary key default gen_random_uuid(), edition_id uuid not null references beta_fantasy.editions, serial integer not null check(serial>0), owner_id uuid not null references beta_fantasy.members(user_id), tradeable boolean not null, created_at timestamptz not null default clock_timestamp(), unique(edition_id,serial));
create table beta_fantasy.ownership_events(id uuid primary key default gen_random_uuid(), card_id uuid not null references beta_fantasy.cards, from_user uuid references beta_fantasy.members, to_user uuid not null references beta_fantasy.members, reason text not null, reference uuid not null, acquisition_price bigint, prospect_rank integer, created_at timestamptz not null default clock_timestamp());
create table beta_fantasy.journals(id uuid primary key default gen_random_uuid(), reason text not null, reference uuid not null unique, created_at timestamptz not null default clock_timestamp());
create table beta_fantasy.ledger(id uuid primary key default gen_random_uuid(), journal_id uuid not null references beta_fantasy.journals, account text not null, amount bigint not null check(amount<>0), created_at timestamptz not null default clock_timestamp());
create index on beta_fantasy.ledger(account);
create table beta_fantasy.pack_definitions(id uuid primary key default gen_random_uuid(), name text not null, version integer not null default 1, slots jsonb not null check(jsonb_typeof(slots)='array' and jsonb_array_length(slots) between 1 and 30), pool uuid[] not null check(cardinality(pool)>0), weights jsonb not null, guarantees jsonb not null default '{}', price bigint not null check(price>=0), max_quantity integer not null check(max_quantity>0), sold integer not null default 0 check(sold>=0 and sold<=max_quantity), tradeable boolean not null, starts_at timestamptz not null default clock_timestamp(), ends_at timestamptz not null default clock_timestamp()+interval '1 year', status text not null default 'active' check(status in('active','closed')), unique(name,version));
create table beta_fantasy.packs(id uuid primary key default gen_random_uuid(), user_id uuid not null references beta_fantasy.members, definition_id uuid not null references beta_fantasy.pack_definitions, request_id uuid not null unique, created_at timestamptz not null default clock_timestamp(), opened_at timestamptz);
create table beta_fantasy.pack_items(pack_id uuid not null references beta_fantasy.packs, slot integer not null, card_id uuid not null unique references beta_fantasy.cards, primary key(pack_id,slot));
create table beta_fantasy.listings(id uuid primary key default gen_random_uuid(), card_id uuid not null references beta_fantasy.cards, seller uuid not null references beta_fantasy.members, price bigint not null check(price between 1 and 1000000000), fee_bps integer not null check(fee_bps between 0 and 10000), state text not null default 'active' check(state in('active','sold','cancelled')), created_at timestamptz not null default clock_timestamp());
create unique index on beta_fantasy.listings(card_id) where state='active';
create table beta_fantasy.sales(id uuid primary key default gen_random_uuid(), listing_id uuid not null unique references beta_fantasy.listings, buyer uuid not null references beta_fantasy.members, seller uuid not null references beta_fantasy.members, price bigint not null, fee bigint not null, created_at timestamptz not null default clock_timestamp());
create table beta_fantasy.trades(id uuid primary key default gen_random_uuid(), sender uuid not null references beta_fantasy.members, recipient uuid not null references beta_fantasy.members, state text not null default 'pending' check(state in('draft','pending','accepted','declined','cancelled','expired')), expires_at timestamptz not null default clock_timestamp()+interval '7 days', created_at timestamptz not null default clock_timestamp(), check(sender<>recipient));
create table beta_fantasy.trade_items(trade_id uuid not null references beta_fantasy.trades, card_id uuid not null references beta_fantasy.cards, from_user uuid not null references beta_fantasy.members, primary key(trade_id,card_id));
create table beta_fantasy.scoring_rules(id uuid primary key default gen_random_uuid(), version text not null unique, rules jsonb not null);
insert into beta_fantasy.scoring_rules(version,rules) values('football-demo-v1','{"appearance":1,"sixty_minutes":1,"goal":{"GK":6,"DEF":6,"MID":5,"FWD":4},"assist":3,"clean_sheet":{"GK":4,"DEF":4,"MID":1,"FWD":0},"save_group":3,"save_points":1,"yellow":-1,"red":-3,"own_goal":-2,"conceded_group":2,"conceded_points":-1}');
create table beta_fantasy.competitions(id uuid primary key default gen_random_uuid(), name text not null, sport text not null references beta_fantasy.sports, season text not null, round integer not null check(round>0), opens_at timestamptz not null default clock_timestamp(), locks_at timestamptz not null, rules jsonb not null, scoring_id uuid not null references beta_fantasy.scoring_rules, awards jsonb not null default '[100,70,50]', prize text not null default 'Preview/Test Prize' check(prize='Preview/Test Prize'), scored_at timestamptz, seed integer, check(locks_at>opens_at));
create table beta_fantasy.entries(id uuid primary key default gen_random_uuid(), competition_id uuid not null references beta_fantasy.competitions, user_id uuid not null references beta_fantasy.members, cards uuid[] not null, snapshot jsonb not null, updated_at timestamptz not null default clock_timestamp(), unique(competition_id,user_id));
create table beta_fantasy.round_scores(competition_id uuid not null references beta_fantasy.competitions, player_id uuid not null references beta_fantasy.players, scoring_id uuid not null references beta_fantasy.scoring_rules, stats jsonb not null, score integer not null, primary key(competition_id,player_id));
create table beta_fantasy.round_inputs(competition_id uuid not null references beta_fantasy.competitions, player_id uuid not null references beta_fantasy.players, stats jsonb not null, actor uuid not null, primary key(competition_id,player_id));
create table beta_fantasy.results(competition_id uuid not null references beta_fantasy.competitions, user_id uuid not null references beta_fantasy.members, entry_id uuid not null references beta_fantasy.entries, score integer not null, rank integer not null, championship_points integer not null, primary key(competition_id,user_id));
create table beta_fantasy.status_events(id uuid primary key default gen_random_uuid(), player_id uuid not null references beta_fantasy.players, status text not null, actor uuid not null, created_at timestamptz not null default clock_timestamp());
create table beta_fantasy.replacements(card_id uuid primary key references beta_fantasy.cards, user_id uuid not null references beta_fantasy.members, pack_id uuid unique references beta_fantasy.packs, created_at timestamptz not null default clock_timestamp());
create table beta_fantasy.requests(user_id uuid not null references beta_fantasy.members, request_id uuid not null, action text not null, payload jsonb not null, result jsonb not null, primary key(user_id,request_id));
create table beta_fantasy.admin_events(id uuid primary key default gen_random_uuid(), actor uuid not null, action text not null, payload jsonb not null, created_at timestamptz not null default clock_timestamp());

create function beta_fantasy.immutable() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'Immutable fantasy record'; end $$;
create function beta_fantasy.member_guard() returns trigger language plpgsql set search_path='' as $$ begin
 perform pg_advisory_xact_lock(71820342);
 if new.revoked_at is null and new.expires_at>clock_timestamp() and (select count(*) from beta_fantasy.members where user_id<>new.user_id and revoked_at is null and expires_at>clock_timestamp())>=3 then raise exception 'Preview limited to three members'; end if;
 return new; end $$;
create trigger member_limit before insert or update on beta_fantasy.members for each row execute function beta_fantasy.member_guard();
create function beta_fantasy.competition_guard() returns trigger language plpgsql set search_path='' as $$ begin
 if (to_jsonb(new)-array['seed','scored_at']) is distinct from (to_jsonb(old)-array['seed','scored_at']) or old.scored_at is not null then raise exception 'Competition rules and results immutable'; end if;
 return new; end $$;
create trigger competition_version before update on beta_fantasy.competitions for each row execute function beta_fantasy.competition_guard();
create function beta_fantasy.edition_guard() returns trigger language plpgsql set search_path='' as $$ begin
 if new.max_supply>old.max_supply or (old.locked_at is not null and (new.max_supply<>old.max_supply or new.player_id<>old.player_id or new.tier<>old.tier or new.season<>old.season or new.kind<>old.kind or new.locked_at is distinct from old.locked_at)) or new.issued<old.issued then raise exception 'Edition supply and identity locked'; end if;
 return new; end $$;
create trigger edition_guard before update on beta_fantasy.editions for each row execute function beta_fantasy.edition_guard();
create function beta_fantasy.card_guard() returns trigger language plpgsql set search_path='' as $$ declare e beta_fantasy.editions; begin
 if tg_op='UPDATE' then
  if (to_jsonb(new)-'owner_id') is distinct from (to_jsonb(old)-'owner_id') then raise exception 'Card identity immutable'; end if;
 else
  select * into strict e from beta_fantasy.editions where id=new.edition_id for update;
  if e.status<>'launched' or e.launch_at>clock_timestamp() or new.serial<>e.issued+1 or new.serial>e.max_supply then raise exception 'Edition supply exhausted or invalid serial'; end if;
  update beta_fantasy.editions set issued=new.serial,locked_at=coalesce(locked_at,clock_timestamp()) where id=e.id;
 end if; return new; end $$;
create trigger card_guard before insert or update on beta_fantasy.cards for each row execute function beta_fantasy.card_guard();
create function beta_fantasy.ledger_check() returns trigger language plpgsql set search_path='' as $$ begin
 if (select coalesce(sum(amount),0) from beta_fantasy.ledger where journal_id=new.journal_id)<>0 then raise exception 'Unbalanced journal'; end if;
 if exists(select 1 from beta_fantasy.ledger where account not like 'system:%' group by account having sum(amount)<0) then raise exception 'Insufficient credits'; end if;
 return null; end $$;
create constraint trigger ledger_balanced after insert on beta_fantasy.ledger deferrable initially deferred for each row execute function beta_fantasy.ledger_check();
create function beta_fantasy.entry_guard() returns trigger language plpgsql set search_path='' as $$ declare comp_id uuid; begin
 comp_id:=case when tg_op='INSERT' then new.competition_id else old.competition_id end;
 if exists(select 1 from beta_fantasy.competitions where id=comp_id and (locks_at<=clock_timestamp() or opens_at>clock_timestamp() or scored_at is not null)) then raise exception 'Lineup locked'; end if; if tg_op='DELETE' then return old; end if; return new; end $$;
create trigger entry_locked before insert or update or delete on beta_fantasy.entries for each row execute function beta_fantasy.entry_guard();
create function beta_fantasy.pack_guard() returns trigger language plpgsql set search_path='' as $$ begin
 if (to_jsonb(new)-'sold') is distinct from (to_jsonb(old)-'sold') then raise exception 'Pack configuration version immutable'; end if; return new; end $$;
create trigger pack_version before update on beta_fantasy.pack_definitions for each row execute function beta_fantasy.pack_guard();
do $$ declare t text; begin
 for t in select tablename from pg_tables where schemaname='beta_fantasy' loop
  execute format('alter table beta_fantasy.%I enable row level security',t);
  execute format('revoke all on beta_fantasy.%I from public,anon,authenticated,docked_beta_app',t);
 end loop;
 foreach t in array array['ownership_events','journals','ledger','pack_items','sales','scoring_rules','round_scores','results','status_events','requests','admin_events','trade_items'] loop
  execute format('create trigger immutable before update or delete on beta_fantasy.%I for each row execute function beta_fantasy.immutable()',t);
 end loop;
 foreach t in array array['cards','editions','packs','members','competitions','replacements'] loop
  execute format('create trigger no_delete before delete on beta_fantasy.%I for each row execute function beta_fantasy.immutable()',t);
 end loop;
end $$;

create function beta_fantasy.actor(admin_required boolean default false) returns uuid language plpgsql set search_path='' as $$ declare u uuid:=auth.uid(); begin
 if current_setting('docked.fantasy_preview',true) is distinct from 'test-credits-only' or not (select enabled from beta_fantasy.settings) then raise exception 'Fantasy Preview disabled'; end if;
 perform 1 from beta_fantasy.members where user_id=u for share;
 perform 1 from beta_public.profiles where id=u for share;
 if not beta_private.active_member_session() or not exists(select 1 from beta_public.profiles where id=u and disabled_at is null and age_attested and accepted_version<>'') or not exists(select 1 from beta_fantasy.members where user_id=u and revoked_at is null and expires_at>clock_timestamp()) then raise exception 'Preview membership or session required'; end if;
 if exists(select 1 from auth.users au where au.id=u and (to_jsonb(au)->>'banned_until')::timestamptz>clock_timestamp()) then raise exception 'Account banned'; end if;
 if admin_required and (coalesce(auth.jwt()->>'aal','')<>'aal2' or not exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin'))) then raise exception 'Admin MFA required'; end if;
 return u; end $$;
create function beta_fantasy.balance(u uuid) returns bigint language sql set search_path='' as $$ select coalesce(sum(amount),0)::bigint from beta_fantasy.ledger where account=u::text $$;
create function beta_fantasy.money(reason text, ref uuid, accounts text[], amounts bigint[]) returns void language plpgsql set search_path='' as $$ declare j uuid; i integer; begin
 if cardinality(accounts)<>cardinality(amounts) or (select sum(x) from unnest(amounts) x)<>0 then raise exception 'Unbalanced journal'; end if;
 insert into beta_fantasy.journals(reason,reference) values(reason,ref) returning id into j;
 for i in 1..cardinality(accounts) loop if amounts[i]<>0 then insert into beta_fantasy.ledger(journal_id,account,amount) values(j,accounts[i],amounts[i]); end if; end loop;
 if exists(select 1 from beta_fantasy.ledger where account not like 'system:%' group by account having sum(amount)<0) then raise exception 'Insufficient credits'; end if;
end $$;
create function beta_fantasy.mint(eid uuid,u uuid,tradeable boolean,reason text,ref uuid) returns uuid language plpgsql set search_path='' as $$ declare c uuid; e beta_fantasy.editions; begin
 select * into strict e from beta_fantasy.editions where id=eid for update;
 insert into beta_fantasy.cards(edition_id,serial,owner_id,tradeable) values(eid,e.issued+1,u,tradeable) returning id into c;
 insert into beta_fantasy.ownership_events(card_id,to_user,reason,reference,prospect_rank) values(c,u,reason,ref,e.prospect_rank);
 return c; end $$;
create function beta_fantasy.transferable(cid uuid,u uuid) returns void language plpgsql set search_path='' as $$ begin
 if not exists(select 1 from beta_fantasy.members m join beta_public.profiles p on p.id=m.user_id where m.user_id=u and m.revoked_at is null and m.expires_at>clock_timestamp() and p.disabled_at is null) then raise exception 'Card owner membership inactive'; end if;
 if exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.packs pa on pa.id=pi.pack_id where pi.card_id=cid and pa.opened_at is null) then raise exception 'Open the pack before transferring cards'; end if;
 if not exists(select 1 from beta_fantasy.cards where id=cid and owner_id=u and tradeable) then raise exception 'Tradeable owned card required'; end if;
 if exists(select 1 from beta_fantasy.entries e join beta_fantasy.competitions c on c.id=e.competition_id where cid=any(e.cards) and c.scored_at is null) then raise exception 'Card committed to lineup; remove before trading'; end if;
end $$;
create function beta_fantasy.transfer(cid uuid,from_id uuid,to_id uuid,reason text,ref uuid,price bigint default null) returns void language plpgsql set search_path='' as $$ begin
 perform beta_fantasy.transferable(cid,from_id);
 update beta_fantasy.cards set owner_id=to_id where id=cid and owner_id=from_id;
 if not found then raise exception 'Ownership changed'; end if;
 insert into beta_fantasy.ownership_events(card_id,from_user,to_user,reason,reference,acquisition_price,prospect_rank) select cid,from_id,to_id,reason,ref,price,p.prospect_rank from beta_fantasy.cards c join beta_fantasy.editions e on e.id=c.edition_id join beta_fantasy.players p on p.id=e.player_id where c.id=cid;
 update beta_fantasy.listings set state='cancelled' where card_id=cid and state='active';
end $$;
create function beta_fantasy.social(u uuid,body text) returns void language plpgsql set search_path='' as $$ declare sid uuid; begin
 -- Use existing visibility/moderation/blocking policies. Never post for suspended/private accounts.
 select id into sid from beta_private.social_profiles where user_id=u and status='active' and visibility='members';
 if sid is not null and beta_private.community_feature_allowed(u,'community_social') then
  insert into beta_private.social_posts(author_id,kind,body,sport) values(sid,'celebration',body,'football');
 end if; end $$;
create function beta_fantasy.lineup(comp uuid,u uuid,ids uuid[]) returns jsonb language plpgsql set search_path='' as $$ declare c beta_fantasy.competitions; s beta_fantasy.sports; item record; snapshot jsonb; begin
 select * into strict c from beta_fantasy.competitions where id=comp;
 select * into strict s from beta_fantasy.sports where id=c.sport;
 if (select count(*) from jsonb_object_keys(coalesce(c.rules->'positions',s.positions)))<>(select count(*) from jsonb_object_keys(s.positions)) or exists(select 1 from jsonb_each_text(coalesce(c.rules->'positions',s.positions)) f where not (s.positions ? f.key) or f.value::integer<0) or (select sum(value::integer) from jsonb_each_text(coalesce(c.rules->'positions',s.positions))) is distinct from s.team_size then raise exception 'Complete sport formation required'; end if;
 if cardinality(ids)<>s.team_size or (select count(distinct x) from unnest(ids) x)<>s.team_size then raise exception 'Invalid lineup size or duplicate card'; end if;
 if exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.packs pa on pa.id=pi.pack_id where pi.card_id=any(ids) and pa.opened_at is null) then raise exception 'Open pack before fielding cards'; end if;
 if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.id=any(ids) and a.owner_id=u and p.sport=c.sport and p.status not in('retired','delisted') and not exists(select 1 from beta_fantasy.listings l where l.card_id=a.id and l.state='active'))<>s.team_size then raise exception 'Ineligible, listed or unowned card'; end if;
 if coalesce((c.rules->>'duplicates')::boolean,false)=false and (select count(distinct e.player_id) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids))<>s.team_size then raise exception 'Duplicate player'; end if;
 for item in select key,value from jsonb_each_text(coalesce(c.rules->'positions',s.positions)) loop
  if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.id=any(ids) and p.position=item.key)<>item.value::integer then raise exception 'Invalid position formation'; end if;
 end loop;
 for item in select key,value from jsonb_each_text(coalesce(c.rules->'tier_max','{}')) loop
  if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids) and e.tier=item.key)>item.value::integer then raise exception 'Tier eligibility exceeded'; end if;
 end loop;
 if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids) and e.kind='first_year')<coalesce((c.rules->>'first_year_min')::integer,0) or (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids) and e.tier='CORE')<coalesce((c.rules->>'core_min')::integer,0) then raise exception 'Minimum Core or First Year eligibility'; end if;
 select jsonb_agg(jsonb_build_object('card_id',a.id,'player_id',e.player_id,'tier',e.tier,'position',p.position,'season',e.season,'kind',e.kind) order by a.id) into snapshot from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.id=any(ids);
 return snapshot; end $$;
create function beta_fantasy.score(stats jsonb,p_position text,r jsonb) returns integer language sql immutable set search_path='' as $$
 select case when (stats->>'minutes')::integer=0 then 0 else
 (r->>'appearance')::integer + case when (stats->>'minutes')::integer>=60 then (r->>'sixty_minutes')::integer else 0 end
 +(stats->>'goals')::integer*(r->'goal'->>p_position)::integer +(stats->>'assists')::integer*(r->>'assist')::integer
 +case when (stats->>'minutes')::integer>=60 and (stats->>'conceded')::integer=0 then (r->'clean_sheet'->>p_position)::integer else 0 end
 +case when p_position='GK' then ((stats->>'saves')::integer/(r->>'save_group')::integer)*(r->>'save_points')::integer else 0 end
 +(stats->>'yellow')::integer*(r->>'yellow')::integer +(stats->>'red')::integer*(r->>'red')::integer +(stats->>'own_goals')::integer*(r->>'own_goal')::integer
 +case when p_position in('GK','DEF') then ((stats->>'conceded')::integer/(r->>'conceded_group')::integer)*(r->>'conceded_points')::integer else 0 end end
$$;

create function beta_fantasy.prepare_pack(pack_id uuid,u uuid) returns void language plpgsql set search_path='' as $$
declare pack beta_fantasy.packs; d beta_fantasy.pack_definitions; chosen beta_fantasy.editions; i integer; item record; selected_tier text; slot_position text; weights double precision; draw double precision; cid uuid;
begin
 select * into strict pack from beta_fantasy.packs where id=pack_id and user_id=u;
 select * into strict d from beta_fantasy.pack_definitions where id=pack.definition_id;
   -- Charge only when issuance succeeds. An exhausted pool cannot strand paid credits.
   if d.price>0 then perform beta_fantasy.money('pack',pack.id,array[u::text,'system:pack'],array[-d.price,d.price]); end if;
   for i in 0..jsonb_array_length(d.slots)-1 loop
    slot_position:=d.slots->>i;
    -- Guarantees occupy configured leading slots; other slots use explicit tier weights.
    selected_tier:=d.guarantees->>i::text;
    if selected_tier is null then
     select sum(value::double precision) into weights from jsonb_each_text(d.weights);
     if weights is null or weights<=0 or exists(select 1 from jsonb_each_text(d.weights) where value::double precision<0) then raise exception 'Invalid pack weights'; end if;
     draw:=random()*weights;
     for item in select key,value::double precision as weight from jsonb_each_text(d.weights) order by key loop
      draw:=draw-item.weight; if draw<0 then selected_tier:=item.key; exit; end if;
     end loop;
    end if;
    select a.* into chosen from beta_fantasy.editions a join beta_fantasy.players b on b.id=a.player_id where a.id=any(d.pool) and a.tier=selected_tier and a.status='launched' and a.launch_at<=clock_timestamp() and a.issued<a.max_supply and b.status not in('retired','delisted') and (slot_position='ANY' or b.position=slot_position) and (d.name<>'Starter' or not exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.cards ci on ci.id=pi.card_id join beta_fantasy.editions ei on ei.id=ci.edition_id where pi.pack_id=pack.id and ei.player_id=a.player_id)) order by random() limit 1;
    if not found then raise exception 'Configured pool exhausted; no reroll or debit'; end if;
    cid:=beta_fantasy.mint(chosen.id,u,d.tradeable,case when d.name='Starter' then 'starter' else 'pack' end,pack.id);
    insert into beta_fantasy.pack_items values(pack.id,i,cid);
   end loop;

end $$;

-- Single reviewed mutation entry. Runtime receives EXECUTE only, never table writes.
create function beta_fantasy.command(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid; result jsonb:='{}'; prior beta_fantasy.requests; d beta_fantasy.pack_definitions; pack beta_fantasy.packs; chosen beta_fantasy.editions; l beta_fantasy.listings; tr beta_fantasy.trades; comp beta_fantasy.competitions; item record; i integer; cid uuid; ref uuid; snap jsonb; ids uuid[]; weights double precision; draw double precision; selected_tier text; slot_position text; fee bigint; score_rules jsonb; stats jsonb; n bigint; pid uuid; is_admin boolean;
begin
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.actor(false);
 if request_id is null then raise exception 'Request ID required'; end if;
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=command.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused'; end if; return prior.result; end if;
 is_admin:=action like 'admin_%'; if is_admin then perform beta_fantasy.actor(true); end if;
 if action in('claim_starter','buy_pack') then
  if action='claim_starter' then
   if exists(select 1 from beta_fantasy.packs a join beta_fantasy.pack_definitions b on b.id=a.definition_id where a.user_id=u and b.name='Starter') then raise exception 'Starter already claimed'; end if;
   select * into strict d from beta_fantasy.pack_definitions where name='Starter' and version=1;
  else select * into strict d from beta_fantasy.pack_definitions where id=(p->>'definition_id')::uuid and name not in('Starter','Replacement'); end if;
  if d.status<>'active' or clock_timestamp()<d.starts_at or clock_timestamp()>=d.ends_at or d.sold>=d.max_quantity then raise exception 'Pack unavailable'; end if;
  insert into beta_fantasy.packs(user_id,definition_id,request_id) values(u,d.id,request_id) returning id into ref;
  update beta_fantasy.pack_definitions set sold=sold+1 where id=d.id;
  perform beta_fantasy.prepare_pack(ref,u);
  result:=jsonb_build_object('pack_id',ref);
 elsif action='open_pack' then
  select * into strict pack from beta_fantasy.packs where id=(p->>'pack_id')::uuid and user_id=u;
  if pack.opened_at is null then
   select * into strict d from beta_fantasy.pack_definitions where id=pack.definition_id;
   update beta_fantasy.packs set opened_at=clock_timestamp() where id=pack.id;
   perform beta_fantasy.social(u,'Opened a '||d.name||' pack in Fantasy Cards Preview.');
  end if;
  select jsonb_build_object('pack_id',pack.id,'cards',jsonb_agg(card_id order by slot)) into result from beta_fantasy.pack_items where pack_id=pack.id;
 elsif action='list' then
  cid:=(p->>'card_id')::uuid; perform beta_fantasy.transferable(cid,u);
  insert into beta_fantasy.listings(card_id,seller,price,fee_bps) select cid,u,(p->>'price')::bigint,fee_bps from beta_fantasy.settings returning id into ref;
  perform beta_fantasy.social(u,'Listed a card for test credits in Fantasy Cards Preview.'); result:=jsonb_build_object('listing_id',ref);
 elsif action='cancel_listing' then
  update beta_fantasy.listings set state='cancelled' where id=(p->>'listing_id')::uuid and seller=u and state='active'; if not found then raise exception 'Active owned listing required'; end if;
 elsif action='buy' then
  select * into strict l from beta_fantasy.listings where id=(p->>'listing_id')::uuid;
  if l.state<>'active' or l.seller=u then raise exception 'Listing unavailable'; end if;
  perform beta_fantasy.transferable(l.card_id,l.seller);
  fee:=(l.price*l.fee_bps+5000)/10000;
  insert into beta_fantasy.sales(listing_id,buyer,seller,price,fee) values(l.id,u,l.seller,l.price,fee) returning id into ref;
  perform beta_fantasy.money('sale',ref,array[u::text,l.seller::text,'system:fee'],array[-l.price,l.price-fee,fee]);
  perform beta_fantasy.transfer(l.card_id,l.seller,u,'sale',ref,l.price);
  update beta_fantasy.listings set state='sold' where id=l.id;
  perform beta_fantasy.social(u,'Acquired a card on the test-credit marketplace.');
 elsif action='offer_trade' then
  pid:=(p->>'recipient')::uuid;
  if not exists(select 1 from beta_fantasy.members where user_id=pid and revoked_at is null and expires_at>clock_timestamp()) then raise exception 'Recipient unavailable'; end if;
  if jsonb_array_length(p->'give') not between 1 and 30 or jsonb_array_length(p->'receive') not between 1 and 30 then raise exception 'Both trade sides required'; end if;
  insert into beta_fantasy.trades(sender,recipient) values(u,pid) returning id into ref;
  for item in select value::uuid as id,u as owner from jsonb_array_elements_text(p->'give') union all select value::uuid,pid from jsonb_array_elements_text(p->'receive') loop
   perform beta_fantasy.transferable(item.id,item.owner);
   insert into beta_fantasy.trade_items values(ref,item.id,item.owner);
  end loop; result:=jsonb_build_object('trade_id',ref);
 elsif action in('accept_trade','decline_trade','cancel_trade') then
  select * into strict tr from beta_fantasy.trades where id=(p->>'trade_id')::uuid;
  if tr.state<>'pending' or tr.expires_at<=clock_timestamp() then raise exception 'Trade unavailable or expired'; end if;
  if (action='cancel_trade' and tr.sender<>u) or (action<>'cancel_trade' and tr.recipient<>u) then raise exception 'Trade permission denied'; end if;
  if action='accept_trade' then
   for item in select * from beta_fantasy.trade_items where trade_id=tr.id order by card_id loop perform beta_fantasy.transferable(item.card_id,item.from_user); end loop;
   for item in select * from beta_fantasy.trade_items where trade_id=tr.id order by card_id loop perform beta_fantasy.transfer(item.card_id,item.from_user,case when item.from_user=tr.sender then tr.recipient else tr.sender end,'trade',tr.id); end loop;
   perform beta_fantasy.social(u,'Completed a card trade in Fantasy Cards Preview.');
  end if;
  update beta_fantasy.trades set state=case action when 'accept_trade' then 'accepted' when 'decline_trade' then 'declined' else 'cancelled' end where id=tr.id;
 elsif action='save_lineup' then
  select * into strict comp from beta_fantasy.competitions where id=(p->>'competition_id')::uuid;
  if clock_timestamp()<comp.opens_at or clock_timestamp()>=comp.locks_at or comp.scored_at is not null then raise exception 'Lineup locked or entry closed'; end if;
  select array_agg(value::uuid) into ids from jsonb_array_elements_text(p->'cards'); snap:=beta_fantasy.lineup(comp.id,u,ids);
  insert into beta_fantasy.entries(competition_id,user_id,cards,snapshot) values(comp.id,u,ids,snap) on conflict(competition_id,user_id) do update set cards=excluded.cards,snapshot=excluded.snapshot,updated_at=clock_timestamp();
 elsif action='admin_credit' then
  pid:=(p->>'user_id')::uuid; if not exists(select 1 from beta_fantasy.members where user_id=pid) or (p->>'amount')::bigint not between 1 and 1000000 then raise exception 'Invalid credit grant'; end if;
  perform beta_fantasy.money('admin_credit',request_id,array['system:issuance',pid::text],array[-(p->>'amount')::bigint,(p->>'amount')::bigint]);
 elsif action='admin_status' then
  pid:=(p->>'player_id')::uuid;
  update beta_fantasy.players set status=p->>'status' where id=pid; if not found then raise exception 'Player missing'; end if;
  insert into beta_fantasy.status_events(player_id,status,actor) values(pid,p->>'status',u);
  if p->>'status' in('retired','delisted') then
   -- Before lock, retirement invalidates the saved entry; rebuild explicitly, never substitute.
   delete from beta_fantasy.entries en using beta_fantasy.competitions co where en.competition_id=co.id and co.locks_at>clock_timestamp() and exists(select 1 from jsonb_array_elements(en.snapshot) si where (si->>'player_id')::uuid=pid);
   insert into beta_fantasy.replacements(card_id,user_id) select a.id,a.owner_id from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where e.player_id=pid on conflict do nothing;
  end if;
 elsif action='admin_replacement' then
  cid:=(p->>'card_id')::uuid;
  select user_id into strict pid from beta_fantasy.replacements where card_id=cid and pack_id is null;
  select * into strict d from beta_fantasy.pack_definitions where name='Replacement' and version=1;
  if d.sold>=d.max_quantity then raise exception 'Replacement stock exhausted'; end if;
  insert into beta_fantasy.packs(user_id,definition_id,request_id) values(pid,d.id,request_id) returning id into ref;
  update beta_fantasy.pack_definitions set sold=sold+1 where id=d.id;
  perform beta_fantasy.prepare_pack(ref,pid);
  update beta_fantasy.replacements set pack_id=ref where card_id=cid; result:=jsonb_build_object('pack_id',ref);
 elsif action='admin_simulate' then
  select * into strict comp from beta_fantasy.competitions where id=(p->>'competition_id')::uuid;
  if comp.scored_at is not null or clock_timestamp()<comp.locks_at then raise exception 'Round must be locked and unscored'; end if;
  select rules into strict score_rules from beta_fantasy.scoring_rules where id=comp.scoring_id;
  for item in select a.* from beta_fantasy.players a where sport=comp.sport order by id loop
   n:=('x'||substr(md5((p->>'seed')||':'||item.id::text),1,8))::bit(32)::bigint;
   stats:=jsonb_build_object('minutes',case when item.status='active' then 90 else 0 end,'goals',case when n%7=0 then 1 else 0 end,'assists',case when n%5=0 then 1 else 0 end,'conceded',n%4,'saves',n%8,'yellow',case when n%11=0 then 1 else 0 end,'red',0,'own_goals',0);
   stats:=coalesce((select ri.stats from beta_fantasy.round_inputs ri where ri.competition_id=comp.id and ri.player_id=item.id),stats);
   insert into beta_fantasy.round_scores values(comp.id,item.id,comp.scoring_id,stats,beta_fantasy.score(stats,item.position,score_rules));
  end loop;
  insert into beta_fantasy.results(competition_id,user_id,entry_id,score,rank,championship_points)
  select comp.id,x.user_id,x.id,x.total,x.place,coalesce((comp.awards->>(x.place::integer-1))::integer,0) from (
   select e.id,e.user_id,sum(s.score)::integer total,rank() over(order by sum(s.score) desc)::integer place from beta_fantasy.entries e cross join lateral jsonb_array_elements(e.snapshot) a join beta_fantasy.round_scores s on s.competition_id=e.competition_id and s.player_id=(a->>'player_id')::uuid where e.competition_id=comp.id group by e.id,e.user_id
  ) x;
  update beta_fantasy.competitions set scored_at=clock_timestamp(),seed=(p->>'seed')::integer where id=comp.id;
  for item in select user_id from beta_fantasy.results where competition_id=comp.id and rank=1 loop perform beta_fantasy.social(item.user_id,'Won '||comp.name||' in Fantasy Cards Preview.'); end loop;
 elsif action='admin_stats' then
  if not exists(select 1 from beta_fantasy.competitions co join beta_fantasy.players pl on pl.sport=co.sport where co.id=(p->>'competition_id')::uuid and pl.id=(p->>'player_id')::uuid and co.scored_at is null) then raise exception 'Unscored sport round required'; end if;
  if not ((p->'stats') ?& array['minutes','goals','assists','conceded','saves','yellow','red','own_goals']) or exists(select 1 from jsonb_each_text(p->'stats') x where x.value::integer<0 or x.value::integer>150) then raise exception 'Invalid event statistics'; end if;
  insert into beta_fantasy.round_inputs values((p->>'competition_id')::uuid,(p->>'player_id')::uuid,p->'stats',u) on conflict(competition_id,player_id) do update set stats=excluded.stats,actor=excluded.actor;
 elsif action='admin_scoring' then
  if (p->'rules'->>'save_group')::integer<=0 or (p->'rules'->>'conceded_group')::integer<=0 then raise exception 'Positive scoring divisor required'; end if;
  insert into beta_fantasy.scoring_rules(version,rules)values(p->>'version',p->'rules');
 elsif action='admin_player' then
  if not exists(select 1 from beta_fantasy.sports where id=p->>'sport' and positions ? (p->>'position')) then raise exception 'Sport position invalid'; end if;
  insert into beta_fantasy.players(name,sport,position,team,colour,shirt,first_season,prospect_rank) values(p->>'name',p->>'sport',p->>'position',p->>'team',p->>'colour',(p->>'shirt')::integer,p->>'first_season',(p->>'prospect_rank')::integer) returning id into ref; result:=jsonb_build_object('player_id',ref);
 elsif action='admin_edition' then
  if p->>'kind'='first_year' and not exists(select 1 from beta_fantasy.players where id=(p->>'player_id')::uuid and first_season=p->>'season') then raise exception 'First Year must match first eligible season'; end if;
  insert into beta_fantasy.editions(player_id,tier,season,kind,max_supply,prospect_rank,launch_at,status) values((p->>'player_id')::uuid,p->>'tier',p->>'season',p->>'kind',(p->>'max_supply')::integer,(p->>'prospect_rank')::integer,(p->>'launch_at')::timestamptz,'draft') returning id into ref; result:=jsonb_build_object('edition_id',ref);
 elsif action='admin_lock_edition' then
  update beta_fantasy.editions set locked_at=clock_timestamp(),status='launched' where id=(p->>'edition_id')::uuid and locked_at is null and status='draft'; if not found then raise exception 'Unlocked draft edition required'; end if;
 elsif action='admin_pack' then
  select array_agg(value::uuid) into ids from jsonb_array_elements_text(p->'pool');
  if cardinality(ids) is null or cardinality(ids)=0 or exists(select 1 from unnest(ids) x where not exists(select 1 from beta_fantasy.editions where id=x and status='launched')) then raise exception 'Launched edition pool required'; end if;
  if exists(select 1 from jsonb_each_text(p->'weights') w where w.value::numeric<0 or not exists(select 1 from beta_fantasy.tiers where id=w.key)) or (select sum(value::numeric) from jsonb_each_text(p->'weights'))<>100 then raise exception 'Tier probabilities must sum to 100'; end if;
  for item in select key,value from jsonb_each_text(coalesce(p->'guarantees','{}')) loop
   if item.key !~ '^[0-9]+$' or item.key::integer>=jsonb_array_length(p->'slots') or not exists(select 1 from beta_fantasy.tiers where id=item.value) then raise exception 'Invalid guarantee slot'; end if;
  end loop;
  insert into beta_fantasy.pack_definitions(name,version,slots,pool,weights,guarantees,price,max_quantity,tradeable,starts_at,ends_at) values(p->>'name',(p->>'version')::integer,p->'slots',ids,p->'weights',coalesce(p->'guarantees','{}'),(p->>'price')::bigint,(p->>'max_quantity')::integer,(p->>'tradeable')::boolean,(p->>'starts_at')::timestamptz,(p->>'ends_at')::timestamptz) returning id into ref;result:=jsonb_build_object('definition_id',ref);
 elsif action='admin_fee' then
  update beta_fantasy.settings set fee_bps=(p->>'fee_bps')::integer;
 elsif action='admin_competition' then
  insert into beta_fantasy.competitions(name,sport,season,round,locks_at,rules,scoring_id) values(p->>'name','football',p->>'season',(p->>'round')::integer,(p->>'locks_at')::timestamptz,p->'rules',(select id from beta_fantasy.scoring_rules where version=coalesce(p->>'scoring_version','football-demo-v1'))) returning id into ref; result:=jsonb_build_object('competition_id',ref);
 else raise exception 'Unknown fantasy action'; end if;
 if is_admin then insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p); end if;
 insert into beta_fantasy.requests values(u,request_id,action,p,result);
 return result;
end $$;

create function beta_fantasy.read_state() returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid; result jsonb; begin
 u:=beta_fantasy.actor(false);
 select jsonb_build_object(
 'user_id',u,'credits',beta_fantasy.balance(u),'admin',coalesce(auth.jwt()->>'aal','')='aal2' and exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin')),
 'fee_bps',(select fee_bps from beta_fantasy.settings),
 'catalog',case when coalesce(auth.jwt()->>'aal','')='aal2' and exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin')) then jsonb_build_object('players',(select jsonb_agg(to_jsonb(p)) from beta_fantasy.players p),'editions',(select jsonb_agg(to_jsonb(e)) from beta_fantasy.editions e),'replacements',(select jsonb_agg(to_jsonb(r)) from beta_fantasy.replacements r),'sales',(select jsonb_agg(to_jsonb(s)) from beta_fantasy.sales s),'ownership',(select jsonb_agg(to_jsonb(o)) from beta_fantasy.ownership_events o)) else null end,
 'cards',coalesce((select jsonb_agg(to_jsonb(x)) from (select a.*,e.tier,e.season,e.kind,e.max_supply,e.player_id,p.name,p.position,p.team,p.colour,p.shirt,p.status,p.sport,exists(select 1 from beta_fantasy.listings l where l.card_id=a.id and l.state='active') as listed,(select max(created_at) from beta_fantasy.ownership_events o where o.card_id=a.id and o.to_user=u) as acquired_at from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.owner_id=u and not exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.packs pa on pa.id=pi.pack_id where pi.card_id=a.id and pa.opened_at is null) order by a.created_at desc) x),'[]'),
 'packs',coalesce((select jsonb_agg(to_jsonb(x)) from (select a.*,d.name,d.slots,case when a.opened_at is not null then (select jsonb_agg(card_id order by slot) from beta_fantasy.pack_items where pack_id=a.id) else null end as cards from beta_fantasy.packs a join beta_fantasy.pack_definitions d on d.id=a.definition_id where a.user_id=u order by a.created_at desc) x),'[]'),
 'shop',coalesce((select jsonb_agg(to_jsonb(d)) from beta_fantasy.pack_definitions d where name<>'Replacement'),'[]'),
 'market',coalesce((select jsonb_agg(to_jsonb(x)) from (select l.*,e.tier,e.season,e.kind,e.max_supply,p.name,p.position,p.status,a.serial from beta_fantasy.listings l join beta_fantasy.cards a on a.id=l.card_id join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where l.state='active') x),'[]'),
 'trades',coalesce((select jsonb_agg(to_jsonb(t)||jsonb_build_object('items',(select jsonb_agg(to_jsonb(i)) from beta_fantasy.trade_items i where i.trade_id=t.id))) from beta_fantasy.trades t where u in(t.sender,t.recipient)),'[]'),
 'competitions',coalesce((select jsonb_agg(to_jsonb(c)) from beta_fantasy.competitions c),'[]'),
 'entries',coalesce((select jsonb_agg(to_jsonb(e)) from beta_fantasy.entries e where user_id=u),'[]'),
 'results',coalesce((select jsonb_agg(to_jsonb(r)) from beta_fantasy.results r),'[]'),
 'ledger',coalesce((select jsonb_agg(to_jsonb(x)) from (select l.*,j.reason from beta_fantasy.ledger l join beta_fantasy.journals j on j.id=l.journal_id where account=u::text order by l.created_at desc limit 100) x),'[]'),
 'provenance',coalesce((select jsonb_agg(to_jsonb(o)) from beta_fantasy.ownership_events o where o.card_id in(select id from beta_fantasy.cards where owner_id=u)),'[]'),
 'members',coalesce((select jsonb_agg(jsonb_build_object('id',m.user_id,'name',coalesce(s.display_name,'Preview member'))) from beta_fantasy.members m left join beta_private.social_profiles s on s.user_id=m.user_id and s.visibility='members' and s.status='active' where m.revoked_at is null and m.expires_at>clock_timestamp()),'[]'),
 'replacements',coalesce((select jsonb_agg(to_jsonb(r)) from beta_fantasy.replacements r where user_id=u),'[]')
 ) into result; return result; end $$;

-- Fictional, deterministic catalog only. No users or credits are seeded by migration.
insert into beta_fantasy.players(id,name,sport,position,team,colour,shirt,first_season,prospect_rank)
select ('f1000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,
 (array['Noah','Arlo','Finn','Milo','Oscar','Theo','Jude','Ezra','Luca'])[1+(i-1)%9]||' '||(array['Vale','Rowan','Brook','Hart'])[1+(i-1)/9],
 'football',case when i<=4 then 'GK' when i<=16 then 'DEF' when i<=28 then 'MID' else 'FWD' end,
 (array['Harbour Blue','Valley Violet','Northern Red','Coastal Gold'])[1+(i-1)%4],(array['#1A2AFF','#8B3DFF','#E34C64','#E5B755'])[1+(i-1)%4],i,'2027',i from generate_series(1,36) i;
insert into beta_fantasy.editions(player_id,tier,season,kind,max_supply,prospect_rank,status) select p.id,t.id,'2027','first_year',t.reference_supply,p.prospect_rank,'launched' from beta_fantasy.players p cross join beta_fantasy.tiers t;
insert into beta_fantasy.pack_definitions(name,slots,pool,weights,guarantees,price,max_quantity,tradeable)
select 'Starter','["GK","DEF","DEF","DEF","DEF","MID","MID","MID","MID","FWD","FWD"]',array_agg(e.id),'{"CORE":1}','{}',0,3,false from beta_fantasy.editions e where tier='CORE';
-- Starter pool slots must not repeat player identities within a pack; enforced below.
insert into beta_fantasy.pack_definitions(name,slots,pool,weights,guarantees,price,max_quantity,tradeable)
select x.name,to_jsonb(array_fill('ANY'::text,array[x.size])),array_agg(e.id),x.weights::jsonb,x.guarantees::jsonb,x.price,100,true from beta_fantasy.editions e cross join (values('Matchday',5,100,'{"CORE":75,"RARE":20,"ELITE":5}','{}'),('Pro',7,200,'{"CORE":50,"RARE":35,"ELITE":14,"LEGENDARY":1}','{"0":"RARE"}'),('Elite',9,400,'{"CORE":30,"RARE":40,"ELITE":25,"LEGENDARY":4,"ICON":1}','{"0":"ELITE"}'),('Replacement',1,0,'{"CORE":1}','{}')) x(name,size,price,weights,guarantees) group by x.name,x.size,x.price,x.weights,x.guarantees;
insert into beta_fantasy.competitions(name,sport,season,round,locks_at,rules,scoring_id) select n.name,'football','2027',1,clock_timestamp()+interval '7 days',n.rules::jsonb,r.id from beta_fantasy.scoring_rules r cross join (values('Rookie League','{"tier_max":{"ELITE":1,"LEGENDARY":0,"ICON":0},"core_min":5,"first_year_min":3}'),('Challenger','{"tier_max":{"ELITE":2,"LEGENDARY":1,"ICON":0}}'),('Open League','{}')) n(name,rules) where r.version='football-demo-v1';
revoke all on all functions in schema beta_fantasy from public,anon,authenticated,docked_beta_app;
grant usage on schema beta_fantasy to docked_beta_app;
grant execute on function beta_fantasy.command(text,jsonb,uuid),beta_fantasy.read_state() to docked_beta_app;





-- SOURCE 20261007234952_fantasy_free_play_production.sql sha256=38e1181f33889e94512167854c1bc50bd45e7dbef79c9111d893d5f5b3cb67c2
-- Additive, dormant by default. Applying this migration never promotes Preview.
alter table beta_fantasy.settings add column deployment_mode text not null default 'preview' check(deployment_mode in('preview','production'));
alter table beta_fantasy.settings add column production_ref text;
alter table beta_fantasy.settings add column terms_version text;
alter table beta_fantasy.settings add column privacy_version text;
alter table beta_fantasy.settings add constraint production_metadata_required check(deployment_mode<>'production' or (production_ref is not null and production_ref ~ '^[a-z]{20}$' and terms_version is not null and privacy_version is not null));
alter table beta_fantasy.competitions drop constraint competitions_prize_check;
alter table beta_fantasy.competitions add constraint competitions_prize_check check(prize in('Preview/Test Prize','No cash prize'));
create table beta_fantasy.production_policy(version integer generated always as identity primary key, daily_points integer not null check(daily_points between 1 and 50), card_every integer not null check(card_every between 7 and 365), daily_card_limit integer not null check(daily_card_limit between 0 and 100), created_at timestamptz not null default clock_timestamp(), actor uuid);
create table beta_fantasy.production_catalog(id boolean primary key default true check(id), starter_definition uuid not null references beta_fantasy.pack_definitions, reward_definition uuid not null references beta_fantasy.pack_definitions);
create table beta_fantasy.production_definitions(definition_id uuid primary key references beta_fantasy.pack_definitions, kind text not null check(kind in('starter','reward')));
create table beta_fantasy.starter_claims(user_id uuid primary key references beta_fantasy.members, pack_id uuid not null unique references beta_fantasy.packs, created_at timestamptz not null default clock_timestamp());
create table beta_fantasy.daily_claims(id uuid primary key default gen_random_uuid(), user_id uuid not null references beta_fantasy.members, period date not null, points integer not null check(points between 1 and 50), policy_version integer not null references beta_fantasy.production_policy, pack_id uuid unique references beta_fantasy.packs, card_outcome text not null check(card_outcome in('not_due','awarded','stock_unavailable','daily_limit')), created_at timestamptz not null default clock_timestamp(), unique(user_id,period));
create table beta_fantasy.production_rounds(competition_id uuid primary key references beta_fantasy.competitions);
create index on beta_fantasy.daily_claims(period) where pack_id is not null;
create index on beta_fantasy.cards(owner_id,created_at);
create index on beta_fantasy.ownership_events(card_id,created_at);
create index on beta_fantasy.packs(user_id,created_at);
create index on beta_fantasy.pack_items(pack_id,slot);
do $$ declare n text; begin
 foreach n in array array['production_policy','production_catalog','production_definitions','starter_claims','daily_claims','production_rounds'] loop
  execute format('alter table beta_fantasy.%I enable row level security',n);
  execute format('revoke all on beta_fantasy.%I from public,anon,authenticated,docked_beta_app',n);
  if n<>'production_catalog' then execute format('create trigger immutable before update or delete on beta_fantasy.%I for each row execute function beta_fantasy.immutable()',n); end if;
 end loop;
end $$;

-- Keep the original Preview implementations and restrict entry by database mode.
alter function beta_fantasy.actor(boolean) rename to preview_actor;
alter function beta_fantasy.command(text,jsonb,uuid) rename to preview_command;
do $$ begin execute replace(pg_get_functiondef('beta_fantasy.preview_command(text,jsonb,uuid)'::regprocedure),'command.request_id','preview_command.request_id'); end $$;
alter function beta_fantasy.read_state() rename to preview_read_state;
create function beta_fantasy.production_eligible() returns uuid language plpgsql set search_path='' as $$
declare u uuid:=auth.uid(); s beta_fantasy.settings; begin
 select * into strict s from beta_fantasy.settings;
 if s.deployment_mode<>'production' or not s.enabled or current_setting('docked.fantasy_production',true) is distinct from s.production_ref or coalesce(current_setting('docked.fantasy_preview',true),'')<>'' then raise exception 'Production Fantasy context required'; end if;
 perform 1 from beta_public.profiles where id=u for share;
 if not beta_private.active_member_session() or not exists(select 1 from beta_public.profiles where id=u and disabled_at is null and age_attested and accepted_version=s.terms_version) then raise exception 'Verified current-consent account required'; end if;
 if not coalesce((select granted and version=s.privacy_version from beta_private.consent_events where user_id=u and purpose='privacy' order by created_at desc,id desc limit 1),false) then raise exception 'Current privacy consent required'; end if;
 if exists(select 1 from auth.users au where au.id=u and (to_jsonb(au)->>'banned_until')::timestamptz>clock_timestamp()) then raise exception 'Account banned'; end if;
 return u;
end $$;
create function beta_fantasy.actor(admin_required boolean default false) returns uuid language plpgsql set search_path='' as $$ declare u uuid; begin
 if (select deployment_mode from beta_fantasy.settings)='preview' then
  if coalesce(current_setting('docked.fantasy_production',true),'')<>'' then raise exception 'Production context forbidden in Preview'; end if;
  return beta_fantasy.preview_actor(admin_required);
 end if;
 u:=beta_fantasy.production_eligible();
 if not exists(select 1 from beta_fantasy.members where user_id=u and revoked_at is null and expires_at>clock_timestamp()) then raise exception 'Production membership required'; end if;
 if admin_required and (coalesce(auth.jwt()->>'aal','')<>'aal2' or not exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin'))) then raise exception 'Admin MFA required'; end if;
 return u;
end $$;
create or replace function beta_fantasy.member_guard() returns trigger language plpgsql set search_path='' as $$ begin
 perform pg_advisory_xact_lock(71820342);
 if (select deployment_mode from beta_fantasy.settings)='preview' and new.revoked_at is null and new.expires_at>clock_timestamp() and (select count(*) from beta_fantasy.members where user_id<>new.user_id and revoked_at is null and expires_at>clock_timestamp())>=3 then raise exception 'Preview limited to three members'; end if;
 return new;
end $$;
create function beta_fantasy.command(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ begin
 if (select deployment_mode from beta_fantasy.settings)<>'preview' then raise exception 'Preview commands disabled in production'; end if;
 return beta_fantasy.preview_command(action,p,request_id);
end $$;
create function beta_fantasy.read_state() returns jsonb language plpgsql security definer set search_path='' as $$ begin
 if (select deployment_mode from beta_fantasy.settings)<>'preview' then raise exception 'Preview state disabled in production'; end if;
 return beta_fantasy.preview_read_state();
end $$;

-- Called only by a verified migration operator on an unused Fantasy installation.
-- It neither changes existing Edge tables nor copies any Preview accounts/data.
create function beta_fantasy.initialize_production(project_ref text,terms text,privacy text) returns void language plpgsql set search_path='' as $$
declare starter uuid; reward uuid; comp uuid; scoring uuid; begin
 perform pg_advisory_xact_lock(71820342);
 if project_ref is null or terms is null or privacy is null or project_ref !~ '^[a-z]{20}$' or project_ref in('bckkllmndoxzpzdqrevb','dwdjeecjdkkiidoutnme') or terms !~ '^[a-zA-Z0-9][a-zA-Z0-9._-]{2,79}$' or privacy !~ '^[a-zA-Z0-9][a-zA-Z0-9._-]{2,79}$' or terms ~* '(draft|preview|fixture|pending|unapproved|placeholder)' or privacy ~* '(draft|preview|fixture|pending|unapproved|placeholder)' then raise exception 'Reviewed production identity and policy versions required'; end if;
 if (select deployment_mode from beta_fantasy.settings)<>'preview' or exists(select 1 from beta_fantasy.members) or exists(select 1 from beta_fantasy.cards) or exists(select 1 from beta_fantasy.journals) or exists(select 1 from beta_fantasy.entries) then raise exception 'Clean production Fantasy installation required'; end if;
 insert into beta_fantasy.pack_definitions(name,version,slots,pool,weights,guarantees,price,max_quantity,tradeable,ends_at)
 select 'Starter',2,'["GK","DEF","DEF","DEF","DEF","MID","MID","MID","MID","FWD","FWD"]',array_agg(id),'{"CORE":100}','{}',0,1000,false,clock_timestamp()+interval '100 years' from beta_fantasy.editions where tier='CORE' returning id into starter;
 insert into beta_fantasy.pack_definitions(name,slots,pool,weights,guarantees,price,max_quantity,tradeable,ends_at)
 select 'Daily reward', '["ANY"]',array_agg(id),'{"CORE":100}','{}',0,10000,false,clock_timestamp()+interval '100 years' from beta_fantasy.editions where tier='CORE' returning id into reward;
 insert into beta_fantasy.production_catalog values(true,starter,reward);
 insert into beta_fantasy.production_definitions values(starter,'starter'),(reward,'reward');
 insert into beta_fantasy.production_policy(daily_points,card_every,daily_card_limit) values(10,7,100);
 insert into beta_fantasy.scoring_rules(version,rules) select 'football-free-play-v1',rules from beta_fantasy.scoring_rules where version='football-demo-v1' returning id into scoring;
 insert into beta_fantasy.competitions(name,sport,season,round,locks_at,rules,scoring_id,prize) values('Free football league','football','2027',1,clock_timestamp()+interval '7 days','{"duplicates":false}',scoring,'No cash prize') returning id into comp;
 insert into beta_fantasy.production_rounds values(comp);
 update beta_fantasy.settings set deployment_mode='production',production_ref=project_ref,terms_version=terms,privacy_version=privacy,enabled=true;
end $$;
create function beta_fantasy.production_pack(definition uuid,u uuid) returns uuid language plpgsql set search_path='' as $$ declare d beta_fantasy.pack_definitions; pack uuid; begin
 select * into strict d from beta_fantasy.pack_definitions where id=definition for update;
 if d.price<>0 or d.tradeable or d.status<>'active' or clock_timestamp()<d.starts_at or clock_timestamp()>=d.ends_at or d.sold>=d.max_quantity then raise exception 'Free pack unavailable'; end if;
 insert into beta_fantasy.packs(user_id,definition_id,request_id) values(u,d.id,gen_random_uuid()) returning id into pack;
 update beta_fantasy.pack_definitions set sold=sold+1 where id=d.id;
 perform beta_fantasy.prepare_pack(pack,u);
 return pack;
end $$;
create function beta_fantasy.production_command(action text,p jsonb,request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid; prior beta_fantasy.requests; result jsonb; pack uuid; comp_id uuid; definition uuid; previous beta_fantasy.pack_definitions; policy beta_fantasy.production_policy; claim beta_fantasy.daily_claims; period_key date; outcome text:='not_due'; count_claims integer; begin
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.production_eligible();
 if request_id is null or p is null or jsonb_typeof(p)<>'object' then raise exception 'Request ID and payload required'; end if;
 if action is null or action not in('claim_starter','claim_daily','open_pack','save_lineup','admin_reward_policy','admin_stats','admin_simulate','admin_free_round','admin_starter_stock') then raise exception 'Action unavailable in free-play production'; end if;
 insert into beta_fantasy.members(user_id,expires_at) values(u,'infinity') on conflict(user_id) do nothing;
 perform beta_fantasy.actor(action like 'admin_%');
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=production_command.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused'; end if; return prior.result; end if;
 if action in('open_pack','save_lineup','admin_stats','admin_simulate') then
  if action<>'open_pack' and not exists(select 1 from beta_fantasy.production_rounds where competition_id=(p->>'competition_id')::uuid) then raise exception 'Production round required'; end if;
  if action='open_pack' and not exists(select 1 from beta_fantasy.packs pa join beta_fantasy.production_definitions pd on pa.definition_id=pd.definition_id where pa.id=(p->>'pack_id')::uuid and pa.user_id=u) then raise exception 'Own production pack required'; end if;
  return beta_fantasy.preview_command(action,p,request_id);
 elsif action='claim_starter' then
  if p<>'{}'::jsonb then raise exception 'Starter payload must be empty'; end if;
  select pack_id into pack from beta_fantasy.starter_claims where user_id=u;
  if pack is null then
   pack:=beta_fantasy.production_pack((select starter_definition from beta_fantasy.production_catalog),u);
   insert into beta_fantasy.starter_claims values(u,pack,clock_timestamp());
  end if;
  result:=jsonb_build_object('pack_id',pack);
 elsif action='claim_daily' then
  if p<>'{}'::jsonb then raise exception 'Daily payload must be empty'; end if;
  if not exists(select 1 from beta_fantasy.starter_claims where user_id=u) then raise exception 'Claim starter before daily rewards'; end if;
  period_key:=(clock_timestamp() at time zone 'UTC')::date;
  select * into claim from beta_fantasy.daily_claims where user_id=u and period=period_key;
  if not found then
   select * into strict policy from beta_fantasy.production_policy order by version desc limit 1;
   select count(*)+1 into count_claims from beta_fantasy.daily_claims where user_id=u;
   if count_claims%policy.card_every=0 then
    if (select count(*) from beta_fantasy.daily_claims where period=period_key and pack_id is not null)>=policy.daily_card_limit then outcome:='daily_limit';
    else
     -- Only expected stock exhaustion falls back to points; unexpected failures abort.
     if exists(select 1 from beta_fantasy.pack_definitions d join beta_fantasy.production_catalog pc on pc.reward_definition=d.id where d.price=0 and not d.tradeable and d.sold<d.max_quantity and d.status='active' and clock_timestamp()>=d.starts_at and clock_timestamp()<d.ends_at and exists(select 1 from beta_fantasy.editions e join beta_fantasy.players pl on pl.id=e.player_id where e.id=any(d.pool) and e.tier='CORE' and e.status='launched' and e.launch_at<=clock_timestamp() and e.issued<e.max_supply and pl.status not in('retired','delisted'))) then
      pack:=beta_fantasy.production_pack((select reward_definition from beta_fantasy.production_catalog),u); outcome:='awarded';
     else outcome:='stock_unavailable'; end if;
    end if;
   end if;
   insert into beta_fantasy.daily_claims(user_id,period,points,policy_version,pack_id,card_outcome) values(u,period_key,policy.daily_points,policy.version,pack,outcome) returning * into claim;
  end if;
  result:=jsonb_build_object('claim_id',claim.id,'period',claim.period,'points',claim.points,'pack_id',claim.pack_id,'card_outcome',claim.card_outcome);
 elsif action='admin_starter_stock' then
  if p->>'quantity' is null or (select count(*) from jsonb_object_keys(p))<>1 or (p->>'quantity')::integer not between 1 and 1000 then raise exception 'Bounded starter quantity required'; end if;
  select d.* into strict previous from beta_fantasy.pack_definitions d join beta_fantasy.production_catalog pc on pc.starter_definition=d.id;
  if previous.sold<previous.max_quantity then raise exception 'Existing starter allocation must be exhausted'; end if;
  insert into beta_fantasy.pack_definitions(name,version,slots,pool,weights,guarantees,price,max_quantity,tradeable,ends_at)
   values('Starter',previous.version+1,previous.slots,previous.pool,previous.weights,previous.guarantees,0,(p->>'quantity')::integer,false,previous.ends_at) returning id into definition;
  insert into beta_fantasy.production_definitions values(definition,'starter');
  update beta_fantasy.production_catalog set starter_definition=definition;
  result:=jsonb_build_object('definition_id',definition);
  insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p);
 elsif action='admin_free_round' then
  if not (p ?& array['name','season','round','locks_at']) or (select count(*) from jsonb_object_keys(p))<>4 or length(p->>'name') not between 2 and 80 or length(p->>'season') not between 1 and 20 or (p->>'round')::integer not between 1 and 1000 or (p->>'locks_at')::timestamptz<=clock_timestamp() or (p->>'locks_at')::timestamptz>clock_timestamp()+interval '90 days' then raise exception 'Valid future free round required'; end if;
  insert into beta_fantasy.competitions(name,sport,season,round,locks_at,rules,scoring_id,prize) values(p->>'name','football',p->>'season',(p->>'round')::integer,(p->>'locks_at')::timestamptz,'{"duplicates":false}',(select id from beta_fantasy.scoring_rules where version='football-free-play-v1'),'No cash prize') returning id into comp_id;
  insert into beta_fantasy.production_rounds values(comp_id);
  result:=jsonb_build_object('competition_id',comp_id);
  insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p);
 else
  if not (p ?& array['daily_points','card_every','daily_card_limit']) or (select count(*) from jsonb_object_keys(p))<>3 then raise exception 'Exact reward policy required'; end if;
  insert into beta_fantasy.production_policy(daily_points,card_every,daily_card_limit,actor) values((p->>'daily_points')::integer,(p->>'card_every')::integer,(p->>'daily_card_limit')::integer,u) returning jsonb_build_object('version',version) into result;
  insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p);
 end if;
 insert into beta_fantasy.requests values(u,request_id,action,p,result);
 return result;
end $$;

create function beta_fantasy.production_read_state() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid; t timestamptz:=clock_timestamp(); result jsonb; begin
 u:=beta_fantasy.production_eligible();
 if exists(select 1 from beta_fantasy.members where user_id=u and (revoked_at is not null or expires_at<=clock_timestamp())) then raise exception 'Membership inactive'; end if;
 select jsonb_build_object('mode','production','user_id',u,'credits',0,'fee_bps',0,'admin',coalesce(auth.jwt()->>'aal','')='aal2' and exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin')),'catalog',null,
 'cards',coalesce((select jsonb_agg(to_jsonb(x)) from (select a.*,e.tier,e.season,e.kind,e.max_supply,e.player_id,p.name,p.position,p.team,p.colour,p.shirt,p.status,p.sport,false as listed,a.created_at as acquired_at from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.owner_id=u and not exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.packs pa on pa.id=pi.pack_id where pi.card_id=a.id and pa.opened_at is null) order by a.created_at desc limit 1000) x),'[]'),
 'packs',coalesce((select jsonb_agg(to_jsonb(x)) from (select a.*,d.name,d.slots,case when a.opened_at is not null then (select jsonb_agg(card_id order by slot) from beta_fantasy.pack_items where pack_id=a.id) else null end as cards from beta_fantasy.packs a join beta_fantasy.pack_definitions d on d.id=a.definition_id where a.user_id=u order by a.created_at desc limit 1000) x),'[]'),
 'shop','[]'::jsonb,'market','[]'::jsonb,'trades','[]'::jsonb,'ledger','[]'::jsonb,'replacements','[]'::jsonb,
 'competitions',coalesce((select jsonb_agg(to_jsonb(c)-'prize') from (select co.* from beta_fantasy.competitions co join beta_fantasy.production_rounds pr on pr.competition_id=co.id order by co.locks_at desc limit 50)c),'[]'),
 'entries',coalesce((select jsonb_agg(to_jsonb(e)) from (select * from beta_fantasy.entries where user_id=u order by updated_at desc limit 50)e),'[]'),
 'results',coalesce((select jsonb_agg(to_jsonb(r)) from (select r.* from beta_fantasy.results r join beta_fantasy.production_rounds pr on pr.competition_id=r.competition_id where r.user_id=u order by r.competition_id limit 100)r),'[]'),
 'provenance',coalesce((select jsonb_agg(to_jsonb(o)) from (select o.* from beta_fantasy.ownership_events o join beta_fantasy.cards c on c.id=o.card_id where c.owner_id=u order by o.created_at desc limit 1000)o),'[]'),
 'members',jsonb_build_array(jsonb_build_object('id',u,'name','You')),
 'rewards',jsonb_build_object('server_time',t,'period_timezone','UTC','next_claim_at',case when exists(select 1 from beta_fantasy.daily_claims where user_id=u and period=(t at time zone 'UTC')::date) then ((t at time zone 'UTC')::date+1)::timestamp at time zone 'UTC' else t end,'claimed_today',exists(select 1 from beta_fantasy.daily_claims where user_id=u and period=(t at time zone 'UTC')::date),'points',coalesce((select sum(points) from beta_fantasy.daily_claims where user_id=u),0),'starter_claimed',exists(select 1 from beta_fantasy.starter_claims where user_id=u),'policy',(select to_jsonb(p)-'actor' from beta_fantasy.production_policy p order by version desc limit 1),'history',coalesce((select jsonb_agg(to_jsonb(h)) from (select period,points,policy_version,pack_id,card_outcome,created_at from beta_fantasy.daily_claims where user_id=u order by period desc limit 90)h),'[]'))
 ) into result;
 return result;
end $$;

create or replace function beta_fantasy.social(u uuid,body text) returns void language plpgsql set search_path='' as $$ declare sid uuid; begin
 select id into sid from beta_private.social_profiles where user_id=u and status='active' and visibility='members';
 if sid is not null and beta_private.community_feature_allowed(u,'community_social') then
  insert into beta_private.social_posts(author_id,kind,body,sport) values(sid,'celebration',case when (select deployment_mode from beta_fantasy.settings)='production' then replace(body,'Fantasy Cards Preview','Fantasy Cards') else body end,'football');
 end if;
end $$;
-- No direct runtime access to legacy helpers or production bootstrap.
revoke all on all functions in schema beta_fantasy from public,anon,authenticated,docked_beta_app;
grant execute on function beta_fantasy.command(text,jsonb,uuid),beta_fantasy.read_state(),beta_fantasy.production_command(text,jsonb,uuid),beta_fantasy.production_read_state() to docked_beta_app;


-- SOURCE 20261008145441_nfl_community_catalogue.sql sha256=1d12c2e8e8f6430304ef68a23348aef452862b29f43942fadd192e7c415fb478
-- Catalogue identities for community tags only. No feed, price, settlement,
-- fantasy inventory, region policy or publication authority is granted.
insert into beta_private.sports(id,name,enabled)
values('nfl','American football',false) on conflict(id) do nothing;

insert into beta_private.competitions(id,sport_id,enabled,rules)
values('americanfootball_nfl','nfl',false,
  '{"catalogueOnly":true,"marketScope":"fixtures_only"}'::jsonb)
on conflict(id) do nothing;

do $$ begin
  if not exists(select 1 from beta_private.competitions
    where id='americanfootball_nfl' and sport_id='nfl') then
    raise exception 'NFL catalogue identity mismatch';
  end if;
end $$;


-- SOURCE 20261008151700_fantasy_beta_result_isolation.sql sha256=d92df78cd30ec567335a47d2ef0177cd0f2220326873960c660d4b1c13d23e5c
-- Dormant in Preview. Release history is append-only and operator-only.
create table beta_fantasy.production_releases(
  id bigint generated always as identity primary key,
  channel text not null check(channel in('beta','stable')),
  created_at timestamptz not null default clock_timestamp()
);
alter table beta_fantasy.production_releases enable row level security;
revoke all on beta_fantasy.production_releases from public,anon,authenticated,docked_beta_app;
create trigger immutable before update or delete on beta_fantasy.production_releases
  for each row execute function beta_fantasy.immutable();
create function beta_fantasy.release_insert_guard() returns trigger language plpgsql set search_path='' as $$ begin
  perform pg_advisory_xact_lock(71820342);
  return new;
end $$;
create trigger release_lock before insert on beta_fantasy.production_releases
  for each row execute function beta_fantasy.release_insert_guard();
insert into beta_fantasy.production_releases(channel) values('beta');
create function beta_fantasy.production_channel() returns text language sql stable set search_path='' as $$
  select channel from beta_fantasy.production_releases order by id desc limit 1
$$;

-- Existing records remain explicitly legacy; never relabel prior results beta/official.
alter table beta_fantasy.production_rounds add column release_channel text not null default 'legacy'
  check(release_channel in('legacy','beta','stable'));
alter table beta_fantasy.production_rounds alter column release_channel set default beta_fantasy.production_channel();
alter table beta_fantasy.daily_claims add column release_channel text not null default 'legacy'
  check(release_channel in('legacy','beta','stable'));
alter table beta_fantasy.daily_claims alter column release_channel set default beta_fantasy.production_channel();

alter function beta_fantasy.production_eligible() rename to production_eligible_v1;
create function beta_fantasy.production_eligible() returns uuid language plpgsql set search_path='' as $$ begin
  if current_setting('docked.fantasy_channel',true) is distinct from beta_fantasy.production_channel() then
    raise exception 'Production release channel mismatch';
  end if;
  return beta_fantasy.production_eligible_v1();
end $$;
alter function beta_fantasy.production_command(text,jsonb,uuid) rename to production_command_v1;
do $$ begin
  execute replace(pg_get_functiondef('beta_fantasy.production_command_v1(text,jsonb,uuid)'::regprocedure),
    'production_command.request_id','production_command_v1.request_id');
end $$;
create function beta_fantasy.production_command(action text,p jsonb,request_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$ declare u uuid; begin
  perform pg_advisory_xact_lock(71820342);
  u:=beta_fantasy.production_eligible();
  -- Recover a committed result after a release transition. The original entry
  -- point still checks current membership/MFA and exact action/payload identity.
  if exists(select 1 from beta_fantasy.requests q where q.user_id=u and q.request_id=production_command.request_id) then
    return beta_fantasy.production_command_v1(action,p,request_id);
  end if;
  if action in('save_lineup','admin_stats','admin_simulate') and not exists(
    select 1 from beta_fantasy.production_rounds where competition_id=(p->>'competition_id')::uuid
      and release_channel=beta_fantasy.production_channel()) then
    raise exception 'Current release round required';
  end if;
  return beta_fantasy.production_command_v1(action,p,request_id);
end $$;

alter function beta_fantasy.production_read_state() rename to production_read_state_v1;
create function beta_fantasy.production_read_state() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid; ch text; state jsonb; board jsonb; sid uuid; begin
  perform pg_advisory_xact_lock(71820342);
  u:=beta_fantasy.production_eligible(); ch:=beta_fantasy.production_channel();
  state:=beta_fantasy.production_read_state_v1();
  select id into sid from beta_private.social_profiles where user_id=u and status='active';
  with visible as (
    select u user_id,u display_id,'You'::text name
    union all
    select sp.user_id,sp.id,sp.display_name
    from beta_private.social_profiles sp
    join beta_fantasy.members m on m.user_id=sp.user_id and m.revoked_at is null and m.expires_at>clock_timestamp()
    join beta_public.profiles p on p.id=sp.user_id and p.disabled_at is null
    where sp.user_id<>u and sid is not null and sp.status='active' and sp.visibility='members'
      and beta_private.community_feature_allowed(u,'community_social')
      and beta_private.community_feature_allowed(sp.user_id,'community_social')
      and beta_private.community_feature_allowed(u,'leaderboards')
      and beta_private.community_feature_allowed(sp.user_id,'leaderboards')
      and beta_private.community_feature_allowed(u,'public_profiles')
      and beta_private.community_feature_allowed(sp.user_id,'public_profiles')
      and beta_private.social_profile_visible(sid,sp.id,false)
  ), totals as (
    select v.display_id id,v.name,coalesce(sum(r.championship_points),0)::bigint points
    from visible v left join (beta_fantasy.results r join beta_fantasy.production_rounds pr
      on pr.competition_id=r.competition_id and pr.release_channel=ch) on r.user_id=v.user_id
    group by v.display_id,v.name
  ), ranked as (
    select *,dense_rank() over(order by points desc) rank from totals
  ) select coalesce(jsonb_agg(to_jsonb(x) order by x.points desc,x.id),'[]') into board
    from (select * from ranked order by points desc,id limit 100) x;
  state:=state || jsonb_build_object(
    'release_channel',ch,
    'my_championship_points',coalesce((select sum(r.championship_points) from beta_fantasy.results r
      join beta_fantasy.production_rounds pr on pr.competition_id=r.competition_id
      where r.user_id=u and pr.release_channel=ch),0),
    'leaderboard',jsonb_build_object('scope','visible_members_current_release','rows',board),
    'competitions',coalesce((select jsonb_agg(to_jsonb(x)-'prize') from (
      select c.*,pr.release_channel from beta_fantasy.competitions c join beta_fantasy.production_rounds pr on pr.competition_id=c.id
      where pr.release_channel=ch order by c.locks_at desc,c.id limit 50) x),'[]'),
    'entries',coalesce((select jsonb_agg(to_jsonb(x)) from (
      select e.* from beta_fantasy.entries e join beta_fantasy.production_rounds pr on pr.competition_id=e.competition_id
      where e.user_id=u and pr.release_channel=ch order by e.updated_at desc,e.id limit 50) x),'[]'),
    'results',coalesce((select jsonb_agg(to_jsonb(x)) from (
      select r.competition_id,r.user_id,r.score,r.rank,r.championship_points,pr.release_channel
      from beta_fantasy.results r join beta_fantasy.production_rounds pr on pr.competition_id=r.competition_id
      join beta_fantasy.competitions c on c.id=r.competition_id where r.user_id=u and pr.release_channel=ch
      order by c.locks_at desc,r.competition_id limit 100) x),'[]'));
  state:=jsonb_set(state,'{rewards}',(state->'rewards') || jsonb_build_object(
    'release_channel',ch,
    'points',coalesce((select sum(points) from beta_fantasy.daily_claims where user_id=u and release_channel=ch),0),
    'history',coalesce((select jsonb_agg(to_jsonb(x)) from (
      select period,points,policy_version,pack_id,card_outcome,created_at,release_channel
      from beta_fantasy.daily_claims where user_id=u order by period desc limit 90) x),'[]')));
  return state;
end $$;
-- Renaming must not leave the previous public entry points callable by runtime.
revoke all on all functions in schema beta_fantasy from public,anon,authenticated,docked_beta_app;
grant execute on function beta_fantasy.command(text,jsonb,uuid),beta_fantasy.read_state(),beta_fantasy.production_command(text,jsonb,uuid),beta_fantasy.production_read_state() to docked_beta_app;


-- Browsers cannot reach the beta schemas, even if someone exposes a schema in
-- PostgREST. Only the exact server role has the enumerated reviewed privileges.
revoke all on schema beta_public,beta_private,beta_fantasy from public,anon,authenticated,docked_app;
revoke all on all tables in schema beta_public,beta_private,beta_fantasy from public,anon,authenticated,docked_app;
revoke all on all functions in schema beta_public,beta_private,beta_fantasy from public,anon,authenticated,docked_app;
revoke all on all sequences in schema beta_public,beta_private,beta_fantasy from public,anon,authenticated,docked_app;
alter default privileges in schema beta_public,beta_private,beta_fantasy revoke execute on functions from public;
-- Keep dormant. Initialization and approved policy/admission are separate gates.
update beta_fantasy.settings set enabled=false;
-- A beta release can never be relabelled official. Existing beta history stays beta.
alter table beta_fantasy.production_releases add constraint beta_only check(channel='beta');
